#!/usr/bin/env bash
# STBOX single-file bundle (generated by build.sh)
SST_BUNDLED=1
SST_VERSION="0.5.0"
# STBOX（SSH Tool Box）入口：解析全局参数，加载框架后按模块分发
set -uo pipefail

# 解析软链接，确保通过 /usr/local/bin/st 启动时仍能找到真实安装目录
SST_SOURCE=${BASH_SOURCE[0]}
while [[ -L $SST_SOURCE ]]; do
  SST_LINK_DIR=$(cd -- "$(dirname -- "$SST_SOURCE")" && pwd -P)
  SST_SOURCE=$(readlink "$SST_SOURCE")
  [[ $SST_SOURCE == /* ]] || SST_SOURCE="$SST_LINK_DIR/$SST_SOURCE"
done
SST_HOME=$(cd -- "$(dirname -- "$SST_SOURCE")" && pwd -P)
if [[ ${SST_BUNDLED:-0} -eq 1 ]]; then
  [[ $SST_SOURCE == /* ]] || SST_SOURCE="$SST_HOME/$(basename -- "$SST_SOURCE")"
  SST_ENTRY="$SST_SOURCE"
else
  SST_ENTRY="$SST_HOME/st.sh"
fi
export SST_HOME SST_ENTRY
export SST_YES=${SST_YES:-0}
export SST_NO_COLOR=${SST_NO_COLOR:-0}
export SST_PLAIN=${SST_PLAIN:-0}
export SST_UI_ASCII=${SST_UI_ASCII:-0}

# 先消费全局开关，再加载核心（颜色等依赖这些变量）
args=()
for arg in "$@"; do
  case $arg in
    --yes|-y) SST_YES=1 ;;
    --no-color) SST_NO_COLOR=1 ;;
    --plain)
      SST_PLAIN=1
      SST_NO_COLOR=1
      SST_UI_ASCII=1
      ;;
    *) args+=("$arg") ;;
  esac
done
export SST_PLAIN SST_UI_ASCII
set -- "${args[@]}"



# --- core/ui.sh ---
# 界面层：能力检测、配色、Unicode/ASCII 符号、显示宽度、面板与菜单组件
# 由 core/common.sh 自动加载；业务模块只使用 common.sh 的 section/kv/info 等封装。

UI_COLOR_ENABLED=0
UI_UNICODE=0
UI_UTF8_LOCALE=0
UI_WIDTH=${COLUMNS:-80}
UI_FRAME_MAX=${SST_UI_FRAME_MAX:-72}
UI_CHAR_WIDTH=1

# ---------- 能力检测 ----------
ui_locale_utf8() {
  local charmap=${LC_ALL:-${LC_CTYPE:-${LANG:-}}}
  case $charmap in
    *UTF-8*|*utf-8*|*utf8*|*UTF8*) return 0 ;;
  esac
  charmap=$(locale charmap 2>/dev/null || true)
  [[ $charmap == UTF-8 ]]
}

ui_has_utf8() {
  [[ ${SST_UI_ASCII:-0} -eq 1 ]] && return 1
  [[ ${TERM:-dumb} == dumb ]] && return 1
  ui_locale_utf8
}

ui_has_color() {
  [[ ${SST_NO_COLOR:-0} -eq 1 ]] && return 1
  [[ ${SST_PLAIN:-0} -eq 1 ]] && return 1
  [[ -n ${NO_COLOR:-} ]] && return 1
  [[ -t 1 ]] || return 1
  [[ ${TERM:-dumb} == dumb ]] && return 1
  return 0
}

ui_detect_width() {
  local width=${COLUMNS:-}
  if ! [[ $width =~ ^[0-9]+$ ]] || (( width < 20 )); then
    width=$(tput cols 2>/dev/null || true)
  fi
  [[ $width =~ ^[0-9]+$ ]] && (( width > 1 )) || width=80
  UI_WIDTH=$width
}

ui_set_palette() {
  if (( ! UI_COLOR_ENABLED )); then
    C_RESET='' C_BOLD='' C_DIM=''
    C_ACCENT='' C_INFO='' C_OK='' C_WARN='' C_ERROR='' C_MUTED='' C_HIGHLIGHT=''
    C_GREEN='' C_RED='' C_YELLOW='' C_CYAN='' C_BLUE='' C_MAGENTA=''
    return 0
  fi

  local colors=8
  if command -v tput >/dev/null 2>&1; then
    colors=$(tput colors 2>/dev/null || printf '8')
  fi
  [[ $colors =~ ^[0-9]+$ ]] || colors=8

  C_RESET=$'\033[0m'
  C_BOLD=$'\033[1m'
  C_DIM=$'\033[2m'
  if (( colors >= 256 )); then
    C_ACCENT=$'\033[38;5;45m'
    C_INFO=$'\033[38;5;75m'
    C_OK=$'\033[38;5;114m'
    C_WARN=$'\033[38;5;179m'
    C_ERROR=$'\033[38;5;203m'
    C_MUTED=$'\033[38;5;244m'
    C_HIGHLIGHT=$'\033[38;5;223m'
  else
    C_ACCENT=$'\033[36m'
    C_INFO=$'\033[36m'
    C_OK=$'\033[32m'
    C_WARN=$'\033[33m'
    C_ERROR=$'\033[31m'
    C_MUTED=$'\033[2m'
    C_HIGHLIGHT=$'\033[1;36m'
  fi
  C_GREEN=$C_OK
  C_RED=$C_ERROR
  C_YELLOW=$C_WARN
  C_CYAN=$C_ACCENT
  C_BLUE=$C_INFO
  C_MAGENTA=$C_ACCENT
}

ui_set_symbols() {
  if (( UI_UNICODE )); then
    UI_SYM_BAR='│'
    UI_SYM_H='─'
    UI_BOX_TL='╭'
    UI_BOX_TR='╮'
    UI_BOX_BL='╰'
    UI_BOX_BR='╯'
    UI_BOX_V='│'
    UI_SYM_OK='✓'
    UI_SYM_WARN='!'
    UI_SYM_ERR='✗'
    UI_SYM_INFO='·'
    UI_SYM_ARROW='→'
    UI_SYM_BULLET='·'
    UI_SYM_PROMPT='›'
    UI_SYM_ELLIPSIS='…'
  else
    UI_SYM_BAR='|'
    UI_SYM_H='-'
    UI_BOX_TL='+'
    UI_BOX_TR='+'
    UI_BOX_BL='+'
    UI_BOX_BR='+'
    UI_BOX_V='|'
    UI_SYM_OK='[OK]'
    UI_SYM_WARN='[!]'
    UI_SYM_ERR='[X]'
    UI_SYM_INFO='[i]'
    UI_SYM_ARROW='->'
    UI_SYM_BULLET='-'
    UI_SYM_PROMPT='>'
    UI_SYM_ELLIPSIS='...'
  fi
}

ui_init() {
  if ui_locale_utf8; then UI_UTF8_LOCALE=1; else UI_UTF8_LOCALE=0; fi
  if ui_has_utf8; then UI_UNICODE=1; else UI_UNICODE=0; fi
  [[ ${SST_PLAIN:-0} -eq 1 ]] && UI_UNICODE=0
  ui_detect_width
  if ui_has_color; then UI_COLOR_ENABLED=1; else UI_COLOR_ENABLED=0; fi
  ui_set_palette
  ui_set_symbols
}

# ---------- 显示宽度 ----------
# 结果写入 UI_CHAR_WIDTH，避免逐字符启动子进程
ui_char_width() {
  local cp=$1
  UI_CHAR_WIDTH=1
  if (( cp <= 0 )); then
    UI_CHAR_WIDTH=0
    return 0
  fi
  if (( cp < 32 || (cp >= 0x7f && cp < 0xa0) )); then
    UI_CHAR_WIDTH=0
    return 0
  fi
  if (( cp >= 0x300 && cp <= 0x36f )) \
    || (( cp == 0x200b || cp == 0x200c || cp == 0x200d )) \
    || (( cp >= 0xfe00 && cp <= 0xfe0f )); then
    UI_CHAR_WIDTH=0
    return 0
  fi
  if (( cp >= 0x1100 && cp <= 0x115f )) \
    || (( cp >= 0x2e80 && cp <= 0x303e )) \
    || (( cp >= 0x3041 && cp <= 0x33ff )) \
    || (( cp >= 0x3400 && cp <= 0x4dbf )) \
    || (( cp >= 0x4e00 && cp <= 0x9fff )) \
    || (( cp >= 0xa000 && cp <= 0xa4cf )) \
    || (( cp >= 0xa960 && cp <= 0xa97f )) \
    || (( cp >= 0xac00 && cp <= 0xd7a3 )) \
    || (( cp >= 0xf900 && cp <= 0xfaff )) \
    || (( cp >= 0xfe10 && cp <= 0xfe19 )) \
    || (( cp >= 0xfe30 && cp <= 0xfe6f )) \
    || (( cp >= 0xff00 && cp <= 0xff60 )) \
    || (( cp >= 0xffe0 && cp <= 0xffe6 )) \
    || (( cp >= 0x1f300 && cp <= 0x1f64f )) \
    || (( cp >= 0x1f900 && cp <= 0x1f9ff )) \
    || (( cp >= 0x20000 && cp <= 0x3fffd )); then
    UI_CHAR_WIDTH=2
  fi
}

ui_text_width() {
  local text=${1:-}
  local i ch cp width=0
  if (( ! UI_UTF8_LOCALE )); then
    printf '%d' "${#text}"
    return 0
  fi
  for (( i = 0; i < ${#text}; i++ )); do
    ch=${text:i:1}
    printf -v cp '%d' "'$ch" 2>/dev/null || cp=0
    ui_char_width "$cp"
    width=$((width + UI_CHAR_WIDTH))
  done
  printf '%d' "$width"
}

ui_pad() {
  local text=${1:-} width=${2:-0}
  local current
  current=$(ui_text_width "$text")
  if (( current < width )); then
    printf '%s%*s' "$text" "$((width - current))" ''
  else
    printf '%s' "$text"
  fi
}

ui_fit() {
  local text=${1:-} max=${2:-0}
  [[ -n $text ]] || return 0
  [[ $max =~ ^[0-9]+$ ]] || { printf '%s' "$text"; return 0; }
  local total
  total=$(ui_text_width "$text")
  (( total <= max )) && { printf '%s' "$text"; return 0; }

  local ell=$UI_SYM_ELLIPSIS
  local ell_width target
  ell_width=$(ui_text_width "$ell")
  target=$((max - ell_width))
  if (( target < 1 )); then
    printf '%s' "$ell"
    return 0
  fi

  local i ch cp width=0 out=''
  for (( i = 0; i < ${#text}; i++ )); do
    ch=${text:i:1}
    if (( UI_UTF8_LOCALE )); then
      printf -v cp '%d' "'$ch" 2>/dev/null || cp=0
      ui_char_width "$cp"
    else
      UI_CHAR_WIDTH=1
    fi
    (( width + UI_CHAR_WIDTH > target )) && break
    out+=$ch
    width=$((width + UI_CHAR_WIDTH))
  done
  printf '%s%s' "$out" "$ell"
}

ui_wrap_text() {
  local text=${1:-} max=${2:-0}
  [[ -n $text ]] || { printf '\n'; return 0; }
  if ! [[ $max =~ ^[0-9]+$ ]] || (( max < 4 )); then
    printf '%s\n' "$text"
    return 0
  fi

  local i ch cp width=0 line=''
  for (( i = 0; i < ${#text}; i++ )); do
    ch=${text:i:1}
    if (( UI_UTF8_LOCALE )); then
      printf -v cp '%d' "'$ch" 2>/dev/null || cp=0
      ui_char_width "$cp"
    else
      UI_CHAR_WIDTH=1
    fi
    if (( width + UI_CHAR_WIDTH > max )); then
      printf '%s\n' "$line"
      line=''
      width=0
    fi
    line+=$ch
    width=$((width + UI_CHAR_WIDTH))
  done
  [[ -n $line ]] && printf '%s\n' "$line"
}

ui_frame_width() {
  local width=${UI_WIDTH:-80}
  (( width > UI_FRAME_MAX )) && width=$UI_FRAME_MAX
  (( width < 20 )) && width=20
  printf '%d' "$width"
}

# ---------- 基础输出 ----------
ui_status() {
  local type=$1
  shift
  local color prefix
  case $type in
    ok)
      color=$C_OK
      if (( UI_UNICODE )); then prefix="$UI_SYM_OK 完成"; else prefix='[完成]'; fi
      ;;
    warn)
      color=$C_WARN
      if (( UI_UNICODE )); then prefix="$UI_SYM_WARN 注意"; else prefix='[注意]'; fi
      ;;
    err)
      color=$C_ERROR
      if (( UI_UNICODE )); then prefix="$UI_SYM_ERR 错误"; else prefix='[错误]'; fi
      ;;
    *)
      color=$C_INFO
      if (( UI_UNICODE )); then prefix="$UI_SYM_INFO 信息"; else prefix='[信息]'; fi
      ;;
  esac
  printf '%s%s%s %s\n' "$color" "$prefix" "$C_RESET" "$*"
}

ui_section() {
  local title=${1:-} meta=${2:-}
  local used avail max meta_width spaces
  printf '\n%s%s%s %s%s%s' "$C_ACCENT" "$UI_SYM_BAR" "$C_RESET" "$C_BOLD" "$title" "$C_RESET"
  if [[ -n $meta ]]; then
    used=$((2 + $(ui_text_width "$title")))
    avail=$((UI_WIDTH - 1))
    meta_width=$(ui_text_width "$meta")
    max=$((avail - used - 2))
    if (( max >= 4 && meta_width > max )); then
      meta=$(ui_fit "$meta" "$max")
      meta_width=$(ui_text_width "$meta")
    fi
    if (( max >= 4 )); then
      spaces=$((avail - used - meta_width))
      (( spaces > 0 )) && printf '%*s%s%s%s' "$spaces" '' "$C_DIM" "$meta" "$C_RESET"
    fi
  fi
  printf '\n'
}

ui_rule() {
  local width i
  width=$(ui_frame_width)
  printf '%s' "$C_DIM"
  for (( i = 0; i < width; i++ )); do
    printf '%s' "$UI_SYM_H"
  done
  printf '%s\n' "$C_RESET"
}

ui_kv() {
  local label=${1:-} value=${2:-} padded
  padded=$(ui_pad "$label" 22)
  printf '  %s%s%s  %s\n' "$C_DIM" "$padded" "$C_RESET" "$value"
}

ui_group() {
  printf '\n  %s%s %s%s\n' "$C_DIM" "$UI_SYM_BULLET" "$1" "$C_RESET"
}

ui_menu_item() {
  local num=$1 title=$2 desc=${3:-}
  local title_max title_shown title_width avail shown
  title_max=$((UI_WIDTH - 6))
  (( title_max < 6 )) && title_max=6
  title_shown=$(ui_fit "$title" "$title_max")
  title_width=$(ui_text_width "$title_shown")
  printf '  %s%2d%s  %s%s%s' "$C_ACCENT" "$num" "$C_RESET" "$C_BOLD" "$title_shown" "$C_RESET"
  if [[ -n $desc ]]; then
    avail=$((UI_WIDTH - 11 - title_width))
    if (( avail > 5 )); then
      shown=$(ui_fit "$desc" "$avail")
      printf '  %s%s %s%s\n' "$C_DIM" "$UI_SYM_BULLET" "$shown" "$C_RESET"
    else
      printf '\n'
    fi
  else
    printf '\n'
  fi
}

ui_menu_footer() {
  local label=${1:-返回}
  printf '\n  %s0%s  %s\n\n' "$C_ACCENT" "$C_RESET" "$label"
}

ui_menu_list() {
  local list=$1 zero=${2:-返回} i=0 line
  while IFS= read -r line; do
    [[ -n $line ]] || continue
    i=$((i + 1))
    ui_menu_item "$i" "$line"
  done <<<"$list"
  ui_menu_footer "$zero"
}

ui_menu_option() {
  local key=$1 label=$2
  printf '  %s%2s%s  %s\n' "$C_ACCENT" "$key" "$C_RESET" "$label"
}

ui_prompt_text() {
  local text=${1:-请选择}
  printf '%s%s%s %s%s%s ' "$C_ACCENT" "$text" "$C_RESET" "$C_ACCENT" "$UI_SYM_PROMPT" "$C_RESET"
}

ui_read_choice() {
  local prompt=${1:-请选择}
  UI_CHOICE=''
  read -r -p "$(ui_prompt_text "$prompt")" UI_CHOICE || return 1
  return 0
}

ui_panel_color() {
  local color=$1 title=$2 line width inner top fill content i
  width=$(ui_frame_width)
  inner=$((width - 4))
  (( inner < 8 )) && inner=8
  title=$(ui_fit "$title" $((width - 6)))

  fill=$((width - 5 - $(ui_text_width "$title")))
  (( fill < 0 )) && fill=0
  top="${UI_BOX_TL}${UI_SYM_H} ${C_BOLD}${title}${C_RESET}${color} "
  for (( i = 0; i < fill; i++ )); do top+="$UI_SYM_H"; done
  top+="$UI_BOX_TR"
  printf '%s%s%s\n' "$color" "$top" "$C_RESET"

  shift 2
  for line in "$@"; do
    while IFS= read -r content; do
      content=$(ui_pad "$content" "$inner")
      printf '%s%s%s %s %s%s%s\n' "$color" "$UI_BOX_V" "$C_RESET" "$content" "$color" "$UI_BOX_V" "$C_RESET"
    done < <(ui_wrap_text "$line" "$inner")
  done

  printf '%s' "$color"
  printf '%s' "$UI_BOX_BL"
  for (( i = 0; i < width - 2; i++ )); do printf '%s' "$UI_SYM_H"; done
  printf '%s%s\n' "$UI_BOX_BR" "$C_RESET"
}

ui_panel() { ui_panel_color "$C_ACCENT" "$@"; }

ui_danger_panel() { ui_panel_color "$C_ERROR" "$@"; }

ui_confirm_danger() {
  local message=$1 impact=${2:-} rollback=${3:-}
  [[ ${SST_YES:-0} -eq 1 ]] && return 0
  local -a lines=("$message")
  [[ -n $impact ]] && lines+=("影响：$impact")
  [[ -n $rollback ]] && lines+=("回滚：$rollback")
  ui_danger_panel "危险操作" "${lines[@]}"
  confirm "确认继续？"
}

ui_init

# --- core/common.sh ---
# 基础层：日志、权限、系统探测、包管理、交互工具（界面能力见 ui.sh）
# 由 st.sh 加载，不独立执行。

if ! declare -F ui_init >/dev/null 2>&1; then
  # shellcheck source=ui.sh
  source "$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)/ui.sh"
fi

if [[ ${SST_BUNDLED:-0} -eq 1 ]]; then
  if [[ ${EUID:-1} -eq 0 ]]; then
    SST_STATE_DIR=${STBOX_STATE_DIR:-/var/lib/stbox}
  else
    SST_STATE_DIR=${STBOX_STATE_DIR:-${XDG_DATA_HOME:-${HOME:-/root}/.local/share}/stbox}
  fi
  SST_CONFIG_DIR="$SST_STATE_DIR/config"
  SST_DATA_DIR="$SST_STATE_DIR/data"
  SST_LOG_DIR="$SST_STATE_DIR/logs"
else
  SST_STATE_DIR="$SST_HOME"
  SST_CONFIG_DIR="$SST_HOME/config"
  SST_DATA_DIR="$SST_HOME/data"
  SST_LOG_DIR="$SST_HOME/logs"
fi
SST_LOG="$SST_LOG_DIR/sst.log"
export SST_STATE_DIR
ARCH=${ARCH:-$(uname -m)}

sst_init_dirs() {
  mkdir -p "$SST_CONFIG_DIR" "$SST_DATA_DIR/backups" "$SST_DATA_DIR/apps" "$SST_LOG_DIR" 2>/dev/null || true
  [[ ${SST_BUNDLED:-0} -eq 1 ]] && chmod 700 "$SST_STATE_DIR" 2>/dev/null || true
  chmod 600 "$SST_LOG" 2>/dev/null || true
}

# ---------- 输出与日志 ----------
sst_log() {
  local level=$1
  shift
  ( umask 077; printf '%s [%s] %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$level" "$*" >>"$SST_LOG" ) 2>/dev/null || true
}
info() { ui_status info "$*"; sst_log INFO "$*"; }
ok()   { ui_status ok "$*"; sst_log OK "$*"; }
warn() { ui_status warn "$*" >&2; sst_log WARN "$*"; }
err()  { ui_status err "$*" >&2; sst_log ERROR "$*"; }
die()  { err "$*"; exit 1; }

# 敏感信息仅输出到终端，不写入日志
secret_info() { ui_status info "$*"; }
secret_ok()   { ui_status ok "$*"; }

section() { ui_section "${1:-}" "${2:-}"; }
kv()      { ui_kv "${1:-}" "${2:-}"; }
hr()      { ui_rule; }

# ---------- 通用工具 ----------
have() { command -v "$1" >/dev/null 2>&1; }

confirm() {
  local prompt=${1:-"确认执行该操作？"} answer
  [[ ${SST_YES:-0} -eq 1 ]] && return 0
  [[ -t 0 ]] || die "非交互环境请追加 --yes 参数"
  read -r -p "$prompt [y/N] " answer || return 1
  case ${answer,,} in
    y|yes|是) return 0 ;;
    *) return 1 ;;
  esac
}

pause() {
  [[ -t 0 ]] || return 0
  read -r -p "按回车继续…" _ || true
}

ask() {
  local prompt=$1 default=${2:-} answer
  read -r -p "$prompt${default:+ [$default]}: " answer || true
  printf '%s\n' "${answer:-$default}"
}

valid_port() {
  [[ ${1:-} =~ ^[0-9]+$ ]] && (( 1 <= $1 && $1 <= 65535 ))
}

# 通过 /dev/tcp 检测远端端口（需 timeout 命令）
tcp_check() {
  local host=$1 port=$2 wait=${3:-3}
  have timeout || return 1
  timeout "$wait" bash -c "exec 3<>/dev/tcp/$host/$port" >/dev/null 2>&1
}

bytes_h() {
  awk -v b="${1:-0}" 'BEGIN{split("B KB MB GB TB PB",u," ");i=1;while(b>=1024&&i<6){b/=1024;i++}printf "%.2f %s",b,u[i]}'
}

# ---------- 权限 ----------
require_root() {
  [[ ${EUID:-1} -eq 0 ]] && return 0
  if have sudo && [[ -t 0 ]]; then
    warn "该操作需要 root 权限，正在使用 sudo 重新执行…"
    exec sudo -E env SST_YES="$SST_YES" SST_NO_COLOR="$SST_NO_COLOR" \
      SST_UI_ASCII="${SST_UI_ASCII:-0}" SST_PLAIN="${SST_PLAIN:-0}" \
      bash "$SST_ENTRY" "${SST_ARGS[@]}"
  fi
  die "需要 root 权限，请使用 sudo $SST_ENTRY ${SST_ARGS[*]:-}"
}

# ---------- 系统探测 ----------
sst_detect_os() {
  OS_ID=unknown
  OS_NAME=Linux
  OS_VER=''
  OS_LIKE=''
  ARCH=$(uname -m)

  if [[ -r /etc/os-release ]]; then
    OS_ID=$(. /etc/os-release; printf '%s' "${ID:-unknown}")
    OS_NAME=$(. /etc/os-release; printf '%s' "${PRETTY_NAME:-${NAME:-Linux}}")
    OS_VER=$(. /etc/os-release; printf '%s' "${VERSION_ID:-}")
    OS_LIKE=$(. /etc/os-release; printf '%s' "${ID_LIKE:-}")
  fi

  if have apt-get; then PKG=apt
  elif have dnf; then PKG=dnf
  elif have yum; then PKG=yum
  elif have apk; then PKG=apk
  elif have pacman; then PKG=pacman
  elif have zypper; then PKG=zypper
  else PKG=unknown
  fi

  if [[ -d /run/systemd/system ]] && have systemctl; then INIT=systemd
  elif have rc-service; then INIT=openrc
  else INIT=sysv
  fi

  VIRT=''
  if have systemd-detect-virt; then
    VIRT=$(systemd-detect-virt 2>/dev/null || true)
    VIRT=${VIRT%%$'\n'*}
  fi
  [[ -n $VIRT ]] || VIRT=unknown
}

# ---------- 包管理 ----------
pkg_update() {
  case ${PKG:-unknown} in
    apt) DEBIAN_FRONTEND=noninteractive apt-get update -qq ;;
    dnf) dnf makecache -q ;;
    yum) yum makecache -q ;;
    apk) apk update -q ;;
    pacman) pacman -Sy --noconfirm ;;
    zypper) zypper -q refresh ;;
    *) die "当前系统不支持自动安装依赖（未知包管理器）" ;;
  esac
}

pkg_install() {
  [[ $# -gt 0 ]] || return 0
  case ${PKG:-unknown} in
    apt) DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "$@" ;;
    dnf|yum) "$PKG" install -y -q "$@" ;;
    apk) apk add --no-cache "$@" ;;
    pacman) pacman -S --noconfirm --needed "$@" ;;
    zypper) zypper -n install "$@" ;;
    *) die "当前系统不支持自动安装依赖（未知包管理器）" ;;
  esac
}

pkg_clean() {
  case ${PKG:-unknown} in
    apt) apt-get clean; rm -rf /var/lib/apt/lists/* 2>/dev/null || true ;;
    dnf|yum) "$PKG" clean all ;;
    apk) apk cache clean ;;
    pacman) pacman -Sc --noconfirm ;;
    zypper) zypper clean -a ;;
    *) return 0 ;;
  esac
}

pkg_upgrade() {
  case ${PKG:-unknown} in
    apt) DEBIAN_FRONTEND=noninteractive apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get upgrade -y ;;
    dnf) dnf upgrade -y ;;
    yum) yum upgrade -y ;;
    apk) apk update && apk upgrade ;;
    pacman) pacman -Syu --noconfirm ;;
    zypper) zypper -n update ;;
    *) die "当前系统不支持自动更新" ;;
  esac
}

pkg_remove() {
  [[ $# -gt 0 ]] || return 0
  case ${PKG:-unknown} in
    apt) DEBIAN_FRONTEND=noninteractive apt-get purge -y "$@" && apt-get autoremove -y ;;
    dnf|yum) "$PKG" remove -y "$@" && "$PKG" autoremove -y ;;
    apk) apk del "$@" ;;
    pacman) pacman -Rns --noconfirm "$@" ;;
    zypper) zypper -n remove "$@" ;;
    *) die "当前系统不支持自动卸载软件包" ;;
  esac
}

ensure_tool() {
  local cmd=$1
  shift
  have "$cmd" && return 0
  [[ $# -gt 0 ]] || die "缺少命令：$cmd，请手动安装"
  info "安装依赖：$*"
  pkg_update
  pkg_install "$@"
  have "$cmd" || die "依赖安装失败：$cmd"
}

# ---------- 服务管理 ----------
svc_enable() {
  case ${INIT:-sysv} in
    systemd) systemctl enable --now "$1" ;;
    openrc) rc-update add "$1" default >/dev/null 2>&1 || true; rc-service "$1" start ;;
    *) service "$1" start ;;
  esac
}

svc_restart() {
  case ${INIT:-sysv} in
    systemd) systemctl restart "$1" ;;
    openrc) rc-service "$1" restart ;;
    *) service "$1" restart ;;
  esac
}

svc_active() {
  case ${INIT:-sysv} in
    systemd) systemctl is-active --quiet "$1" ;;
    openrc) rc-service "$1" status >/dev/null 2>&1 ;;
    *) service "$1" status >/dev/null 2>&1 ;;
  esac
}

# ---------- 网络信息 ----------
get_public_ip() {
  local cache="$SST_DATA_DIR/public_ip" ip=''
  if [[ -s $cache ]]; then
    local now mtime
    now=$(date +%s)
    mtime=$(stat -c %Y "$cache" 2>/dev/null || echo 0)
    if (( now - mtime < 600 )); then
      cat "$cache"
      return 0
    fi
  fi
  ip=$(curl -4 -fsS --max-time 4 https://api.ipify.org 2>/dev/null \
    || curl -4 -fsS --max-time 4 https://ifconfig.me 2>/dev/null || true)
  if [[ -n $ip ]]; then
    printf '%s\n' "$ip" >"$cache" 2>/dev/null || true
  fi
  printf '%s\n' "${ip:-未知}"
}

# 下载文件；GitHub raw 不可达时自动切换 jsDelivr / gh-proxy 镜像
download_with_fallback() {
  local url=$1 out=$2 max_time=${3:-60} alt='' first_time
  first_time=$max_time
  if [[ $url == https://raw.githubusercontent.com/* ]] && (( first_time > 15 )); then
    first_time=15
  elif [[ $url == *github.com* ]] && (( first_time > 25 )); then
    first_time=25
  fi

  if curl -fL --connect-timeout 6 --max-time "$first_time" -o "$out" "$url" 2>/dev/null; then
    return 0
  fi
  rm -f "$out"

  if [[ $url == https://raw.githubusercontent.com/* ]]; then
    local rest=${url#https://raw.githubusercontent.com/}
    local owner=${rest%%/*}
    rest=${rest#*/}
    local repo=${rest%%/*}
    rest=${rest#*/}
    local branch=${rest%%/*}
    rest=${rest#*/}
    alt="https://cdn.jsdelivr.net/gh/${owner}/${repo}@${branch}/${rest}"
  fi

  if [[ -n $alt ]]; then
    warn "原始地址不可达，尝试镜像：$alt"
    if curl -fL --connect-timeout 6 --max-time "$max_time" -o "$out" "$alt" 2>/dev/null; then
      return 0
    fi
    rm -f "$out"
  fi

  if [[ $url == *github.com* || $url == *githubusercontent.com* ]]; then
    alt="https://gh-proxy.com/${url}"
    warn "尝试 GitHub 代理：$alt"
    if curl -fL --connect-timeout 6 --max-time "$max_time" -o "$out" "$alt" 2>/dev/null; then
      return 0
    fi
    rm -f "$out"
  fi
  return 1
}

get_mem_info() {
  # 输出：总量/已用/可用（MB），优先 free，缺失时读取 /proc/meminfo
  local out
  out=$(free -m 2>/dev/null | awk 'NR==2 {print $2, $3, ($7 != "" ? $7 : $4)}')
  if [[ -n $out ]]; then
    printf '%s\n' "$out"
    return 0
  fi
  awk '
    /MemTotal/ { total = $2 }
    /MemAvailable/ { avail = $2 }
    /MemFree/ { free = $2 }
    END {
      if (total == "") { print ""; exit }
      if (avail == "") avail = free
      used = total - avail
      printf "%d %d %d\n", total / 1024, used / 1024, avail / 1024
    }
  ' /proc/meminfo 2>/dev/null
}

get_rx_tx() {
  # 输出：自开机以来累计接收/发送字节数
  awk -F: '/^[ ]*[a-zA-Z]/ && $1 !~ /lo/ {
        split($2, a, " ");
        rx += a[1]; tx += a[9];
      } END { printf "%d %d\n", rx, tx }' /proc/net/dev 2>/dev/null
}

get_load() {
  cut -d' ' -f1-3 /proc/loadavg 2>/dev/null || echo "未知"
}

get_cpu_model() {
  if have lscpu; then
    lscpu 2>/dev/null | awk -F: '/Model name/{gsub(/^ +/,"",$2); print $2; exit}'
  else
    awk -F: '/model name/{gsub(/^ +/,"",$2); print $2; exit}' /proc/cpuinfo 2>/dev/null
  fi
}

get_uptime_human() {
  local secs
  secs=$(cut -d. -f1 /proc/uptime 2>/dev/null) || { echo "未知"; return; }
  local d=$(( secs / 86400 )) h=$(( secs % 86400 / 3600 )) m=$(( secs % 3600 / 60 ))
  printf '%d 天 %d 小时 %d 分' "$d" "$h" "$m"
}

# --- core/config.sh ---
# 配置层：键值配置的读取与写入（config/settings.conf）

cfg_file() { printf '%s/settings.conf' "$SST_CONFIG_DIR"; }

cfg_get() {
  local key=$1 default=${2:-} value='' f
  f=$(cfg_file)
  if [[ -r $f ]]; then
    value=$(grep -E "^${key}=" "$f" 2>/dev/null | tail -n 1 | cut -d= -f2-)
  fi
  printf '%s\n' "${value:-$default}"
}

cfg_set() {
  local key=$1 value=$2 f tmp
  [[ $key =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || die "非法配置键：$key"
  [[ $value != *$'\n'* && $value != *$'\r'* ]] || die "配置值不能包含换行符：$key"
  f=$(cfg_file)
  mkdir -p "$SST_CONFIG_DIR" 2>/dev/null || die "无法创建配置目录：$SST_CONFIG_DIR"
  tmp=$(mktemp) || die "无法创建临时文件"
  if [[ -r $f ]]; then
    grep -vE "^${key}=" "$f" >"$tmp" 2>/dev/null || true
  fi
  printf '%s=%s\n' "$key" "$value" >>"$tmp"
  mv "$tmp" "$f"
  chmod 600 "$f" 2>/dev/null || true
}

cfg_show() {
  local f
  f=$(cfg_file)
  section "配置信息"
  kv "配置文件" "$f"
  kv "数据目录" "$SST_DATA_DIR"
  kv "日志文件" "$SST_LOG"
  if [[ -r $f ]]; then
    hr
    cat "$f"
  else
    warn "暂无配置，运行相关功能后会自动生成"
  fi
}

# --- core/wizard.sh ---
# 开荒向导状态与报告

SST_WIZARD_DIR="$SST_DATA_DIR/init"
SST_WIZARD_STATE="$SST_WIZARD_DIR/state.conf"
SST_WIZARD_STEPS=(preflight disk basics accounts ssh firewall hardening report)

wizard_init() {
  mkdir -p "$SST_WIZARD_DIR" 2>/dev/null || true
  chmod 700 "$SST_WIZARD_DIR" 2>/dev/null || true
  if [[ ! -f $SST_WIZARD_STATE ]]; then
    {
      printf 'VERSION=2\n'
      printf 'STARTED_AT=%s\n' "$(date '+%F %T')"
      for s in "${SST_WIZARD_STEPS[@]}"; do
        printf 'STEP_%s=pending\n' "$s"
      done
    } >"$SST_WIZARD_STATE"
    chmod 600 "$SST_WIZARD_STATE" 2>/dev/null || true
  else
    local s
    for s in "${SST_WIZARD_STEPS[@]}"; do
      grep -qE "^STEP_${s}=" "$SST_WIZARD_STATE" 2>/dev/null || printf 'STEP_%s=pending\n' "$s" >>"$SST_WIZARD_STATE"
    done
    grep -qE '^VERSION=' "$SST_WIZARD_STATE" || printf 'VERSION=2\n' >>"$SST_WIZARD_STATE"
  fi
}

wizard_get() {
  local key=$1 default=${2:-}
  [[ -r $SST_WIZARD_STATE ]] || { printf '%s\n' "$default"; return 0; }
  local value
  value=$(grep -E "^${key}=" "$SST_WIZARD_STATE" 2>/dev/null | tail -n 1 | cut -d= -f2-)
  printf '%s\n' "${value:-$default}"
}

wizard_set() {
  local key=$1 value=$2 tmp
  [[ $key =~ ^[A-Za-z0-9_]+$ ]] || return 1
  [[ $value != *$'\n'* && $value != *$'\r'* ]] || { warn "状态值不能包含换行符：$key"; return 1; }
  wizard_init
  tmp=$(mktemp)
  grep -vE "^${key}=" "$SST_WIZARD_STATE" >"$tmp" 2>/dev/null || true
  printf '%s=%s\n' "$key" "$value" >>"$tmp"
  mv "$tmp" "$SST_WIZARD_STATE"
  chmod 600 "$SST_WIZARD_STATE" 2>/dev/null || true
}

wizard_mark() {
  local step=$1 status=${2:-done}
  wizard_set "STEP_${step}" "$status"
  wizard_set "STEP_${step}_AT" "$(date '+%F %T')"
}

wizard_step_status() {
  wizard_get "STEP_${1}" pending
}

wizard_step_label() {
  case $1 in
    preflight) printf '服务器预检' ;;
    disk) printf '磁盘检测与挂载' ;;
    basics) printf '基础信息' ;;
    accounts) printf '账户设置' ;;
    ssh) printf 'SSH 安全' ;;
    firewall) printf '防火墙与防护' ;;
    hardening) printf '系统加固' ;;
    report) printf '验收报告' ;;
    *) printf '%s' "$1" ;;
  esac
}

wizard_step_short() {
  case $1 in
    preflight) printf '预检' ;;
    disk) printf '磁盘' ;;
    basics) printf '基础' ;;
    accounts) printf '账户' ;;
    ssh) printf 'SSH' ;;
    firewall) printf '防火墙' ;;
    hardening) printf '加固' ;;
    report) printf '报告' ;;
    *) printf '%s' "$1" ;;
  esac
}

wizard_step_state_text() {
  case $1 in
    done) printf '已完成' ;;
    skipped) printf '已跳过' ;;
    in_progress) printf '进行中' ;;
    *) printf '待执行' ;;
  esac
}

wizard_done_count() {
  local s count=0
  for s in "${SST_WIZARD_STEPS[@]}"; do
    [[ $(wizard_step_status "$s") == done ]] && count=$((count + 1))
  done
  printf '%d' "$count"
}

wizard_next_step() {
  local s status
  for s in "${SST_WIZARD_STEPS[@]}"; do
    status=$(wizard_step_status "$s")
    [[ $status == done || $status == skipped ]] && continue
    printf '%s' "$s"
    return 0
  done
}

wizard_progress_meta() {
  local total done next
  total=${#SST_WIZARD_STEPS[@]}
  done=$(wizard_done_count)
  next=$(wizard_next_step)
  if (( done >= total )); then
    printf '全部完成 · 可生成报告'
  elif [[ -n $next ]]; then
    printf '%d/%d 完成 · 下一步：%s' "$done" "$total" "$(wizard_step_label "$next")"
  else
    printf '%d/%d 完成 · 可生成报告' "$done" "$total"
  fi
}

wizard_status_table() {
  local s status symbol color text
  section "开荒进度"
  for s in "${SST_WIZARD_STEPS[@]}"; do
    status=$(wizard_step_status "$s")
    case $status in
      done) symbol=$UI_SYM_OK color=$C_OK ;;
      skipped) symbol=$UI_SYM_WARN color=$C_WARN ;;
      in_progress) symbol=$UI_SYM_ARROW color=$C_ACCENT ;;
      *) symbol=$UI_SYM_BULLET color=$C_DIM ;;
    esac
    text=$(wizard_step_state_text "$status")
    printf '  %s%s%s %s%s%s\n' "$color" "$symbol" "$C_RESET" \
      "$(ui_pad "$(wizard_step_label "$s")" 18)" "$C_DIM" "$text$C_RESET"
  done
  [[ -n $(wizard_get HOSTNAME) ]] && kv "主机名" "$(wizard_get HOSTNAME)"
  [[ -n $(wizard_get TIMEZONE) ]] && kv "时区" "$(wizard_get TIMEZONE)"
  [[ -n $(wizard_get DNS) ]] && kv "DNS" "$(wizard_get DNS)"
  [[ -n $(wizard_get DATA_DISKS) ]] && kv "数据盘" "$(wizard_get DATA_DISKS)"
  [[ -n $(wizard_get ADMIN_USER) ]] && kv "管理用户" "$(wizard_get ADMIN_USER)"
  [[ -n $(wizard_get SSH_NEW_PORT) ]] && kv "SSH 新端口" "$(wizard_get SSH_NEW_PORT)"
  [[ -n $(wizard_get SSH_STATUS) ]] && kv "SSH 状态" "$(wizard_get SSH_STATUS)"
  [[ -n $(wizard_get FIREWALL) ]] && kv "防火墙" "$(wizard_get FIREWALL)"
  [[ -n $(wizard_get SECURITY_SYSCTL) ]] && kv "安全参数" "$(wizard_get SECURITY_SYSCTL)"
  [[ -n $(wizard_get SWAP) ]] && kv "SWAP" "$(wizard_get SWAP)"
  [[ -n $(wizard_get BBR) ]] && kv "BBR" "$(wizard_get BBR)"
  return 0
}

wizard_report_write() {
  require_root
  wizard_init
  local file ts
  ts=$(date +%Y%m%d-%H%M%S)
  file="$SST_WIZARD_DIR/report-$ts.md"
  mkdir -p "$SST_WIZARD_DIR"
  {
    printf '# STBOX 开荒报告\n\n'
    printf '%s\n' "- 生成时间：$(date '+%F %T')"
    printf '%s\n' "- 主机名：$(hostname)"
    printf '%s\n' "- 系统：$OS_NAME"
    printf '%s\n' "- 内核：$(uname -r)"
    printf '%s\n' "- 架构：$ARCH"
    printf '%s\n\n' "- 公网 IP：$(get_public_ip)"
    printf '## 向导进度\n\n'
    printf '| 步骤 | 状态 |\n|---|---|\n'
    local s
    for s in "${SST_WIZARD_STEPS[@]}"; do
      printf '| %s | %s |\n' "$(wizard_step_label "$s")" "$(wizard_step_status "$s")"
    done
    printf '\n## 当前配置\n\n'
    printf '| 项目 | 值 |\n|---|---|\n'
    printf '| 时区 | %s |\n' "$(timedatectl show -p Timezone --value 2>/dev/null || date +%Z)"
    printf '| DNS | %s |\n' "$(awk '/^nameserver/ {printf "%s ", $2}' /etc/resolv.conf 2>/dev/null)"
    printf '| SSH 端口 | %s |\n' "$(ssh_all_ports 2>/dev/null || ssh_current_port 2>/dev/null || echo 22)"
    printf '| root 登录 | %s |\n' "$(ssh_cfg_get PermitRootLogin 2>/dev/null || echo 未知)"
    printf '| 密码登录 | %s |\n' "$(ssh_cfg_get PasswordAuthentication 2>/dev/null || echo 未知)"
    printf '| 管理用户 | %s |\n' "$(wizard_get ADMIN_USER 未创建)"
    printf '| 防火墙 | %s |\n' "$(_fw_installed 2>/dev/null || echo 未知)"
    printf '| Fail2ban | %s |\n' "$(have fail2ban-client && svc_state_text fail2ban || echo 未安装)"
    printf '| 安全参数 | %s |\n' "$(wizard_get SECURITY_SYSCTL 未应用)"
    printf '| SWAP | %s |\n' "$(wizard_get SWAP 未创建)"
    printf '| BBR | %s |\n' "$(wizard_get BBR $(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || echo 未知))"
    printf '| TCP 算法 | %s |\n' "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || echo 未知)"
    printf '| 数据盘 | %s |\n' "$(wizard_get DATA_DISKS 未挂载)"
    printf '\n## 后续建议\n\n'
    if [[ -n $(wizard_get SSH_NEW_PORT) ]]; then
      printf '1. 用新终端验证：ssh -p %s 用户@%s\n' "$(wizard_get SSH_NEW_PORT)" "$(get_public_ip)"
      printf '2. 确认可登录后执行：st init ssh keep\n'
    else
      printf '1. 用新终端验证 SSH 可登录后再关闭旧端口或会话。\n'
    fi
    printf '3. 按需执行：st security ssh_status / st security firewall_status。\n'
    printf '4. 定期运行：st backup create /etc /var/www。\n'
  } >"$file"
  chmod 600 "$file"
  printf '%s\n' "$file"
}

# --- core/apps.sh ---
# 应用插件框架：扫描 apps/ 与 plugins/apps/，注册元数据并提供 Compose 运行助手。
# 插件目录结构：<name>/app.conf + <name>/app.sh
# app.sh 需提供 app_<name>_install / app_<name>_remove（status 可选）。

declare -A SST_APP_TITLE=() SST_APP_DESC=() SST_APP_CATEGORY=()
declare -A SST_APP_PORT=() SST_APP_URL=() SST_APP_DIR=()
SST_APP_ORDER=()

sst_load_apps() {
  [[ ${SST_BUNDLED:-0} -eq 1 ]] && return 0
  SST_APP_ORDER=()
  SST_APP_TITLE=() SST_APP_DESC=() SST_APP_CATEGORY=()
  SST_APP_PORT=() SST_APP_URL=() SST_APP_DIR=()

  local root dir name
  for root in "$SST_HOME/apps" "$SST_HOME/plugins/apps"; do
    [[ -d $root ]] || continue
    for dir in "$root"/*/; do
      [[ -f ${dir}app.conf ]] || continue
      name=$(basename "$dir")
      [[ -n ${SST_APP_TITLE[$name]:-} ]] && continue

      APP_TITLE='' APP_DESC='' APP_CATEGORY='' APP_PORT='' APP_URL=''
      # shellcheck disable=SC1090
      source "${dir}app.conf" || { warn "应用配置加载失败：${dir}app.conf"; continue; }

      SST_APP_TITLE[$name]=${APP_TITLE:-$name}
      SST_APP_DESC[$name]=${APP_DESC:-}
      SST_APP_CATEGORY[$name]=${APP_CATEGORY:-其他}
      SST_APP_PORT[$name]=${APP_PORT:-}
      SST_APP_URL[$name]=${APP_URL:-}
      SST_APP_DIR[$name]=$dir
      SST_APP_ORDER+=("$name")

      if [[ -f ${dir}app.sh ]]; then
        # shellcheck disable=SC1090
        source "${dir}app.sh" || warn "应用脚本加载失败：${dir}app.sh"
      fi
    done
  done
}

app_exists() {
  [[ -n ${SST_APP_TITLE[${1:-}]:-} ]]
}

app_call() {
  local name=$1 action=$2
  shift 2
  local safe=${name//-/_}
  local fn="app_${safe}_${action}"
  declare -F "$fn" >/dev/null 2>&1 || die "应用 $name 不支持操作：$action"
  "$fn" "$@"
}

app_data_dir() { printf '%s/apps/%s' "$SST_DATA_DIR" "$1"; }

app_installed() {
  [[ -f "$(app_data_dir "${1:-}")/docker-compose.yml" ]]
}

compose_run() {
  if docker compose version >/dev/null 2>&1; then
    docker compose "$@"
  elif have docker-compose; then
    docker-compose "$@"
  else
    return 1
  fi
}

# 从标准输入读取 Compose 内容并启动
app_compose_up() {
  local name=$1 dir
  dir=$(app_data_dir "$name")
  mkdir -p "$dir" || return 1
  cat >"$dir/docker-compose.yml"
  compose_run -f "$dir/docker-compose.yml" up -d
}

app_compose_down() {
  local name=$1 dir
  dir=$(app_data_dir "$name")
  [[ -f $dir/docker-compose.yml ]] || return 0
  compose_run -f "$dir/docker-compose.yml" down --remove-orphans || return 1
  rm -f "$dir/docker-compose.yml"
}

app_compose_ps() {
  local name=$1 dir
  dir=$(app_data_dir "$name")
  [[ -f $dir/docker-compose.yml ]] || { info "应用 $name 未部署"; return 0; }
  compose_run -f "$dir/docker-compose.yml" ps
}

app_access_url() {
  local name=$1 url=${SST_APP_URL[${1:-}]:-}
  [[ -n $url ]] || return 0
  printf '%s\n' "${url//IP/$(get_public_ip)}"
}

# Web IDE 类应用的安全提示（code-server / OpenVSCode 等）
app_webide_notice() {
  local port=$1
  warn "Web IDE 以 HTTP 暴露 $port 端口，直接对公网开放存在被接管风险。"
  info "建议用 SSH 隧道访问：ssh -L $port:127.0.0.1:$port 用户@服务器"
  info "如需公网访问，请通过 Nginx/Caddy 反向代理并启用 HTTPS 与访问认证。"
}

# --- core/scripts.sh ---
# 第三方脚本市场：登记经过筛选的外部脚本，下载后执行，而不是 curl | bash 直通。
# 目录：scripts/*.conf、plugins/scripts/*.conf
#
# 字段：
#   SCRIPT_TITLE    显示名称
#   SCRIPT_DESC     功能说明
#   SCRIPT_CATEGORY 测试 / 工具 / 探针 / 面板 / 节点 / 代理 / 内核 / 甲骨文 / 重装 / NAT
#   SCRIPT_URL      下载地址（HTTPS）
#   SCRIPT_MODE     bash | binary
#   SCRIPT_ARG      固定参数（可选）
#   SCRIPT_ROOT     1 需要 root（默认 1）
#   SCRIPT_RISK     低 / 中 / 高
#   SCRIPT_SHA256   可选校验值
#   SCRIPT_ARCH     可选限定架构（如 x86_64）

declare -A SST_SCRIPT_TITLE=() SST_SCRIPT_DESC=() SST_SCRIPT_CATEGORY=()
declare -A SST_SCRIPT_URL=() SST_SCRIPT_MODE=() SST_SCRIPT_ARG=()
declare -A SST_SCRIPT_ROOT=() SST_SCRIPT_RISK=() SST_SCRIPT_SHA256=()
declare -A SST_SCRIPT_ARCH=()
SST_SCRIPT_ORDER=()

sst_load_scripts() {
  [[ ${SST_BUNDLED:-0} -eq 1 ]] && return 0
  SST_SCRIPT_ORDER=()
  SST_SCRIPT_TITLE=() SST_SCRIPT_DESC=() SST_SCRIPT_CATEGORY=()
  SST_SCRIPT_URL=() SST_SCRIPT_MODE=() SST_SCRIPT_ARG=()
  SST_SCRIPT_ROOT=() SST_SCRIPT_RISK=() SST_SCRIPT_SHA256=()
  SST_SCRIPT_ARCH=()

  local root file name
  for root in "$SST_HOME/scripts" "$SST_HOME/plugins/scripts"; do
    [[ -d $root ]] || continue
    for file in "$root"/*.conf; do
      [[ -f $file ]] || continue
      name=$(basename "$file" .conf)
      [[ -n ${SST_SCRIPT_TITLE[$name]:-} ]] && continue

      SCRIPT_TITLE='' SCRIPT_DESC='' SCRIPT_CATEGORY='' SCRIPT_URL=''
      SCRIPT_MODE='' SCRIPT_ARG='' SCRIPT_ROOT='' SCRIPT_RISK=''
      SCRIPT_SHA256='' SCRIPT_ARCH=''
      # shellcheck disable=SC1090
      source "$file" || { warn "脚本配置加载失败：$file"; continue; }

      [[ -n ${SCRIPT_URL:-} ]] || continue
      SST_SCRIPT_TITLE[$name]=${SCRIPT_TITLE:-$name}
      SST_SCRIPT_DESC[$name]=${SCRIPT_DESC:-}
      SST_SCRIPT_CATEGORY[$name]=${SCRIPT_CATEGORY:-工具}
      SST_SCRIPT_URL[$name]=$SCRIPT_URL
      SST_SCRIPT_MODE[$name]=${SCRIPT_MODE:-bash}
      SST_SCRIPT_ARG[$name]=${SCRIPT_ARG:-}
      SST_SCRIPT_ROOT[$name]=${SCRIPT_ROOT:-1}
      SST_SCRIPT_RISK[$name]=${SCRIPT_RISK:-中}
      SST_SCRIPT_SHA256[$name]=${SCRIPT_SHA256:-}
      SST_SCRIPT_ARCH[$name]=${SCRIPT_ARCH:-}
      SST_SCRIPT_ORDER+=("$name")
    done
  done
}

script_exists() { [[ -n ${SST_SCRIPT_TITLE[${1:-}]:-} ]]; }

scripts_confirm_risk() {
  local name=$1 title=${SST_SCRIPT_TITLE[$1]:-}
  if [[ ${SST_SCRIPT_CATEGORY[$name]:-} == "重装" ]]; then
    [[ ${SST_YES:-0} -eq 1 ]] && return 0
    warn "该操作会清空磁盘并重装系统，无法通过本工具回滚。"
    local phrase
    read -r -p "$(ui_prompt_text '输入 REINSTALL 确认')" phrase || return 1
    if [[ $phrase != "REINSTALL" ]]; then
      warn "确认词不匹配，已取消"
      return 1
    fi
    return 0
  fi
  confirm "下载并执行 $title？"
}

scripts_run() {
  local name=$1
  shift
  script_exists "$name" || die "未知脚本：$name（可执行 st bench scripts 查看清单）"

  local url mode arg title risk need_root want_arch file rc
  url=${SST_SCRIPT_URL[$name]}
  mode=${SST_SCRIPT_MODE[$name]}
  arg=${SST_SCRIPT_ARG[$name]}
  title=${SST_SCRIPT_TITLE[$name]}
  risk=${SST_SCRIPT_RISK[$name]}
  need_root=${SST_SCRIPT_ROOT[$name]}
  want_arch=${SST_SCRIPT_ARCH[$name]}

  if [[ $need_root == 1 ]]; then
    require_root
  fi
  if [[ -n $want_arch && $want_arch != "$ARCH" ]]; then
    die "$title 仅支持 $want_arch 架构，当前为 $ARCH"
  fi

  section "$title"
  kv "说明" "${SST_SCRIPT_DESC[$name]}"
  kv "来源" "$url"
  kv "风险" "$risk"
  warn "该功能由第三方脚本提供，执行前请确认来源可信；脚本拥有当前用户权限。"
  scripts_confirm_risk "$name" || return 0

  mkdir -p "$SST_DATA_DIR/scripts" 2>/dev/null || die "无法创建脚本缓存目录"
  file="$SST_DATA_DIR/scripts/${name}-${ARCH}"
  info "下载脚本：$url"
  if ! download_with_fallback "$url" "$file" 90; then
    rm -f "$file"
    die "下载失败，请检查网络或地址"
  fi

  if [[ -n ${SST_SCRIPT_SHA256[$name]} ]]; then
    if ! printf '%s  %s\n' "${SST_SCRIPT_SHA256[$name]}" "$file" | sha256sum -c - >/dev/null 2>&1; then
      rm -f "$file"
      die "SHA256 校验失败，已阻止执行"
    fi
    ok "SHA256 校验通过"
  fi

  chmod +x "$file" 2>/dev/null || true
  local -a cmd
  if [[ $mode == binary ]]; then
    cmd=("$file")
  else
    cmd=(bash "$file")
    if [[ -n $arg ]]; then
      local -a fixed=()
      read -r -a fixed <<<"$arg"
      cmd+=("${fixed[@]}")
    fi
  fi
  cmd+=("$@")

  info "开始执行：${cmd[*]}"
  "${cmd[@]}"
  rc=$?
  if (( rc == 0 )); then
    ok "$title 执行完成"
  else
    warn "$title 退出码：$rc（部分测试脚本在未达标时会返回非 0）"
  fi
  info "脚本已缓存：$file"
}

scripts_menu() {
  local filter=${1:-全部} choice idx name meta title
  local -a names=()

  for name in "${SST_SCRIPT_ORDER[@]}"; do
    case $filter in
      全部) ;;
      测试) [[ ${SST_SCRIPT_CATEGORY[$name]} == "测试" ]] || continue ;;
      工具) [[ ${SST_SCRIPT_CATEGORY[$name]} == "工具" ]] || continue ;;
      *) [[ ${SST_SCRIPT_CATEGORY[$name]} == "$filter" ]] || continue ;;
    esac
    names+=("$name")
  done

  if [[ ${#names[@]} -eq 0 ]]; then
    warn "该分类下暂无脚本"
    return 1
  fi

  while true; do
    section "脚本市场（${filter}）"
    for idx in "${!names[@]}"; do
      name=${names[$idx]}
      title=${SST_SCRIPT_TITLE[$name]}
      meta=${SST_SCRIPT_RISK[$name]}
      [[ -n $meta ]] && meta="$meta · "
      ui_menu_item "$((idx + 1))" "$title" "${meta}${SST_SCRIPT_DESC[$name]}"
    done
    ui_menu_footer
    ui_read_choice "请选择脚本" || break
    choice=$UI_CHOICE
    case $choice in
      0|q|back) break ;;
      [0-9]|[0-9][0-9])
        idx=$((choice - 1))
        if (( idx >= 0 && idx < ${#names[@]} )); then
          scripts_run "${names[$idx]}"
          pause
        else
          warn "无效编号：$choice"
        fi
        ;;
      *)
        if script_exists "$choice"; then
          scripts_run "$choice"
          pause
        else
          warn "未知脚本：$choice"
        fi
        ;;
    esac
  done
}

# --- core/update.sh ---
# 版本与自更新

if [[ -z ${SST_VERSION:-} ]]; then
  SST_VERSION=$(cat "$SST_HOME/VERSION" 2>/dev/null || echo "unknown")
fi

version_info() {
  section "STBOX 版本信息"
  kv "版本" "$SST_VERSION"
  if [[ ${SST_BUNDLED:-0} -eq 1 ]]; then
    kv "运行方式" "单文件"
    kv "程序路径" "$SST_ENTRY"
    kv "状态目录" "$SST_STATE_DIR"
  else
    kv "安装目录" "$SST_HOME"
  fi
  kv "入口命令" "$SST_ENTRY"
  kv "配置目录" "$SST_CONFIG_DIR"
  kv "数据目录" "$SST_DATA_DIR"
  kv "日志文件" "$SST_LOG"
  kv "运行系统" "$OS_NAME ($ARCH)"
  kv "包管理器" "$PKG"
  kv "服务管理器" "$INIT"
}

# 安装/覆盖文件：优先 install，最小系统回退 cp
sst_install_file() {
  local src=$1 dest=$2
  if have install; then
    install -m 755 "$src" "$dest"
  else
    cp -f "$src" "$dest" && chmod 755 "$dest"
  fi
}

# 单文件版本自安装：sudo bash <(curl ...) install
stbox_self_install() {
  [[ ${SST_BUNDLED:-0} -eq 1 ]] || die "仅单文件版本支持 install"
  [[ ${EUID:-1} -eq 0 ]] || die "请使用 root 执行：sudo bash <(curl ...) install"
  local src=${BASH_SOURCE[0]:-} bin=${STBOX_BIN_DIR:-/usr/local/bin}
  [[ -r $src ]] || die "无法读取当前单文件：$src"
  mkdir -p "$bin" || die "无法创建目录：$bin"
  if [[ -e $bin/st ]]; then
    confirm "覆盖已有 $bin/st？" || return 0
  fi
  sst_install_file "$src" "$bin/st" || die "安装失败：$bin/st"
  ok "已安装：$bin/st"
  info "数据目录：$SST_STATE_DIR"
  info "执行 st 进入交互菜单"
}

update_self() {
  require_root
  if [[ ${SST_BUNDLED:-0} -eq 1 ]]; then
    local url=${STBOX_UPDATE_URL:-https://raw.githubusercontent.com/fengzone85/stbox/main/stbox.sh}
    local sha_url=${STBOX_UPDATE_SHA_URL:-$url.sha256}
    local dest=${SST_ENTRY:-}
    [[ -f $dest && $dest != /dev/fd/* && $dest != /proc/* ]] || die "请先执行 sudo bash <(curl ...) install 安装单文件版本"
    confirm "下载并更新单文件版本？" || return 0
    local tmp sha expected actual new_ver
    tmp=$(mktemp) sha=$(mktemp) || die "无法创建临时文件"
    if ! download_with_fallback "$url" "$tmp" 60; then
      rm -f "$tmp" "$sha"
      die "下载新版本失败：$url"
    fi
    if ! download_with_fallback "$sha_url" "$sha" 30; then
      rm -f "$tmp" "$sha"
      die "下载校验文件失败：$sha_url"
    fi
    expected=$(awk 'NR==1 {print $1}' "$sha")
    actual=$(sha256sum "$tmp" | awk '{print $1}')
    if [[ -z $expected || $expected != "$actual" ]]; then
      rm -f "$tmp" "$sha"
      die "SHA256 校验失败，已取消更新"
    fi
    bash -n "$tmp" || { rm -f "$tmp" "$sha"; die "新版本语法校验失败"; }
    new_ver=$(grep -m1 '^SST_VERSION=' "$tmp" | cut -d'"' -f2)
    cp -f "$dest" "$dest.bak" || { rm -f "$tmp" "$sha"; die "备份旧版本失败"; }
    if ! sst_install_file "$tmp" "$dest"; then
      cp -f "$dest.bak" "$dest" 2>/dev/null || true
      rm -f "$tmp" "$sha"
      die "替换失败，已恢复旧版本"
    fi
    rm -f "$tmp" "$sha"
    ok "更新完成${new_ver:+：$new_ver}"
    info "旧版本备份：$dest.bak"
    return 0
  fi

  if [[ -d "$SST_HOME/.git" ]] && have git; then
    info "当前为 Git 源码部署，准备拉取最新代码…"
    confirm "执行 git pull --ff-only 更新？" || return 0
    git -C "$SST_HOME" pull --ff-only || die "更新失败，请检查远程仓库或本地修改"
    ok "更新完成，重新进入脚本后生效"
  else
    warn "当前部署不是 Git 仓库，无法自动更新。"
    warn "请重新拉取/覆盖源码，或执行 install.sh 覆盖安装（配置与数据会保留）。"
  fi
}

# --- core/menu.sh ---
# 菜单层：模块注册、主菜单、子菜单与 CLI 分发

declare -A SST_MODULE_TITLE=() SST_MODULE_DESC=() SST_MODULE_ITEMS=()
declare -A SST_MODULE_GROUP=(
  [init]=0
  [system]=1 [network]=1 [tune]=1 [bench]=1
  [docker]=2 [apps]=2 [site]=2 [ai]=2
  [security]=3 [backup]=3 [tools]=3 [components]=3
  [settings]=4
)
SST_MODULE_GROUPS=(开荒与初始化 系统与网络 应用与部署 安全与运维 设置)
SST_MODULE_ORDER=()
SST_BANNER_KERNEL=''

sst_register_module() {
  local name=$1 title=$2 desc=$3
  [[ -n ${SST_MODULE_TITLE[$name]:-} ]] && return 0
  SST_MODULE_TITLE[$name]=$title
  SST_MODULE_DESC[$name]=$desc
  SST_MODULE_ORDER+=("$name")
}

sst_load_modules() {
  if [[ ${SST_BUNDLED:-0} -eq 1 ]]; then
    sst_sort_modules
    return 0
  fi
  local f
  for f in "$SST_HOME"/modules/*.sh; do
    [[ -f $f ]] || continue
    # shellcheck disable=SC1090
    source "$f" || warn "模块加载失败：$f"
  done
  sst_sort_modules
}

# 主菜单顺序；未列出的模块按注册顺序追加
sst_sort_modules() {
  local -a preferred=(init system network tune bench docker apps site ai security backup tools components settings)
  local -a sorted=()
  local name
  for name in "${preferred[@]}"; do
    [[ -n ${SST_MODULE_TITLE[$name]:-} ]] && sorted+=("$name")
  done
  for name in "${SST_MODULE_ORDER[@]}"; do
    [[ " ${sorted[*]:-} " == *" $name "* ]] || sorted+=("$name")
  done
  SST_MODULE_ORDER=("${sorted[@]}")
}

sst_module_run() {
  local module=$1 action=$2
  shift 2
  local fn="${module}_${action}"
  if declare -F "$fn" >/dev/null 2>&1; then
    "$fn" "$@"
    return $?
  fi
  # 菜单项直接指向脚本市场中的第三方脚本
  if script_exists "$action"; then
    scripts_run "$action" "$@"
    return $?
  fi
  die "模块 $module 不支持操作：$action"
}

sst_module_group() {
  local group=${SST_MODULE_GROUP[$1]:-99}
  printf '%s' "${SST_MODULE_GROUPS[$group]:-其他}"
}

sst_banner_status() {
  local fw fw_label bbr
  fw=$(_fw_installed 2>/dev/null || printf 'none')
  case $fw in
    ufw) fw_label="UFW $(_ufw_state 2>/dev/null || printf '未知')" ;;
    firewalld) fw_label="firewalld $(svc_state_text firewalld 2>/dev/null || printf '未知')" ;;
    nftables|iptables) fw_label="$fw 已安装" ;;
    *) fw_label='防火墙未安装' ;;
  esac
  bbr=$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || printf '未知')
  printf '%s · SSH %s · %s · BBR %s' \
    "$(hostname 2>/dev/null || printf '未知')" \
    "$(ssh_all_ports 2>/dev/null || printf '22')" \
    "$fw_label" "$bbr"
}

sst_print_banner() {
  [[ -n ${SST_BANNER_KERNEL:-} ]] || SST_BANNER_KERNEL=$(uname -r 2>/dev/null || printf '未知')
  local inner line1 line2 line3 line4 line5 line6 line7
  inner=$(( $(ui_frame_width) - 4 ))
  line1=$(ui_fit "SSH Tool Box · ${OS_NAME} · 内核 ${SST_BANNER_KERNEL}" "$inner")
  line2=$(ui_fit "$(sst_banner_status)" "$inner")
  line3=$(ui_fit "开荒向导 $(wizard_progress_meta)" "$inner")
  line4=$(ui_fit "GitHub github.com/fengzone85/stbox" "$inner")
  line5=$(ui_fit "一键安装 curl -fsSL \\" "$inner")
  line6=$(ui_fit "         cdn.jsdelivr.net/gh/fengzone85/stbox/i.sh | \\" "$inner")
  line7=$(ui_fit "         sudo bash" "$inner")
  ui_panel "STBOX ${SST_VERSION}" "$line1" "$line2" "$line3" "$line4" "$line5" "$line6" "$line7"
}

sst_module_help() {
  local module=$1 action label
  section "${SST_MODULE_TITLE[$module]}"
  printf '%s\n' "${SST_MODULE_DESC[$module]}"
  hr
  printf '用法：st %s <操作> [参数]\n\n' "$module"
  while IFS='|' read -r action label; do
    [[ -n $action ]] || continue
    printf '  %s%s%s  %s\n' "$C_ACCENT" "$(ui_pad "$action" 18)" "$C_RESET" "$label"
  done <<<"${SST_MODULE_ITEMS[$module]}"
  printf '\n  不带参数执行 st 可进入交互菜单\n'
}

sst_help() {
  section "STBOX 使用说明"
  cat <<'EOF'
用法：st [--yes] [--no-color] [--plain] <模块> <操作> [参数...]

模块与常用命令：

  开荒与初始化
    init      开荒向导      st init | preflight | disk scan | basics | accounts | ssh | firewall | hardening | report

  系统与网络
    system    系统维护      st system info | memory | update | clean_deep | dns | timezone | hostname | rootpass | portscan | cron | shortcut
    network   网络测试      st network info | ip | speed [MB] | ping [host] | route [host] | dns | port
    tune      系统优化      st tune status | sysctl on/off | swap create/remove | ipv6 4/6 | mirror aliyun
    bench     性能测试      st bench memtest | diskbench [MB] | cpu | nodequality | tcpquality | scripts

  应用与部署
    docker    Docker 管理   st docker status | install | ps | exec | images | networks | volumes | compose | prune | uninstall
    apps      应用市场      st apps list | menu | install <名称> | remove <名称> | status <名称>
    site     建站环境      st site install | status | add | wordpress | proxy | ssl | list | remove | backup | uninstall
    ai        AI 工具       st ai status | list | install [工具] | version | update [工具] | remove [工具]
                             快捷安装：st ai claude | codex | gemini | qoder | codebuddy | ccswitch

  安全与运维
    security  安全与优化    st security status | firewall_status | firewall_allow <端口>
                             BBR/SSH/Fail2ban：st security bbr_on | ssh_status | fail2ban_install
    backup    备份与迁移    st backup list | create [路径...] | restore | schedule | remote
    tools     实用工具      st tools disk_mount | git | rclone | probes | panels | nodes | proxy | kernel | oracle | nat
    components 组件环境     st components list | install | install_all | remove | python | nodejs | golang | java | workspace

  设置
    settings  脚本设置      st settings version | update | config | log

示例：
  st system update
  st network speed 100
  st tune swap create
  st bench superbench
  st site install
  st site wordpress
  st app install npm
  st tools warp
  st components workspace
  st backup create /etc /var/www

说明：
  1. 涉及系统变更的操作需要 root 权限，会自动通过 sudo 重新执行。
  2. 自动化场景使用 --yes 跳过确认；危险操作仍会打印影响范围。
  3. bench/tools 中的第三方脚本会显示来源与风险，确认后才下载执行。
  4. 直接执行 st 进入交互菜单；--no-color 关闭彩色，--plain 同时关闭彩色与 Unicode 边框。
EOF
}

# 容器选择器：菜单打印到 stderr，选中的容器名输出到 stdout
docker_pick() {
  local -a names=()
  mapfile -t names < <(docker ps -a --format '{{.Names}}' 2>/dev/null)
  if [[ ${#names[@]} -eq 0 ]]; then
    warn "当前没有容器"
    return 1
  fi
  local i sel
  {
    printf '\n可用容器：\n'
    for i in "${!names[@]}"; do
      ui_menu_item "$((i + 1))" "${names[$i]}"
    done
    ui_menu_footer "取消"
    ui_read_choice "选择容器编号" || return 1
  } >&2
  sel=$UI_CHOICE
  if [[ ! $sel =~ ^[0-9]+$ ]] || (( sel < 1 || sel > ${#names[@]} )); then
    warn "无效编号"
    return 1
  fi
  printf '%s\n' "${names[$((sel - 1))]}"
}

sst_wizard_checklist() {
  local i step status symbol color cell next total columns
  total=${#SST_WIZARD_STEPS[@]}
  next=$(wizard_next_step)
  columns=4
  (( UI_WIDTH < 50 )) && columns=2
  (( UI_WIDTH < 26 )) && columns=1
  printf '\n  '
  for (( i = 0; i < total; i++ )); do
    step=${SST_WIZARD_STEPS[$i]}
    status=$(wizard_step_status "$step")
    case $status in
      done) symbol=$UI_SYM_OK color=$C_OK ;;
      skipped) symbol=$UI_SYM_WARN color=$C_WARN ;;
      in_progress) symbol=$UI_SYM_ARROW color=$C_ACCENT ;;
      *)
        if [[ $step == "$next" ]]; then
          symbol=$UI_SYM_ARROW color=$C_ACCENT
        else
          symbol=$UI_SYM_BULLET color=$C_DIM
        fi
        ;;
    esac
    cell=$(ui_pad "$symbol $(wizard_step_short "$step")" 9)
    printf '%s%s%s' "$color" "$cell" "$C_RESET"
    if (( (i + 1) % columns == 0 )); then
      printf '\n'
      (( i + 1 < total )) && printf '  '
    else
      printf '  '
    fi
  done
  (( total % columns != 0 )) && printf '\n'
}

sst_module_header() {
  local module=$1
  if [[ $module == init ]]; then
    sst_wizard_checklist
  else
    printf '  %s%s%s\n' "$C_DIM" "${SST_MODULE_DESC[$module]}" "$C_RESET"
  fi
}

sst_module_menu() {
  local module=$1 title=${SST_MODULE_TITLE[$1]}
  local choice idx action label i meta
  local -a actions=() labels=()

  while true; do
    meta=''
    [[ $module == init ]] && meta=$(wizard_progress_meta)
    section "$title" "$meta"
    sst_module_header "$module"
    hr
    actions=() labels=()
    while IFS='|' read -r action label; do
      [[ -n $action ]] || continue
      actions+=("$action")
      labels+=("$label")
    done <<<"${SST_MODULE_ITEMS[$module]}"

    for i in "${!actions[@]}"; do
      ui_menu_item "$((i + 1))" "${labels[$i]}"
    done
    if (( UI_WIDTH >= 48 )); then
      printf '\n  %s0%s 返回   %sh%s 帮助   %s输入操作名可直接执行%s\n\n' \
        "$C_ACCENT" "$C_RESET" "$C_ACCENT" "$C_RESET" "$C_DIM" "$C_RESET"
    else
      printf '\n  %s0%s 返回   %sh%s 帮助\n\n' \
        "$C_ACCENT" "$C_RESET" "$C_ACCENT" "$C_RESET"
    fi

    read -r -p "$(ui_prompt_text '请选择')" choice || break
    case $choice in
      0|q|back|exit) break ;;
      [0-9]|[0-9][0-9])
        idx=$((choice - 1))
        if (( idx >= 0 && idx < ${#actions[@]} )); then
          sst_module_run "$module" "${actions[$idx]}"
          pause
        else
          warn "无效编号：$choice"
        fi
        ;;
      *)
        if declare -F "${module}_${choice}" >/dev/null 2>&1; then
          sst_module_run "$module" "$choice"
          pause
        else
          warn "未知操作：$choice"
        fi
        ;;
    esac
  done
}

sst_main_menu() {
  local choice idx module group current_group
  local -a mods=()

  while true; do
    sst_print_banner
    section "主菜单"
    mods=("${SST_MODULE_ORDER[@]}")
    current_group=-1
    for idx in "${!mods[@]}"; do
      module=${mods[$idx]}
      group=${SST_MODULE_GROUP[$module]:-99}
      if (( group != current_group )); then
        ui_group "$(sst_module_group "$module")"
        current_group=$group
      fi
      ui_menu_item "$((idx + 1))" "${SST_MODULE_TITLE[$module]}" "${SST_MODULE_DESC[$module]}"
    done
    if (( UI_WIDTH >= 48 )); then
      printf '\n  %s0%s 退出   %sh%s 帮助   %s输入模块名可直接进入%s\n\n' \
        "$C_ACCENT" "$C_RESET" "$C_ACCENT" "$C_RESET" "$C_DIM" "$C_RESET"
    else
      printf '\n  %s0%s 退出   %sh%s 帮助\n\n' \
        "$C_ACCENT" "$C_RESET" "$C_ACCENT" "$C_RESET"
    fi

    read -r -p "$(ui_prompt_text '请选择')" choice || break
    case $choice in
      0|q|quit|exit) break ;;
      h|help) sst_help; pause ;;
      '') continue ;;
      [0-9]|[0-9][0-9])
        idx=$((choice - 1))
        if (( idx >= 0 && idx < ${#mods[@]} )); then
          sst_module_menu "${mods[$idx]}"
        else
          warn "无效编号：$choice"
        fi
        ;;
      *)
        if [[ -n ${SST_MODULE_TITLE[$choice]:-} ]]; then
          sst_module_menu "$choice"
        else
          warn "未知模块：$choice"
        fi
        ;;
    esac
  done
}

sst_dispatch() {
  SST_ARGS=("$@")

  if [[ $# -eq 0 ]]; then
    require_root
    sst_main_menu
    return 0
  fi

  local cmd=$1
  shift

  if [[ $cmd == install && ${SST_BUNDLED:-0} -eq 1 ]]; then
    stbox_self_install
    return 0
  fi

  case $cmd in
    version|--version|-v) version_info; return 0 ;;
    help|--help|-h) sst_help; return 0 ;;
  esac

  case $cmd in
    app) cmd=apps ;;
    net) cmd=network ;;
    sec) cmd=security ;;
  esac

  [[ -n ${SST_MODULE_TITLE[$cmd]:-} ]] || die "未知模块：$cmd（执行 st help 查看用法）"
  if [[ $# -eq 0 ]]; then
    sst_module_help "$cmd"
    return 0
  fi

  local action=$1
  shift
  sst_module_run "$cmd" "$action" "$@"
}

