ai_require_node() {
  have npm && return 0
  info "未检测到 npm，先安装 Node.js 与 npm…"
  pkg_update || return 1
  pkg_install nodejs npm || return 1
  have npm || die "Node.js/npm 安装失败"
}

ai_after_install_hint() {
  case $1 in
    qoder) info "Qoder 国际版首次运行：qodercli" ;;
    qodercn) info "Qoder CN 首次运行：qoderclicn" ;;
    codebuddy) info "CodeBuddy 国际版首次运行：codebuddy，登录时选择国际站" ;;
    codebuddycn)
      info "CodeBuddy 国内版：codebuddy 登录时选择国内站，或设置 CODEBUDDY_INTERNET_ENVIRONMENT=internal"
      ;;
  esac
}

ai_install_npm() {
  local id=$1 title=${AI_TITLE[$1]} pkg=${AI_SOURCE[$1]} cmd=${AI_CMD[$1]}
  require_root
  ai_require_node || return 1
  if have "$cmd"; then
    info "已安装：$(command -v "$cmd")"
    confirm "重新安装/升级 $title？" || { ai_after_install_hint "$id"; return 0; }
  else
    confirm "通过 npm 安装 $title（$pkg）？" || return 0
  fi
  if npm install -g "$pkg"; then
    ok "$title 安装完成：$(command -v "$cmd")"
    ai_after_install_hint "$id"
  else
    warn "$title 安装失败，请检查 npm 源或 Node.js 版本要求"
    return 1
  fi
}

ai_install_script() {
  local id=$1 title=${AI_TITLE[$1]} url=${AI_SOURCE[$1]}
  require_root
  ensure_tool curl curl || return 1
  section "安装 $title"
  kv "来源" "$url"
  warn "该安装脚本来自第三方项目，执行前请确认来源可信。"
  confirm "下载并执行 $title 安装脚本？" || return 0
  ai_run_script "$id"
}

# 执行第三方安装脚本（不含确认，供安装/更新复用）
ai_run_script() {
  local id=$1 title=${AI_TITLE[$1]} url=${AI_SOURCE[$1]} tmp rc
  tmp=$(mktemp) || return 1
  if ! download_with_fallback "$url" "$tmp" 120; then
    rm -f "$tmp"
    warn "$title 安装脚本下载失败，可访问官方文档手动安装：${AI_DOC[$id]}"
    return 1
  fi
  bash "$tmp"
  rc=$?
  rm -f "$tmp"
  if (( rc == 0 )); then
    ok "$title 安装流程完成"
  else
    warn "$title 安装脚本退出码：$rc，请查看官方文档：${AI_DOC[$id]}"
    return 1
  fi
}

ai_install_tool() {
  local id=$1
  [[ -n ${AI_TITLE[$id]:-} ]] || die "未知 AI 工具：$id"
  case ${AI_KIND[$id]} in
    npm) ai_install_npm "$id" ;;
    script) ai_install_script "$id" ;;
    *) die "暂不支持自动安装：${AI_TITLE[$id]}" ;;
  esac
}

ai_resolve_id() {
  local key=$1 id
  [[ -n $key ]] || return 1
  for id in "${AI_IDS[@]}"; do
    [[ $key == "$id" || $key == "${AI_CMD[$id]}" || $key == "${AI_TITLE[$id]}" ]] || continue
    printf '%s\n' "$id"
    return 0
  done
  return 1
}

# 选择已安装工具，结果写入 AI_PICKED
ai_pick_installed() {
  local title=$1 id labels=() ids=()
  for id in "${AI_IDS[@]}"; do
    have "${AI_CMD[$id]}" || continue
    ids+=("$id")
    labels+=("${AI_TITLE[$id]}（${AI_CMD[$id]}）")
  done
  if (( ${#ids[@]} == 0 )); then
    info "没有检测到已安装的 AI 工具"
    return 1
  fi
  ui_menu_list "$(printf '%s\n' "${labels[@]}")" "返回"
  ui_read_choice "$title" || return 1
  local choice=$UI_CHOICE
  if ! [[ $choice =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#ids[@]} )); then
    warn "无效编号：$choice"
    return 1
  fi
  AI_PICKED=${ids[$((choice - 1))]}
}

ai_version_of() {
  local id=$1 cmd=${AI_CMD[$1]} out=''
  if [[ ${AI_KIND[$id]} == npm ]] && have npm; then
    out=$(npm ls -g --depth=0 "${AI_SOURCE[$id]}" 2>/dev/null | grep -F "${AI_SOURCE[$id]}@" | head -n1)
    out=${out##*@}
  fi
  if [[ -z $out ]]; then
    if have timeout; then
      out=$(timeout 5 "$cmd" --version 2>/dev/null </dev/null | head -n1)
    else
      out=$("$cmd" --version 2>/dev/null </dev/null | head -n1)
    fi
  fi
  printf '%s\n' "${out:-未知}"
}

ai_version() {
  local id state ver path
  section "AI 工具版本"
  printf '  %-18s %-10s %-18s %s\n' "工具" "状态" "版本" "命令"
  hr
  for id in "${AI_IDS[@]}"; do
    if have "${AI_CMD[$id]}"; then
      state="已安装"
      path=$(command -v "${AI_CMD[$id]}")
      ver=$(ai_version_of "$id")
    else
      state="未安装"
      path=${AI_DOC[$id]}
      ver="-"
    fi
    printf '  %-18s %-10s %-18s %s\n' "${AI_TITLE[$id]}" "$state" "$ver" "$path"
  done
}

ai_update_tool() {
  local id=$1 title=${AI_TITLE[$1]}
  have "${AI_CMD[$id]}" || { warn "$title 未安装，请先安装：st ai $id"; return 1; }
  case ${AI_KIND[$id]} in
    npm)
      require_root
      ai_require_node || return 1
      confirm "更新 $title 到最新版本？" || return 0
      if npm install -g "${AI_SOURCE[$id]}@latest"; then
        ok "$title 已更新：$(ai_version_of "$id")"
      else
        warn "$title 更新失败，请检查 npm 源或网络"
        return 1
      fi
      ;;
    script)
      confirm "重新执行 $title 安装脚本以更新？" || return 0
      ai_run_script "$id"
      ;;
  esac
}

ai_update() {
  local id=${1:-}
  if [[ -z $id ]]; then
    ai_pick_installed "选择要更新的工具" || return 0
    id=$AI_PICKED
  else
    id=$(ai_resolve_id "$id") || die "未知 AI 工具：$1"
  fi
  ai_update_tool "$id"
}

ai_remove_tool() {
  local id=$1 title=${AI_TITLE[$1]}
  if ! have "${AI_CMD[$id]}"; then
    info "$title 未安装"
    return 0
  fi
  case ${AI_KIND[$id]} in
    npm)
      require_root
      [[ $id == codebuddy || $id == codebuddycn ]] && warn "CodeBuddy 国际版/国内版共用同一命令，卸载后两者均不可用"
      confirm "卸载 $title（npm uninstall -g ${AI_SOURCE[$id]}）？" || return 0
      if npm uninstall -g "${AI_SOURCE[$id]}"; then
        ok "$title 已卸载"
      else
        warn "$title 卸载失败"
        return 1
      fi
      ;;
    script)
      warn "$title 由第三方安装脚本管理，本工具不自动卸载"
      info "手动卸载方式参考：${AI_DOC[$id]}"
      ;;
  esac
}

ai_remove() {
  local id=${1:-}
  if [[ -z $id ]]; then
    ai_pick_installed "选择要卸载的工具" || return 0
    id=$AI_PICKED
  else
    id=$(ai_resolve_id "$id") || die "未知 AI 工具：$1"
  fi
  ai_remove_tool "$id"
}

ai_status() {
  local id cmd state path
  section "AI 工具状态"
  printf '  %-18s %-10s %s\n' "工具" "状态" "命令"
  hr
  for id in "${AI_IDS[@]}"; do
    cmd=${AI_CMD[$id]}
    if have "$cmd"; then
      state="已安装"
      path=$(command -v "$cmd")
    else
      state="未安装"
      path=${AI_DOC[$id]}
    fi
    printf '  %-18s %-10s %s\n' "${AI_TITLE[$id]}" "$state" "$path"
  done
}

ai_list() {
  local id
  section "AI 项目清单"
  printf '  %-20s %-12s %s\n' "工具" "命令" "说明"
  hr
  for id in "${AI_IDS[@]}"; do
    printf '  %-20s %-12s %s\n' "${AI_TITLE[$id]}" "${AI_CMD[$id]}" "${AI_DESC[$id]}"
  done
  printf '  %-20s %-12s %s\n' "Claude Desktop" "-" "仅桌面版，服务器环境请使用 Claude Code"
}

ai_install_menu() {
  local choice id i labels=()
  for id in "${AI_IDS[@]}"; do
    labels+=("${AI_TITLE[$id]}")
  done
  ui_menu_list "$(printf '%s\n' "${labels[@]}")" "返回"
  ui_read_choice "选择要安装的工具" || return 0
  choice=$UI_CHOICE
  if ! [[ $choice =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#AI_IDS[@]} )); then
    warn "无效编号：$choice"
    return 0
  fi
  ai_install_tool "${AI_IDS[$((choice - 1))]}"
}

ai_install() {
  local id=${1:-}
  if [[ -z $id ]]; then
    ai_install_menu
    return
  fi
  id=$(ai_resolve_id "$id") || die "未知 AI 工具：$1"
  ai_install_tool "$id"
}

ai_docs() {
  local id
  section "官方地址"
  for id in "${AI_IDS[@]}"; do
    kv "${AI_TITLE[$id]}" "${AI_DOC[$id]}"
  done
  kv "Claude Desktop" "https://claude.ai/download（仅桌面版）"
  printf '\n'
  info "服务器无桌面环境时，优先使用 CC Switch CLI：st ai ccswitch"
}

ai_ccswitch() { ai_install_tool ccswitch; }
ai_claude() { ai_install_tool claude; }
ai_codex() { ai_install_tool codex; }
ai_gemini() { ai_install_tool gemini; }
ai_qoder() { ai_install_tool qoder; }
ai_qodercn() { ai_install_tool qodercn; }
ai_codebuddy() { ai_install_tool codebuddy; }
ai_codebuddycn() { ai_install_tool codebuddycn; }
ai_grok() { ai_install_tool grok; }
ai_opencode() { ai_install_tool opencode; }
ai_openclaw() { ai_install_tool openclaw; }
ai_hermes() { ai_install_tool hermes; }
ai_pi() { ai_install_tool pi; }
ai_minimax() { ai_install_tool minimax; }
ai_kimi() { ai_install_tool kimi; }
ai_ohmy() { ai_install_tool ohmy; }

# --- modules/apps.sh ---
# 模块：应用市场（基于 Docker Compose 的应用插件）

sst_register_module apps "应用市场" "一键部署常用应用"
SST_MODULE_ITEMS[apps]=$'list|应用清单\nmenu|安装与管理\nhelp|插件开发说明'

app_status_mark() {
  if app_installed "$1"; then printf '已部署'; else printf '未部署'; fi
}

apps_list() {
  section "应用清单"
  if [[ ${#SST_APP_ORDER[@]} -eq 0 ]]; then
    warn "未发现应用，检查 apps/ 与 plugins/apps/ 目录"
    return 1
  fi
  printf '  %-14s %-10s %-8s %-8s %s\n' "名称" "分类" "端口" "状态" "说明"
  hr
  local name
  for name in "${SST_APP_ORDER[@]}"; do
    printf '  %-14s %-10s %-8s %-8s %s\n' \
      "$name" "${SST_APP_CATEGORY[$name]}" "${SST_APP_PORT[$name]:--}" \
      "$(app_status_mark "$name")" "${SST_APP_DESC[$name]}"
  done
}

apps_status() {
  local name=${1:-}
  [[ -n $name ]] || die "用法：st app status <名称>"
  app_exists "$name" || die "未知应用：$name"
  section "${SST_APP_TITLE[$name]} 状态"
  if declare -F "app_${name}_status" >/dev/null 2>&1; then
    app_call "$name" status
  else
    app_compose_ps "$name"
  fi
}

apps_install() {
  local name=${1:-}
  if [[ -z $name ]]; then
    die "用法：st app install <名称>（可用：${SST_APP_ORDER[*]}）"
  fi
  app_exists "$name" || die "未知应用：$name"
  require_root
  docker_require || die "应用部署依赖 Docker，请先安装并启动 Docker"
  app_call "$name" install
}

apps_remove() {
  local name=${1:-}
  [[ -n $name ]] || die "用法：st app remove <名称>"
  app_exists "$name" || die "未知应用：$name"
  require_root
  confirm "停止并移除应用 $name 的容器（数据卷默认保留）？" || return 0
  app_call "$name" remove
  ok "已移除应用：$name"
}

apps_help() {
  section "应用插件开发说明"
  cat <<'EOF'
插件目录：apps/<名称>/ 或 plugins/apps/<名称>/
  app.conf  元数据（shell 变量）
    APP_TITLE="显示名称"
    APP_DESC="功能说明"
    APP_CATEGORY="分类"
    APP_PORT="端口"
    APP_URL="访问地址，IP 会被替换为公网 IP"
  app.sh    生命周期函数
    app_<名称>_install()  安装/重新部署，可调用 app_compose_up <名称> 读取 Compose YAML
    app_<名称>_remove()   停止并移除
    app_<名称>_status()   可选，缺省使用 docker compose ps

示例：
  app_compose_up demo <<'YAML'
  services:
    demo:
      image: nginx:alpine
      ports:
        - "8080:80"
  YAML

放入 plugins/apps/ 后无需修改框架，重新执行 st 即自动注册。
EOF
}

app_manage() {
  local name=$1 choice
  while true; do
    section "${SST_APP_TITLE[$name]}"
    kv "说明" "${SST_APP_DESC[$name]}"
    kv "分类" "${SST_APP_CATEGORY[$name]}"
    kv "端口" "${SST_APP_PORT[$name]:--}"
    kv "访问" "$(app_access_url "$name")"
    kv "状态" "$(app_status_mark "$name")"
    printf '\n'
    ui_menu_list $'安装 / 重新部署\n停止并移除容器\n查看运行状态'
    ui_read_choice || break
    choice=$UI_CHOICE
    case $choice in
      1) apps_install "$name"; pause ;;
      2) apps_remove "$name"; pause ;;
      3) apps_status "$name"; pause ;;
      0|q|back) break ;;
      *) warn "无效选项：$choice" ;;
    esac
  done
}

apps_menu() {
  local -a names=("${SST_APP_ORDER[@]}")
  local choice idx name title
  if [[ ${#names[@]} -eq 0 ]]; then
    warn "没有可用应用"
    return 1
  fi

  while true; do
    section "应用市场"
    for idx in "${!names[@]}"; do
      name=${names[$idx]}
      title=${SST_APP_TITLE[$name]}
      ui_menu_item "$((idx + 1))" "$title" \
        "${SST_APP_CATEGORY[$name]} · $(app_status_mark "$name") · ${SST_APP_DESC[$name]}"
    done
    ui_menu_footer
    ui_read_choice "请选择应用" || break
    choice=$UI_CHOICE
    case $choice in
      0|q|back) break ;;
      [0-9]|[0-9][0-9])
        idx=$((choice - 1))
        if (( idx >= 0 && idx < ${#names[@]} )); then
          app_manage "${names[$idx]}"
        else
          warn "无效编号：$choice"
        fi
        ;;
      *)
        if app_exists "$choice"; then
          app_manage "$choice"
        else
          warn "未知应用：$choice"
        fi
        ;;
    esac
  done
}

# --- modules/backup.sh ---
# 模块：备份与迁移

sst_register_module backup "备份迁移" "站点 数据库 定时 远程"
SST_MODULE_ITEMS[backup]=$'list|备份列表\ncreate|创建备份\nrestore|恢复备份\nschedule|定时备份\nremote|远程传输'

backup_dir_get() { cfg_get BACKUP_DIR "$SST_DATA_DIR/backups"; }
backup_targets_get() { cfg_get BACKUP_TARGETS "/etc /var/www"; }

backup_list() {
  local dir f
  dir=$(backup_dir_get)
  section "备份列表"
  if ! compgen -G "$dir/full-*.tar.gz" >/dev/null 2>&1; then
    info "暂无备份，可执行：st backup create"
    return 0
  fi
  printf '  %-32s %10s  %s\n' "文件" "大小" "创建时间"
  hr
  while IFS= read -r f; do
    printf '  %-32s %10s  %s\n' \
      "$(basename "$f")" "$(du -h "$f" | cut -f1)" "$(date -r "$f" '+%Y-%m-%d %H:%M')"
  done < <(ls -1t "$dir"/full-*.tar.gz 2>/dev/null)
  printf '\n  目录：%s\n' "$dir"
}

backup_create() {
  require_root
  local -a raw=() targets=() rels=()
  if [[ $# -gt 0 ]]; then
    raw=("$@")
  elif [[ -t 0 ]]; then
    local input
    input=$(ask "需要备份的路径（空格分隔）" "$(backup_targets_get)")
    read -r -a raw <<<"$input"
    cfg_set BACKUP_TARGETS "${raw[*]}"
  else
    read -r -a raw <<<"$(backup_targets_get)"
  fi

  local t
  for t in "${raw[@]}"; do
    if [[ ! -e $t ]]; then
      warn "跳过不存在的路径：$t"
      continue
    fi
    targets+=("$t")
    rels+=("${t#/}")
  done
  [[ ${#targets[@]} -gt 0 ]] || die "没有可备份的路径"

  confirm "将备份以下路径：${targets[*]}" || return 0

  local dir ts file tmpd
  dir=$(backup_dir_get)
  mkdir -p "$dir" || die "无法创建备份目录：$dir"
  ts=$(date +%Y%m%d-%H%M%S)
  file="$dir/full-$ts.tar.gz"
  tmpd=$(mktemp -d)
  local -a extra=()

  # 数据库导出仅在交互模式下询问，避免 cron 任务误触发
  if [[ -t 0 ]] && { have mysqldump || have mariadb-dump; }; then
    if confirm "同时导出 MySQL/MariaDB 数据库？"; then
      local dumpcmd client pass dbs db
      dumpcmd=mysqldump
      have mariadb-dump && dumpcmd=mariadb-dump
      client=mysql
      have mysql || client=mariadb
      pass=$(ask "MySQL root 密码（留空表示免密 socket）" "")
      mkdir -p "$tmpd/databases"
      dbs=$(MYSQL_PWD="$pass" "$client" -uroot -N -e 'show databases' 2>/dev/null) || true
      for db in $dbs; do
        case $db in
          information_schema|performance_schema|mysql|sys) continue ;;
        esac
        info "导出数据库：$db"
        MYSQL_PWD="$pass" "$dumpcmd" -uroot --single-transaction --quick \
          "$db" >"$tmpd/databases/$db.sql" 2>/dev/null || warn "数据库 $db 导出失败"
      done
      extra=(-C "$tmpd" databases)
    fi
  fi

  info "创建归档：$file"
  if ! tar --ignore-failed-read -czf "$file" -C / "${rels[@]}" "${extra[@]}"; then
    rm -rf "$tmpd"
    rm -f "$file"
    die "备份失败"
  fi
  rm -rf "$tmpd"

  {
    printf 'host=%s\n' "$(hostname)"
    printf 'time=%s\n' "$(date '+%F %T')"
    printf 'paths=%s\n' "${targets[*]}"
  } >"$file.manifest"

  ok "备份完成：$file（$(du -h "$file" | cut -f1)）"
  backup_prune
}

backup_prune() {
  local days dir
  days=$(cfg_get BACKUP_RETENTION 0)
  [[ $days =~ ^[0-9]+$ ]] || days=0
  (( days > 0 )) || return 0
  dir=$(backup_dir_get)
  info "清理 ${days} 天前的备份…"
  find "$dir" -maxdepth 1 -name 'full-*.tar.gz*' -mtime +"$days" -print -delete 2>/dev/null || true
}

backup_restore() {
  require_root
  local dir file target=${2:-/}
  dir=$(backup_dir_get)

  if [[ -n ${1:-} ]]; then
    file=${1}
    [[ -f $file ]] || file="$dir/${1}"
  else
    [[ -t 0 ]] || die "非交互环境请指定备份文件：st backup restore <文件> [目标]"
    local -a files=()
    mapfile -t files < <(ls -1t "$dir"/full-*.tar.gz 2>/dev/null)
    [[ ${#files[@]} -gt 0 ]] || die "没有可用备份"
    local i choice
    section "选择备份"
    for i in "${!files[@]}"; do
      ui_menu_item "$((i + 1))" "$(basename "${files[$i]}")"
    done
    ui_menu_footer "取消"
    ui_read_choice "选择编号" || return 1
    choice=$UI_CHOICE
    [[ $choice =~ ^[0-9]+$ ]] && (( choice >= 1 && choice <= ${#files[@]} )) || {
      [[ $choice == 0 || $choice == q || $choice == back ]] && return 0
      die "无效编号"
    }
    file=${files[$((choice - 1))]}
  fi
  [[ -f $file ]] || die "备份文件不存在：$file"

  section "备份信息"
  [[ -f $file.manifest ]] && cat "$file.manifest"
  kv "归档文件" "$file"
  kv "恢复目标" "$target"
  warn "恢复会覆盖目标目录中的同名文件，请确认已了解影响范围"

  if [[ ${SST_YES:-0} -ne 1 ]]; then
    local phrase
    read -r -p "输入 RESTORE 确认恢复: " phrase || return 1
    [[ $phrase == RESTORE ]] || { warn "已取消"; return 0; }
  fi

  if [[ ! -d $target ]]; then
    mkdir -p "$target" || die "无法创建恢复目标目录：$target"
  fi

  info "开始解压…"
  tar -xzf "$file" -C "$target" --numeric-owner || die "恢复失败"
  ok "恢复完成，请检查服务配置并重启相关服务"
}

backup_schedule() {
  require_root
  local cronfile=/etc/cron.d/sst-backup
  section "定时备份"
  if [[ ${1:-} == remove ]]; then
    rm -f "$cronfile"
    ok "已删除定时备份任务"
    return 0
  fi
  if [[ -f $cronfile ]]; then
    cat "$cronfile"
  else
    info "当前未配置定时备份"
  fi

  confirm "设置/修改每日定时备份？（选择 n 将删除现有任务）" || {
    rm -f "$cronfile"
    ok "已删除定时备份任务"
    return 0
  }

  local time h m retention
  time=$(ask "每天执行时间（HH:MM）" "03:30")
  [[ $time =~ ^([01][0-9]|2[0-3]):[0-5][0-9]$ ]] || die "时间格式错误：$time"
  h=$((10#${time%%:*}))
  m=$((10#${time#*:}))
  retention=$(ask "保留天数（0 表示不自动清理）" "$(cfg_get BACKUP_RETENTION 7)")
  [[ $retention =~ ^[0-9]+$ ]] || die "保留天数必须是数字"

  cfg_set BACKUP_RETENTION "$retention"
  cfg_set BACKUP_TARGETS "$(backup_targets_get)"

  cat >"$cronfile" <<EOF
SHELL=/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
$m $h * * * root "$SST_ENTRY" --yes backup create >> "$SST_LOG" 2>&1
EOF
  chmod 644 "$cronfile"
  ok "已设置每天 $time 执行备份，保留 ${retention} 天"
  info "备份路径来自配置 BACKUP_TARGETS=$(backup_targets_get)"
}

backup_remote() {
  local all=0 dir file host remote_dir
  [[ ${1:-} == all ]] && all=1
  dir=$(backup_dir_get)
  host=$(ask "远程主机（user@host）" "")
  [[ -n $host ]] || return 0
  remote_dir=$(ask "远程目录" "/root/backups")

  if ! have rsync; then
    confirm "安装 rsync 用于远程传输？" || return 0
    pkg_install rsync || die "rsync 安装失败"
  fi

  if (( all == 1 )); then
    info "传输全部备份到 $host:$remote_dir …"
    rsync -avz --progress "$dir"/ "$host:$remote_dir"/
  else
    mapfile -t files < <(ls -1t "$dir"/full-*.tar.gz 2>/dev/null)
    [[ ${#files[@]} -gt 0 ]] || die "没有可用备份"
    file=${files[0]}
    info "传输 $(basename "$file") 到 $host:$remote_dir …"
    rsync -avz --progress "$file" "$file.manifest" "$host:$remote_dir"/ 2>/dev/null \
      || rsync -avz --progress "$file" "$host:$remote_dir"/
  fi
  ok "远程传输完成"
}

# --- modules/bench.sh ---
# 模块：性能与综合测试
# 原生实现内存/磁盘/CPU 测试，第三方测试脚本统一走脚本市场。

sst_register_module bench "性能测试" "内存 磁盘 CPU 与综合测试"
SST_MODULE_ITEMS[bench]=$'memtest|内存压力测试\ndiskbench|磁盘读写测试\ncpu|CPU 基准测试\nscripts|第三方测试脚本\nsuperbench|Superbench 综合测试\nlemonbench|Lemonbench 综合测试\nunixbench|UNIXbench 综合测试\nyabs|YABS 综合测试\nnodequality|NodeQuality 综合测试\ntcpquality|TCP 质量测试\nsuperspeed|三网测速\nspeedtest|Ookla SpeedTest\nmedia|流媒体解锁检测\nmt|MT 流媒体检测\ntubecheck|YouTube CDN 检测\nbesttrace|Besttrace 路由追踪\ndisktest|Disk Test 综合测试\nroutetrace|三网回程路由'

bench_memtest() {
  require_root
  local size iters
  size=$(ask "测试内存大小（如 512M、1G）" "512M")
  [[ $size =~ ^[0-9]+[GgMm]$ ]] || die "大小格式错误，示例：512M / 1G"
  iters=$(ask "循环次数" "2")
  [[ $iters =~ ^[0-9]+$ ]] && (( iters >= 1 )) || die "循环次数必须是正整数"

  confirm "memtester 将占用 $size 内存并运行 $iters 轮，可能影响线上服务，继续？" || return 0
  info "memtester 未安装时会先通过包管理器安装…"
  ensure_tool memtester memtester || return 1
  memtester "$size" "$iters"
}

bench_diskbench() {
  local size=${1:-100} file out
  [[ $size =~ ^[0-9]+$ ]] && (( size >= 10 && size <= 2048 )) \
    || die "测试大小需在 10-2048 MB 之间"
  file="/tmp/sst-disk-test-$$"

  confirm "将在 $file 写入 ${size}MB 测试数据（会自动删除），继续？" || return 0

  info "顺序写入测试…"
  if ! out=$(LC_ALL=C dd if=/dev/zero of="$file" bs=1M count="$size" oflag=direct conv=fdatasync 2>&1); then
    warn "direct IO 不可用，改用普通写入（结果可能受缓存影响）"
    if ! out=$(LC_ALL=C dd if=/dev/zero of="$file" bs=1M count="$size" conv=fdatasync 2>&1); then
      rm -f "$file"
      die "写入测试失败，请检查 /tmp 空间"
    fi
  fi
  kv "写入" "$(printf '%s\n' "$out" | tail -n 1)"

  sync
  if [[ ${EUID:-1} -eq 0 ]]; then
    echo 3 >/proc/sys/vm/drop_caches 2>/dev/null || true
  fi

  info "顺序读取测试…"
  if ! out=$(LC_ALL=C dd if="$file" of=/dev/null bs=1M iflag=direct 2>&1); then
    warn "direct 读取不可用，结果可能受缓存影响"
    out=$(LC_ALL=C dd if="$file" of=/dev/null bs=1M 2>&1) || true
  fi
  kv "读取" "$(printf '%s\n' "$out" | tail -n 1)"

  rm -f "$file"
  ok "磁盘测试完成，测试文件已清理"
}

bench_cpu() {
  require_root
  local cores
  cores=$(nproc 2>/dev/null || echo 1)
  confirm "使用 sysbench 对 ${cores} 线程进行 CPU 整数运算测试？" || return 0
  info "sysbench 未安装时会先通过包管理器安装…"
  ensure_tool sysbench sysbench || return 1
  section "CPU 基准测试（cpu-max-prime=20000）"
  sysbench cpu --cpu-max-prime=20000 --threads="$cores" run
}

bench_scripts() { scripts_menu 测试; }

bench_nodequality() { scripts_run nodequality "$@"; }

bench_tcpquality() { scripts_run tcpquality "$@"; }

# --- modules/components.sh ---
# 模块：常用组件、语言环境与 tmux 工作区

sst_register_module components "组件环境" "常用工具 语言环境 Ansible"
SST_MODULE_ITEMS[components]=$'list|组件清单\ninstall|安装组件\ninstall_all|安装全部组件\nremove|卸载组件\ncustom|安装自定义包\npython|Python 环境\nnodejs|Node.js 环境\ngolang|Go 环境\njava|Java 环境\nuninstall_env|卸载语言环境\nworkspace|tmux 工作区'

COMP_KEYS=(curl wget sudo socat htop iftop unzip tar tmux ffmpeg btop ranger gdu fzf screen masscan cmatrix sl bastet nsnake ninvaders ansible)
COMP_PKGS=(curl wget sudo socat htop iftop unzip tar tmux ffmpeg btop ranger gdu fzf screen masscan cmatrix sl bastet nsnake ninvaders ansible)
COMP_DESCS=("HTTP 下载工具" "下载工具" "权限管理" "网络通信/证书辅助" "进程监控" "网络流量监控" "ZIP 解压" "GZ 压缩解压" "终端复用" "视频编码/推流" "现代监控工具" "终端文件管理器" "磁盘占用分析" "全局模糊搜索" "后台会话" "端口扫描" "黑客帝国屏保" "跑火车屏保" "俄罗斯方块" "贪吃蛇" "太空入侵者" "自动化运维")

comp_installed() {
  have "$1" || [[ -x "/usr/games/$1" ]]
}

components_list() {
  section "组件清单"
  printf '  %3s  %-12s %-8s %s\n' "序号" "组件" "状态" "说明"
  hr
  local i
  for i in "${!COMP_KEYS[@]}"; do
    printf '  %3d  %-12s %-8s %s\n' \
      "$((i + 1))" "${COMP_KEYS[$i]}" \
      "$(comp_installed "${COMP_KEYS[$i]}" && echo 已安装 || echo 未安装)" \
      "${COMP_DESCS[$i]}"
  done
}

components_parse_selection() {
  local input=$1 i
  input=${input//,/ }
  local -a idxs=()
  for i in $input; do
    [[ $i =~ ^[0-9]+$ ]] || die "无效编号：$i"
    (( i >= 1 && i <= ${#COMP_KEYS[@]} )) || die "编号超出范围：$i"
    idxs+=("$((i - 1))")
  done
  printf '%s\n' "${idxs[@]}"
}

components_install() {
  require_root
  components_list
  local input
  input=$(ask "要安装的编号（空格分隔，all=全部）" "all")
  local -a idxs=()
  if [[ $input == all ]]; then
    idxs=("${!COMP_KEYS[@]}")
  else
    local parsed
    parsed=$(components_parse_selection "$input") || return 1
    mapfile -t idxs <<<"$parsed"
  fi
  [[ ${#idxs[@]} -gt 0 ]] || return 0

  confirm "安装以上 ${#idxs[@]} 个组件？" || return 0
  pkg_update || die "软件源更新失败"
  local idx failed=0
  for idx in "${idxs[@]}"; do
    info "安装 ${COMP_KEYS[$idx]}（${COMP_DESCS[$idx]}）…"
    pkg_install "${COMP_PKGS[$idx]}" || { warn "${COMP_KEYS[$idx]} 安装失败"; failed=$((failed + 1)); }
  done
  if (( failed == 0 )); then
    ok "全部组件安装完成"
  else
    warn "完成，但有 ${failed} 个组件安装失败（可能当前发行版无对应软件包）"
  fi
}

components_install_all() {
  require_root
  confirm "安装全部 ${#COMP_KEYS[@]} 个组件？" || return 0
  pkg_update || die "软件源更新失败"
  local i failed=0
  for i in "${!COMP_KEYS[@]}"; do
    info "安装 ${COMP_KEYS[$i]}…"
    pkg_install "${COMP_PKGS[$i]}" || { warn "${COMP_KEYS[$i]} 安装失败"; failed=$((failed + 1)); }
  done
  ok "批量安装结束，失败 ${failed} 个"
}

components_remove() {
  require_root
  section "已安装组件"
  local -a installed=()
  local i
  for i in "${!COMP_KEYS[@]}"; do
    if comp_installed "${COMP_KEYS[$i]}"; then
      installed+=("$i")
      printf '  %3d  %-12s %s\n' "$((i + 1))" "${COMP_KEYS[$i]}" "${COMP_DESCS[$i]}"
    fi
  done
  [[ ${#installed[@]} -gt 0 ]] || { info "没有已安装的组件"; return 0; }

  local input
  input=$(ask "要卸载的编号（空格分隔）" "")
  [[ -n $input ]] || return 0
  local -a idxs=()
  local parsed
  parsed=$(components_parse_selection "$input") || return 1
  mapfile -t idxs <<<"$parsed"
  [[ ${#idxs[@]} -gt 0 ]] || return 0

  local -a pkgs=()
  for i in "${idxs[@]}"; do pkgs+=("${COMP_PKGS[$i]}"); done
  confirm "卸载：${pkgs[*]}（可能同时移除依赖）？" || return 0
  pkg_remove "${pkgs[@]}" || warn "部分组件卸载失败"
  ok "卸载完成"
}

components_custom() {
  require_root
  local pkgs
  pkgs=$(ask "要安装的软件包名（空格分隔）" "")
  [[ -n $pkgs ]] || return 0
  local -a list=()
  read -r -a list <<<"$pkgs"
  confirm "安装：${list[*]}？" || return 0
  pkg_update || die "软件源更新失败"
  pkg_install "${list[@]}" || die "安装失败：${list[*]}"
  ok "安装完成"
}

components_env_pkgs() {
  local lang=$1
  case $PKG:$lang in
    apt:python) printf '%s\n' "python3 python3-pip python3-venv" ;;
    dnf:python|yum:python) printf '%s\n' "python3 python3-pip" ;;
    apk:python) printf '%s\n' "python3 py3-pip" ;;
    pacman:python) printf '%s\n' "python python-pip" ;;
    zypper:python) printf '%s\n' "python3 python3-pip" ;;
    apt:node) printf '%s\n' "nodejs npm" ;;
    dnf:node|yum:node) printf '%s\n' "nodejs npm" ;;
    apk:node) printf '%s\n' "nodejs npm" ;;
    pacman:node) printf '%s\n' "nodejs npm" ;;
    zypper:node) printf '%s\n' "nodejs npm" ;;
    apt:go) printf '%s\n' "golang-go" ;;
    dnf:go|yum:go) printf '%s\n' "golang" ;;
    apk:go) printf '%s\n' "go" ;;
    pacman:go) printf '%s\n' "go" ;;
    zypper:go) printf '%s\n' "go" ;;
    apt:java) printf '%s\n' "openjdk-17-jdk" ;;
    dnf:java|yum:java) printf '%s\n' "java-17-openjdk-devel" ;;
    apk:java) printf '%s\n' "openjdk17" ;;
    pacman:java) printf '%s\n' "jdk17-openjdk" ;;
    zypper:java) printf '%s\n' "java-17-openjdk-devel" ;;
    *) return 1 ;;
  esac
}

components_env_install() {
  local lang=$1 label=$2
  require_root
  local pkgs out
  out=$(components_env_pkgs "$lang") || die "当前系统不支持安装 $label"
  read -r -a pkgs <<<"$out"
  confirm "通过系统包管理器安装 $label（${pkgs[*]}）？发行版仓库版本可能不是最新" || return 0
  pkg_update || die "软件源更新失败"
  pkg_install "${pkgs[@]}" || die "$label 安装失败"
  ok "$label 安装完成"
  case $lang in
    python) python3 --version 2>/dev/null || true ;;
    node) node --version 2>/dev/null || true ;;
    go) go version 2>/dev/null || true ;;
    java) java -version 2>&1 | head -n 1 || true ;;
  esac
}

components_python() { components_env_install python "Python3"; }
components_nodejs() { components_env_install node "Node.js"; }
components_golang() { components_env_install go "Golang"; }
components_java() { components_env_install java "OpenJDK 17"; }

components_uninstall_env() {
  require_root
  section "卸载语言环境"
  local choice lang label
  ui_menu_list $'Python3\nNode.js\nGolang\nOpenJDK 17'
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) lang=python label=Python3 ;;
    2) lang=node label="Node.js" ;;
    3) lang=go label=Golang ;;
    4) lang=java label="OpenJDK 17" ;;
    0|q|back) return 0 ;;
    *) warn "无效选项"; return 0 ;;
  esac

  local pkgs out
  out=$(components_env_pkgs "$lang") || die "当前系统不支持卸载 $label"
  read -r -a pkgs <<<"$out"
  warn "卸载 $label 可能影响依赖它的其他软件，Python3 在部分发行版中还是系统依赖"
  if [[ $lang == python ]]; then
    local phrase
    read -r -p "输入 REMOVE 确认卸载 $label: " phrase || return 1
    [[ $phrase == REMOVE ]] || { warn "已取消"; return 0; }
  else
    confirm "确认卸载 $label（${pkgs[*]}）？" || return 0
  fi
  pkg_remove "${pkgs[@]}" || warn "部分软件包卸载失败"
  ok "$label 卸载流程结束"
}

components_workspace() {
  local choice name
  while true; do
    section "tmux 工作区"
    if have tmux; then
      tmux ls 2>/dev/null || info "暂无 tmux 会话"
    else
      warn "tmux 未安装"
    fi
    printf '\n'
    ui_menu_option "1-5" "进入对应工作区（不存在则创建）"
    ui_menu_option "a" "安装 tmux"
    ui_menu_option "b" "卸载 tmux"
    ui_menu_footer
    ui_read_choice || break
    choice=$UI_CHOICE
    case $choice in
      [1-5])
        if ! have tmux; then
          confirm "tmux 未安装，现在安装？" || continue
          pkg_update || die "软件源更新失败"
          pkg_install tmux || die "tmux 安装失败"
        fi
        name="work$choice"
        info "进入工作区 $name（Ctrl+b 再按 d 退出，任务会继续后台运行）"
        tmux new-session -A -s "$name"
        ;;
      a)
        require_root
        pkg_update || die "软件源更新失败"
        pkg_install tmux || die "tmux 安装失败"
        ok "tmux 安装完成"
        ;;
      b)
        require_root
        confirm "卸载 tmux？现有后台会话会全部结束" || continue
        pkg_remove tmux || warn "tmux 卸载失败"
        ok "tmux 已卸载"
        ;;
      0|q|back) break ;;
      *) warn "无效选项：$choice" ;;
    esac
  done
}

# --- modules/docker.sh ---
# 模块：Docker 管理

sst_register_module docker "Docker" "安装 容器 日志 清理"
SST_MODULE_ITEMS[docker]=$'status|运行状态\ninstall|安装 Docker\nps|容器列表\nlogs|查看日志\nrestart|重启容器\nstart|启动容器\nstop|停止容器\nexec|进入容器\nimages|镜像管理\nnetworks|网络管理\nvolumes|卷管理\nprune|清理空间\ncompose|Compose 项目\nuninstall|卸载 Docker'

docker_require() {
  if ! have docker; then
    warn "未检测到 Docker"
    if [[ -t 0 ]] && confirm "是否现在安装 Docker？"; then
      docker_install || return 1
    else
      return 1
    fi
  fi
  if ! docker info >/dev/null 2>&1; then
    warn "Docker 守护进程未运行，尝试启动…"
    require_root
    svc_enable docker || true
    sleep 2
    if ! docker info >/dev/null 2>&1; then
      err "Docker 无法启动，请检查：systemctl status docker"
      return 1
    fi
  fi
  return 0
}

docker_install() {
  require_root
  if have docker; then
    info "已安装：$(docker --version 2>/dev/null)"
    confirm "重新安装/升级 Docker？" || return 0
  else
    confirm "将从 get.docker.com 拉取并执行官方安装脚本，继续？" || return 0
  fi

  ensure_tool curl curl || return 1
  local mirror='' installer
  if confirm "使用阿里云镜像源加速下载？"; then
    mirror="https://mirrors.aliyun.com/docker-ce"
  fi

  info "开始安装 Docker…"
  installer=$(mktemp)
  if ! curl -fsSL --connect-timeout 10 --max-time 300 -o "$installer" https://get.docker.com; then
    rm -f "$installer"
    die "下载 Docker 安装脚本失败"
  fi
  if [[ -n $mirror ]]; then
    ( export DOWNLOAD_URL="$mirror"; bash "$installer" ) || { rm -f "$installer"; die "Docker 安装失败"; }
  else
    bash "$installer" || { rm -f "$installer"; die "Docker 安装失败"; }
  fi
  rm -f "$installer"

  svc_enable docker || warn "Docker 服务启用失败，请手动检查"
  docker --version 2>/dev/null
  ok "Docker 安装完成"
  info "非 root 用户可使用：usermod -aG docker <用户名>"
}

docker_status() {
  section "Docker 状态"
  if ! have docker; then
    warn "未安装 Docker，可执行：st docker install"
    return 1
  fi
  kv "版本" "$(docker --version 2>/dev/null | sed 's/^Docker version //;s/,.*//')"
  if docker compose version >/dev/null 2>&1; then
    kv "Compose" "$(docker compose version --short 2>/dev/null)"
  elif have docker-compose; then
    kv "Compose" "$(docker-compose version --short 2>/dev/null || echo 已安装)"
  else
    kv "Compose" "未安装插件"
  fi
  kv "服务状态" "$(svc_active docker && echo 运行中 || echo 未运行)"

  if ! docker info >/dev/null 2>&1; then
    warn "Docker 守护进程不可用，运行状态信息跳过"
    return 1
  fi
  local running total images
  running=$(docker ps -q 2>/dev/null | wc -l)
  total=$(docker ps -aq 2>/dev/null | wc -l)
  images=$(docker images -q 2>/dev/null | wc -l)
  kv "容器" "运行 ${running} / 共 ${total}"
  kv "镜像" "$images"
  printf '\n'
  docker system df 2>/dev/null || true
}

docker_ps() {
  docker_require || return 1
  section "容器列表"
  docker ps -a --format 'table {{.Names}}\t{{.Image}}\t{{.Status}}\t{{.Ports}}' 2>/dev/null
}

docker_logs() {
  docker_require || return 1
  local name=${1:-} lines=${2:-100}
  if [[ -z $name ]]; then
    name=$(docker_pick) || return 0
  fi
  docker logs --tail "$lines" "$name" 2>&1
  if [[ -t 0 ]] && confirm "持续跟踪日志（Ctrl+C 退出）？"; then
    docker logs -f --tail 0 "$name" 2>&1
  fi
}

docker_restart() {
  require_root
  docker_require || return 1
  local name=${1:-}
  [[ -n $name ]] || name=$(docker_pick) || return 0
  docker restart "$name" && ok "已重启容器：$name"
}

docker_start() {
  require_root
  docker_require || return 1
  local name=${1:-}
  [[ -n $name ]] || name=$(docker_pick) || return 0
  docker start "$name" && ok "已启动容器：$name"
}

docker_stop() {
  require_root
  docker_require || return 1
  local name=${1:-}
  [[ -n $name ]] || name=$(docker_pick) || return 0
  docker stop "$name" && ok "已停止容器：$name"
}

docker_prune() {
  require_root
  docker_require || return 1
  section "当前空间占用"
  docker system df 2>/dev/null || true

  confirm "清理已停止容器、未使用网络与悬空镜像？" || return 0
  docker system prune -f || warn "基础清理未完成"
  if confirm "同时清理所有未被使用的镜像（-a）？"; then
    docker system prune -a -f || warn "镜像清理未完成"
  fi
  if [[ ${SST_YES:-0} -ne 1 ]] && [[ -t 0 ]] \
    && confirm "清理未被使用的数据卷（会删除卷内数据！）？"; then
    docker volume prune -f || warn "卷清理未完成"
  fi
  section "清理后空间占用"
  docker system df 2>/dev/null || true
}

docker_compose_ps() {
  if docker compose version >/dev/null 2>&1; then
    docker compose ls 2>/dev/null || true
  elif have docker-compose; then
    docker ps -a --filter 'label=com.docker.compose.project' \
      --format 'table {{.Label "com.docker.compose.project"}}\t{{.Names}}\t{{.Status}}' 2>/dev/null
  else
    return 1
  fi
}

docker_compose_file() {
  local path f
  path=$(ask "Compose 文件或项目目录" ".")
  [[ -n $path ]] || return 1
  if [[ -d $path ]]; then
    for f in "$path/compose.yml" "$path/compose.yaml" "$path/docker-compose.yml" "$path/docker-compose.yaml"; do
      if [[ -f $f ]]; then
        printf '%s\n' "$f"
        return 0
      fi
    done
    warn "目录中未找到 compose.yml / docker-compose.yml：$path"
    return 1
  fi
  if [[ ! -f $path ]]; then
    warn "Compose 文件不存在：$path"
    return 1
  fi
  printf '%s\n' "$path"
}

docker_compose() {
  docker_require || return 1
  section "Compose 项目"
  if ! docker_compose_ps; then
    warn "未安装 Docker Compose，可参考：apt install docker-compose-plugin"
    return 0
  fi
  [[ -t 0 ]] || return 0

  local choice file
  ui_menu_list $'启动/更新项目\n拉取镜像并更新\n停止并移除项目\n重启项目\n查看最近日志' "返回"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    0|q|back) return 0 ;;
    1|2|3|4|5) ;;
    *) warn "无效选项：$choice"; return 0 ;;
  esac

  file=$(docker_compose_file) || return 0
  case $choice in
    1)
      if compose_run -f "$file" up -d; then
        ok "Compose 项目已启动/更新：$file"
        compose_run -f "$file" ps 2>/dev/null || true
      else
        warn "Compose 启动失败：$file"
      fi
      ;;
    2)
      if compose_run -f "$file" pull && compose_run -f "$file" up -d; then
        ok "镜像已拉取并更新：$file"
        compose_run -f "$file" ps 2>/dev/null || true
      else
        warn "镜像拉取或更新失败：$file"
      fi
      ;;
    3)
      ui_confirm_danger "将停止并移除 Compose 项目容器。" \
        "项目文件：$file（数据卷默认保留）" \
        "重新启动：st docker compose" || return 0
      if compose_run -f "$file" down --remove-orphans; then
        ok "Compose 项目已停止：$file"
      else
        warn "Compose 停止失败：$file"
      fi
      ;;
    4)
      if compose_run -f "$file" restart; then
        ok "Compose 项目已重启：$file"
        compose_run -f "$file" ps 2>/dev/null || true
      else
        warn "Compose 重启失败：$file"
      fi
      ;;
    5)
      compose_run -f "$file" logs --tail=50 || warn "读取日志失败：$file"
      ;;
  esac
}

docker_exec() {
  require_root
  docker_require || return 1
  local name=${1:-}
  [[ -n $name ]] || name=$(docker_pick) || return 0
  docker exec -it "$name" sh -c 'command -v bash >/dev/null 2>&1 && exec bash || exec sh'
}

docker_images() {
  require_root
  docker_require || return 1
  section "镜像列表"
  docker images
  local -a ids=() labels=()
  while IFS=' ' read -r repo id size; do
    [[ -n $id ]] || continue
    ids+=("$id")
    labels+=("$repo $size")
  done < <(docker images --format '{{.Repository}}:{{.Tag}} {{.ID}} {{.Size}}' 2>/dev/null)
  [[ ${#ids[@]} -gt 0 ]] || { info "没有镜像"; return 0; }

  local i sel
  printf '\n'
  for i in "${!ids[@]}"; do
    ui_menu_item "$((i + 1))" "${labels[$i]}"
  done
  ui_menu_footer
  ui_read_choice "要删除的镜像编号" || return 0
  sel=$UI_CHOICE
  [[ $sel == 0 ]] && return 0
  [[ $sel =~ ^[0-9]+$ ]] && (( sel >= 1 && sel <= ${#ids[@]} )) || die "无效编号"
  confirm "删除镜像 ${labels[$((sel - 1))]}？" || return 0
  docker rmi "${ids[$((sel - 1))]}"
}

docker_networks() {
  require_root
  docker_require || return 1
  section "网络列表"
  docker network ls
  local -a names=()
  mapfile -t names < <(docker network ls --format '{{.Name}}' 2>/dev/null)
  local i sel
  printf '\n'
  for i in "${!names[@]}"; do
    ui_menu_item "$((i + 1))" "${names[$i]}"
  done
  ui_menu_footer
  ui_read_choice "要删除的网络编号" || return 0
  sel=$UI_CHOICE
  [[ $sel == 0 ]] && return 0
  [[ $sel =~ ^[0-9]+$ ]] && (( sel >= 1 && sel <= ${#names[@]} )) || die "无效编号"
  local name=${names[$((sel - 1))]}
  case $name in
    bridge|host|none) die "内置网络 $name 不能删除" ;;
  esac
  confirm "删除网络 $name？" || return 0
  docker network rm "$name"
}

docker_volumes() {
  require_root
  docker_require || return 1
  section "数据卷列表"
  docker volume ls
  local -a names=()
  mapfile -t names < <(docker volume ls --format '{{.Name}}' 2>/dev/null)
  local i sel
  printf '\n'
  for i in "${!names[@]}"; do
    ui_menu_item "$((i + 1))" "${names[$i]}"
  done
  ui_menu_footer
  ui_read_choice "要删除的卷编号" || return 0
  sel=$UI_CHOICE
  [[ $sel == 0 ]] && return 0
  [[ $sel =~ ^[0-9]+$ ]] && (( sel >= 1 && sel <= ${#names[@]} )) || die "无效编号"
  local name=${names[$((sel - 1))]}
  confirm "删除数据卷 $name？卷内数据会永久丢失" || return 0
  docker volume rm "$name"
}

docker_uninstall() {
  require_root
  confirm "停止所有容器并卸载 Docker？" || return 0
  if have docker; then
    if confirm "先删除所有容器？"; then
      mapfile -t ids < <(docker ps -aq 2>/dev/null)
      [[ ${#ids[@]} -gt 0 ]] && docker rm -f "${ids[@]}" >/dev/null 2>&1 || true
    fi
    if confirm "删除所有镜像？"; then
      mapfile -t ids < <(docker images -aq 2>/dev/null)
      [[ ${#ids[@]} -gt 0 ]] && docker rmi -f "${ids[@]}" >/dev/null 2>&1 || true
    fi
  fi

  case ${PKG:-unknown} in
    apt) pkg_remove docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin docker-compose || true ;;
    dnf|yum) pkg_remove docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin || true ;;
    apk) pkg_remove docker docker-cli-compose || true ;;
    pacman) pkg_remove docker docker-compose || true ;;
    zypper) pkg_remove docker docker-compose || true ;;
  esac
  ok "Docker 软件包卸载流程结束"
  if confirm "同时删除 /var/lib/docker 与 /etc/docker（所有容器数据会永久丢失）？"; then
    rm -rf /var/lib/docker /etc/docker
    ok "Docker 数据目录已删除"
  fi
}

# --- modules/init.sh ---
# 模块：开荒向导（预检 / 磁盘 / 基础信息 / 账户 / SSH / 防火墙 / 报告）

sst_register_module init "开荒向导" "预检 磁盘 账户 SSH 防火墙"
SST_MODULE_ITEMS[init]=$'wizard|开始/继续开荒\npreflight|服务器预检\ndisk|磁盘检测与挂载\nbasics|基础信息设置\naccounts|账户设置\nssh|SSH 安全\nfirewall|防火墙与防护\nhardening|系统加固\nstatus|查看进度\nreport|生成报告\nreset|重置向导'

init_status() {
  require_root
  # 只读查看：状态文件不存在时按 0/8 显示，不创建向导状态
  wizard_status_table
  if [[ $(wizard_step_status preflight) == pending ]]; then
    info "运行 st init 开始，或 st init preflight 单独执行预检"
  fi
}

init_preflight_show() {
  local mem_total mem_used mem_avail cpu cores disk swap_state ip keys ufw docker_ver
  local ssh_ports root_login pass_auth bbr tz syncookie
  cpu=$(get_cpu_model)
  [[ -n $cpu ]] || cpu="未知"
  cores=$(nproc 2>/dev/null || echo 未知)
  read -r mem_total mem_used mem_avail <<<"$(get_mem_info)"
  disk=$(df -h / 2>/dev/null | awk 'NR==2 {printf "%s 已用 %s (%s)", $2, $3, $5}')
  if have free; then
    swap_state=$(free -m 2>/dev/null | awk 'NR==3 {if ($2 == 0) print "未启用"; else printf "%d/%d MB (%d%%)", $3, $2, $3 * 100 / $2}')
  else
    swap_state=$(awk '/SwapTotal/ {t=$2} /SwapFree/ {f=$2} END {if (t == 0) print "未启用"; else printf "%d/%d MB", t/1024-f/1024, t/1024}' /proc/meminfo 2>/dev/null)
  fi
  ip=$(get_public_ip)
  keys=$(find /root /home -maxdepth 4 -name authorized_keys -type f -size +0c 2>/dev/null | wc -l)
  ufw=$(_fw_installed)
  docker_ver="未安装"
  have docker && docker_ver=$(docker --version 2>/dev/null | sed 's/^Docker version //;s/,.*//')
  ssh_ports=$(ssh_all_ports)
  root_login=$(ssh_cfg_get PermitRootLogin)
  pass_auth=$(ssh_cfg_get PasswordAuthentication)
  bbr=$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || echo 未知)
  if have timedatectl; then
    tz=$(timedatectl show -p Timezone --value 2>/dev/null || date +%Z)
  else
    tz=$(date +%Z)
  fi

  section "服务器预检"
  kv "主机名" "$(hostname)"
  kv "系统" "$OS_NAME"
  kv "内核" "$(uname -r)"
  kv "架构" "$ARCH"
  kv "虚拟化" "$VIRT"
  kv "CPU" "$cpu（${cores} 核）"
  kv "内存" "${mem_used}/${mem_total} MB（可用 ${mem_avail} MB）"
  kv "磁盘 /" "$disk"
  kv "SWAP" "$swap_state"
  kv "公网 IP" "$ip"
  kv "时区" "$tz"
  kv "DNS" "$(awk '/^nameserver/ {printf "%s ", $2}' /etc/resolv.conf 2>/dev/null)"
  hr
  kv "SSH 端口" "$ssh_ports"
  kv "root 登录" "$root_login"
  kv "密码登录" "$pass_auth"
  kv "SSH 密钥" "${keys} 个用户含 authorized_keys"
  kv "防火墙" "$ufw / $(_ufw_state)"
  kv "Docker" "$docker_ver"
  kv "TCP 算法" "$bbr"

  section "预检提示"
  (( keys > 0 )) || warn "未发现 authorized_keys，暂不建议关闭密码登录"
  [[ $pass_auth == yes ]] && warn "当前允许密码登录，完成密钥验证后建议关闭"
  [[ $root_login == yes ]] && warn "当前允许 root 密码登录，安全基线建议收紧"
  [[ $ufw == ufw && $(_ufw_state) == inactive ]] && warn "UFW 未启用，安全基线建议启用"
  have docker && warn "已安装 Docker：UFW 不能完全保护 Docker 发布的端口"
  syncookie=$(sysctl -n net.ipv4.tcp_syncookies 2>/dev/null || true)
  [[ -n $syncookie && $syncookie != 1 ]] && warn "TCP syncookies 未启用"
}

init_preflight() {
  require_root
  wizard_init
  init_preflight_show
  confirm "预检完成，标记为已完成？" || return 0
  wizard_mark preflight done
  ok "预检已记录"
}

init_disk_scan() {
  section "磁盘扫描"
  info "只读扫描，不会格式化或删除任何数据"
  if have lsblk; then
    lsblk -o NAME,SIZE,TYPE,FSTYPE,MOUNTPOINT,UUID,MODEL,ROTA 2>/dev/null
  else
    warn "lsblk 不可用，请安装 util-linux"
  fi
  hr
  df -hT 2>/dev/null || df -h
  hr
  local root_src chain c
  root_src=$(findmnt -n -o SOURCE / 2>/dev/null || true)
  if [[ -n $root_src ]]; then
    mapfile -t chain < <(lsblk -s -no NAME "$root_src" 2>/dev/null)
    kv "根分区" "$root_src"
    kv "系统盘链路" "$(printf '%s' "${chain[*]}")"
  else
    warn "无法识别根分区来源（可能是 overlay/容器）"
  fi
  if have swapon; then
    printf '\n'
    swapon --show 2>/dev/null || true
  fi
  warn "带文件系统的未挂载分区可在下一步“挂载已有文件系统”，向导不提供格式化"
}

init_disk_is_system() {
  local device=$1 root_src chain c parent name
  root_src=$(findmnt -n -o SOURCE / 2>/dev/null || true)
  [[ -n $root_src ]] || return 2
  name=$(basename "$device")
  parent=$(lsblk -no PKNAME "$device" 2>/dev/null | head -n 1)
  mapfile -t chain < <(lsblk -s -no NAME "$root_src" 2>/dev/null)
  for c in "${chain[@]}"; do
    [[ $c == "$name" ]] && return 0
    [[ -n $parent && $c == "$parent" ]] && return 0
  done
  return 1
}

init_disk_details() {
  local device
  device=$(ask "设备路径（如 /dev/sdb1）" "")
  [[ -n $device ]] || return 0
  [[ -b $device ]] || die "不是块设备：$device"
  section "设备详情：$device"
  lsblk -o NAME,SIZE,TYPE,FSTYPE,MOUNTPOINT,UUID,MODEL,SERIAL,ROTA "$device" 2>/dev/null
  hr
  blkid "$device" 2>/dev/null || true
  if have smartctl; then
    smartctl -H "$device" 2>/dev/null || warn "SMART 状态不可读"
  else
    info "安装 smartmontools 可查看 SMART 健康状态"
  fi
}

init_disk_mount_existing() {
  local device mounted dev_type children fstype mountpoint uuid entry fstab_backup old
  section "挂载已有文件系统"
  lsblk -o NAME,SIZE,TYPE,FSTYPE,MOUNTPOINT,UUID,MODEL 2>/dev/null
  printf '\n'
  device=$(ask "要挂载的设备（如 /dev/sdb1，留空取消）" "")
  [[ -n $device ]] || return 0
  [[ -b $device ]] || die "不是块设备：$device"

  mounted=$(lsblk -no MOUNTPOINT "$device" 2>/dev/null | head -n 1)
  [[ -z $mounted ]] || die "$device 已挂载或正在使用（$mounted）"

  dev_type=$(lsblk -ndo TYPE "$device" 2>/dev/null | head -n 1)
  if [[ $dev_type == disk ]]; then
    children=$(lsblk -no NAME "$device" 2>/dev/null | wc -l)
    (( children <= 1 )) || die "该磁盘已有分区，请选择分区设备（如 ${device}1）"
  fi

  fstype=$(lsblk -no FSTYPE "$device" 2>/dev/null | head -n 1)
  if [[ -z $fstype ]]; then
    die "$device 没有文件系统；向导不执行格式化，请先手动创建文件系统"
  fi
  case $fstype in
    swap|LVM2_member|crypto_LUKS|linux_raid_member)
      die "$device 类型为 $fstype，已拒绝自动挂载" ;;
    ntfs|vfat)
      warn "文件系统 $fstype 需要额外驱动或权限，建议手动挂载" ;;
  esac

  init_disk_is_system "$device"
  case $? in
    0) die "$device 属于系统盘，已拒绝操作" ;;
    2) die "无法确认系统盘来源，已拒绝自动挂载" ;;
  esac

  mountpoint=$(ask "挂载点" "/data")
  [[ $mountpoint == /* ]] || die "挂载点必须是绝对路径"
  findmnt -n "$mountpoint" >/dev/null 2>&1 && die "$mountpoint 已被占用"

  uuid=$(blkid -s UUID -o value "$device" 2>/dev/null || true)
  if [[ -n $uuid ]]; then
    entry="UUID=$uuid $mountpoint $fstype defaults,nofail 0 0"
  else
    warn "无法读取 UUID，将使用设备路径；设备名变化时可能挂载失败"
    entry="$device $mountpoint $fstype defaults,nofail 0 0"
  fi

  fstab_backup=$(backup_config_file /etc/fstab fstab) || die "备份 /etc/fstab 失败"
  if awk -v m="$mountpoint" '$2 == m {found=1} END {exit !found}' /etc/fstab; then
    info "/etc/fstab 已存在 $mountpoint，跳过写入"
  else
    printf '%s\n' "$entry" >>/etc/fstab
    info "已写入 /etc/fstab：$entry"
  fi

  mkdir -p "$mountpoint" || { cp "$fstab_backup" /etc/fstab; die "无法创建挂载点"; }
  if ! mount "$device" "$mountpoint"; then
    cp "$fstab_backup" /etc/fstab
    rmdir "$mountpoint" 2>/dev/null || true
    die "挂载失败，/etc/fstab 已恢复"
  fi
  if ! findmnt -n "$mountpoint" >/dev/null 2>&1; then
    umount "$mountpoint" 2>/dev/null || true
    cp "$fstab_backup" /etc/fstab
    rmdir "$mountpoint" 2>/dev/null || true
    die "挂载校验失败，/etc/fstab 已恢复"
  fi

  old=$(wizard_get DATA_DISKS)
  [[ -n $old ]] && old="${old},"
  wizard_set DATA_DISKS "${old}${device}:${mountpoint}"
  df -hT "$mountpoint" 2>/dev/null || true
  ok "已挂载 $device → $mountpoint，并写入 fstab（nofail）"
  info "如需卸载：umount $mountpoint，并从 /etc/fstab 删除对应行"
}

init_disk() {
  wizard_init
  if [[ ${1:-} == scan ]]; then
    init_disk_scan
    return 0
  fi
  require_root
  [[ -t 0 ]] || die "非交互环境请使用：st init disk scan"
  init_disk_scan
  local choice
  while true; do
    printf '\n'
    ui_menu_list $'挂载已有文件系统（不格式化，推荐）\n查看设备详情 / SMART\n扫描完成，跳过挂载' "保存并退出"
    ui_read_choice || return 0
    choice=$UI_CHOICE
    case $choice in
      1) init_disk_mount_existing ;;
      2) init_disk_details; pause ;;
      3) wizard_mark disk done; break ;;
      0|q|back) return 0 ;;
      *) warn "无效选项：$choice" ;;
    esac
  done
  ok "磁盘步骤完成"
}

init_apply_timezone() {
  local tz=$1
  [[ -f /usr/share/zoneinfo/$tz ]] || die "无效时区：$tz"
  if have timedatectl; then
    timedatectl set-timezone "$tz" || die "时区设置失败"
  else
    ln -sf "/usr/share/zoneinfo/$tz" /etc/localtime || die "时区设置失败"
    printf '%s\n' "$tz" >/etc/timezone
  fi
  wizard_set TIMEZONE "$tz"
  ok "时区已设置为 $tz"
}

init_apply_hostname() {
  local name=$1
  [[ $name =~ ^[A-Za-z0-9][A-Za-z0-9.-]*$ ]] || die "主机名只能包含字母、数字、点和短横线"
  if have hostnamectl; then
    hostnamectl set-hostname "$name" || die "主机名修改失败"
  else
    hostname "$name" || die "主机名修改失败"
    printf '%s\n' "$name" >/etc/hostname
  fi
  if grep -q '^127\.0\.1\.1' /etc/hosts 2>/dev/null; then
    backup_config_file /etc/hosts hosts >/dev/null 2>&1 || true
    local tmp
    tmp=$(mktemp)
    awk -v h="$name" '/^127\.0\.1\.1/ {print "127.0.1.1 " h; next} {print}' /etc/hosts >"$tmp"
    cat "$tmp" >/etc/hosts
    rm -f "$tmp"
  fi
  wizard_set HOSTNAME "$name"
  ok "主机名已设置为 $name"
}

init_enable_timesyncd() {
  if [[ ${INIT:-sysv} == systemd ]] && have systemctl; then
    case ${PKG:-unknown} in
      apt) pkg_install systemd-timesyncd || true ;;
    esac
    timedatectl set-ntp true 2>/dev/null || true
    svc_enable systemd-timesyncd || warn "systemd-timesyncd 启动失败"
    wizard_set TIMESYNC timesyncd
  else
    init_enable_chrony
  fi
}

init_enable_chrony() {
  pkg_update || die "软件源更新失败"
  pkg_install chrony || die "chrony 安装失败"
  if [[ ${INIT:-sysv} == systemd ]] && have systemctl; then
    systemctl disable --now systemd-timesyncd >/dev/null 2>&1 || true
  fi
  svc_enable chrony || svc_enable chronyd || warn "chrony 服务启动失败"
  wizard_set TIMESYNC chrony
  ok "chrony 已启用"
}

init_apply_dns() {
  local -a servers=("$@")
  [[ ${#servers[@]} -gt 0 ]] || die "未提供 DNS 服务器"
  local ip
  for ip in "${servers[@]}"; do
    [[ $ip =~ ^[0-9A-Fa-f:.]+$ ]] || die "DNS 地址格式无效：$ip"
  done
  if have systemctl && systemctl is-active --quiet systemd-resolved 2>/dev/null; then
    local dir=/etc/systemd/resolved.conf.d
    mkdir -p "$dir"
    [[ -f $dir/99-sst-dns.conf ]] && backup_config_file "$dir/99-sst-dns.conf" resolved-dns >/dev/null 2>&1 || true
    {
      printf '[Resolve]\n'
      printf 'DNS=%s\n' "${servers[*]}"
      printf 'FallbackDNS=8.8.8.8 1.0.0.1\n'
    } >"$dir/99-sst-dns.conf"
    systemctl restart systemd-resolved || die "systemd-resolved 重启失败"
    have resolvectl && resolvectl flush-caches >/dev/null 2>&1 || true
  else
    backup_config_file /etc/resolv.conf resolv.conf >/dev/null 2>&1 || true
    {
      printf '# managed by stbox\n'
      for ip in "${servers[@]}"; do printf 'nameserver %s\n' "$ip"; done
    } >/etc/resolv.conf
  fi
  wizard_set DNS "${servers[*]}"
  if getent hosts github.com >/dev/null 2>&1; then
    ok "DNS 已设置并解析正常：${servers[*]}"
  else
    warn "DNS 已写入，但解析测试失败，请检查网络或稍后重试"
  fi
}

init_update_check() {
  pkg_update || die "软件源更新失败"
  case ${PKG:-unknown} in
    apt)
      local n
      n=$(apt list --upgradable 2>/dev/null | grep -c upgradable || true)
      if (( n > 0 )); then
        info "可用更新：$n 个"
        apt list --upgradable 2>/dev/null | head -n 15
      else
        ok "当前没有可用更新"
      fi
      ;;
    dnf|yum)
      "$PKG" check-update -q 2>&1 | head -n 20 || true
      info "dnf/yum check-update 退出码 100 表示有可用更新，0 表示无更新"
      ;;
    apk)
      apk version -l '<' 2>/dev/null | head -n 20 || true
      ;;
    pacman)
      pacman -Qu 2>/dev/null | head -n 20 || info "当前没有可用更新"
      ;;
    zypper)
      zypper -q list-updates 2>/dev/null | head -n 20 || true
      ;;
    *) warn "当前包管理器不支持检查更新" ;;
  esac
}

init_update_install() {
  confirm "安装全部可用更新？可能升级内核或服务，完成后建议重启" || return 0
  pkg_update || die "软件源更新失败"
  pkg_upgrade || die "系统更新失败"
  wizard_set UPDATES installed
  ok "系统更新完成"
  [[ -f /var/run/reboot-required ]] && warn "系统提示需要重启"
}

init_auto_updates() {
  case ${PKG:-unknown} in
    apt)
      pkg_install unattended-upgrades || die "unattended-upgrades 安装失败"
      backup_config_file /etc/apt/apt.conf.d/20auto-upgrades auto-upgrades >/dev/null 2>&1 || true
      cat >/etc/apt/apt.conf.d/20auto-upgrades <<'EOF'
APT::Periodic::Update-Package-Lists "1";
APT::Periodic::Unattended-Upgrade "1";
APT::Periodic::AutocleanInterval "7";
EOF
      if [[ ${INIT:-sysv} == systemd ]]; then
        systemctl enable --now unattended-upgrades >/dev/null 2>&1 || true
      fi
      wizard_set AUTO_UPDATES apt
      ok "已启用 unattended-upgrades（不自动重启）"
      ;;
    dnf|yum)
      pkg_install dnf-automatic || die "dnf-automatic 安装失败"
      local conf=/etc/dnf/automatic.conf
      [[ -f $conf ]] && backup_config_file "$conf" automatic.conf >/dev/null 2>&1 || true
      [[ -f $conf ]] && sed -i 's/^apply_updates.*/apply_updates = yes/' "$conf"
      svc_enable dnf-automatic.timer || warn "dnf-automatic.timer 启动失败"
      wizard_set AUTO_UPDATES dnf
      ok "已启用 dnf-automatic（不自动重启）"
      ;;
    *) die "当前发行版暂不支持一键启用自动安全更新" ;;
  esac
}

init_basics() {
  wizard_init
  require_root
  [[ -t 0 ]] || die "基础信息设置需要在交互终端运行"
  local choice tz name
  section "基础信息设置"

  section "[1/5] 时区"
  kv "当前时区" "$(timedatectl show -p Timezone --value 2>/dev/null || date +%Z)"
  ui_menu_list $'保持当前时区（推荐）\nAsia/Shanghai\nUTC\n自定义\n跳过' "保存退出"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) wizard_set TIMEZONE "$(timedatectl show -p Timezone --value 2>/dev/null || date +%Z)" ;;
    2) init_apply_timezone Asia/Shanghai ;;
    3) init_apply_timezone UTC ;;
    4) tz=$(ask "时区" "Asia/Shanghai"); init_apply_timezone "$tz" ;;
    5) ;;
    0|q|back) return 0 ;;
    *) warn "无效选项" ;;
  esac

  section "[2/5] 主机名"
  kv "当前主机名" "$(hostname)"
  ui_menu_list $'保持当前主机名（推荐）\nweb-01\ndb-01\nproxy-01\n自定义\n随机 srv-xxxxxx\n跳过' "保存退出"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) wizard_set HOSTNAME "$(hostname)" ;;
    2) init_apply_hostname web-01 ;;
    3) init_apply_hostname db-01 ;;
    4) init_apply_hostname proxy-01 ;;
    5) name=$(ask "主机名" "$(hostname)"); init_apply_hostname "$name" ;;
    6) name="srv-$(tr -dc 'a-z0-9' </dev/urandom | head -c 6)"; init_apply_hostname "$name" ;;
    7) ;;
    0|q|back) return 0 ;;
    *) warn "无效选项" ;;
  esac

  section "[3/5] 时间同步"
  kv "当前状态" "$(timedatectl show -p NTPSynchronized --value 2>/dev/null || echo 未知)"
  ui_menu_list $'保持当前配置（推荐）\n启用 systemd-timesyncd\n安装并启用 chrony\n跳过' "保存退出"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) ;;
    2) init_enable_timesyncd ;;
    3) init_enable_chrony ;;
    4) ;;
    0|q|back) return 0 ;;
    *) warn "无效选项" ;;
  esac

  section "[4/5] DNS"
  kv "当前 DNS" "$(awk '/^nameserver/ {printf "%s ", $2}' /etc/resolv.conf 2>/dev/null)"
  ui_menu_list $'保持当前 DNS（推荐）\n223.5.5.5 + 1.1.1.1\n1.1.1.1 + 8.8.8.8\n自定义\n跳过' "保存退出"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) wizard_set DNS "$(awk '/^nameserver/ {printf "%s ", $2}' /etc/resolv.conf 2>/dev/null)" ;;
    2) init_apply_dns 223.5.5.5 1.1.1.1 ;;
    3) init_apply_dns 1.1.1.1 8.8.8.8 ;;
    4) local dns_input; local -a dns_arr=(); dns_input=$(ask "DNS（空格分隔）" "223.5.5.5 1.1.1.1"); read -r -a dns_arr <<<"$dns_input"; init_apply_dns "${dns_arr[@]}" ;;
    5) ;;
    0|q|back) return 0 ;;
    *) warn "无效选项" ;;
  esac

  section "[5/5] 更新策略"
  ui_menu_list $'跳过（推荐，稍后单独更新）\n只检查可用更新\n安装全部更新（可能较慢）\n启用自动安全更新（Debian/Ubuntu、RHEL 系）' "保存退出"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) ;;
    2) init_update_check ;;
    3) init_update_install ;;
    4) init_auto_updates ;;
    0|q|back) return 0 ;;
    *) warn "无效选项" ;;
  esac

  wizard_mark basics done
  ok "基础信息步骤完成"
}

# ---------- P2：账户 ----------

init_admin_ready() {
  local user home
  user=$(wizard_get ADMIN_USER)
  [[ -n $user ]] || return 1
  getent passwd "$user" >/dev/null 2>&1 || return 1
  home=$(getent passwd "$user" | cut -d: -f6)
  [[ -n $home && -s "$home/.ssh/authorized_keys" ]] || return 1
  sudo -l -U "$user" >/dev/null 2>&1 || return 1
  return 0
}

init_key_ready() {
  local user home
  user=$(wizard_get ADMIN_USER)
  if [[ -n $user ]]; then
    home=$(getent passwd "$user" | cut -d: -f6)
    [[ -n $home && -s "$home/.ssh/authorized_keys" ]] && return 0
  fi
  [[ -s /root/.ssh/authorized_keys ]]
}

init_set_user_password() {
  local user=$1 pass=$2
  if have chpasswd; then
    printf '%s:%s\n' "$user" "$pass" | chpasswd
  elif have passwd; then
    printf '%s\n' "$pass" | passwd --stdin "$user"
  else
    return 1
  fi
}

init_set_root_password() {
  local p1 p2
  read -r -s -p "新的 root 密码: " p1 || return 1
  printf '\n'
  read -r -s -p "再次输入: " p2 || return 1
  printf '\n'
  [[ -n $p1 && $p1 == "$p2" ]] || die "两次密码不一致或为空"
  (( ${#p1} >= 8 )) || die "密码至少需要 8 位"
  [[ $p1 != *:* ]] || die "密码不能包含冒号"
  init_set_user_password root "$p1" || die "root 密码修改失败"
  wizard_set ROOT_PASSWORD changed
  ok "root 密码已修改"
}

init_generate_root_password() {
  local p
  p=$(tr -dc 'A-Za-z0-9' </dev/urandom | head -c 20)
  [[ -n $p ]] || die "密码生成失败"
  init_set_user_password root "$p" || die "root 密码修改失败"
  wizard_set ROOT_PASSWORD changed
  secret_ok "root 密码已更新：$p"
  warn "请立即保存该密码，之后不再显示；注意终端回滚缓冲、录屏或会话日志可能留存"
}

init_create_admin_user() {
  local username=$1 mode=$2 shell home group=''
  [[ $username =~ ^[A-Za-z][A-Za-z0-9_-]*$ ]] || die "用户名格式无效"
  [[ $username != root ]] || die "不能使用 root 作为管理用户名"

  if ! getent passwd "$username" >/dev/null 2>&1; then
    shell=/bin/sh
    have bash && shell=/bin/bash
    if have useradd; then
      useradd -m -s "$shell" "$username" || die "创建用户失败"
    else
      adduser -D -s "$shell" "$username" || die "创建用户失败"
    fi
  else
    info "用户 $username 已存在，继续配置"
  fi

  if getent group sudo >/dev/null 2>&1; then
    group=sudo
  elif getent group wheel >/dev/null 2>&1; then
    group=wheel
  fi
  if [[ -n $group ]]; then
    if have usermod; then
      usermod -aG "$group" "$username" 2>/dev/null || warn "加入 $group 组失败"
    else
      adduser "$username" "$group" 2>/dev/null || warn "加入 $group 组失败"
    fi
  else
    warn "未找到 sudo/wheel 组，请手动配置 sudo 权限"
  fi

  home=$(getent passwd "$username" | cut -d: -f6)
  [[ -n $home ]] || die "无法读取用户 home 目录"

  case $mode in
    key)
      [[ -s /root/.ssh/authorized_keys ]] || die "root 没有可用密钥，无法复制到管理用户"
      mkdir -p "$home/.ssh"
      cp /root/.ssh/authorized_keys "$home/.ssh/authorized_keys"
      chown -R "$username":"$(id -gn "$username")" "$home/.ssh"
      chmod 700 "$home/.ssh"
      chmod 600 "$home/.ssh/authorized_keys"
      ;;
    password)
      local p1 p2
      read -r -s -p "管理用户密码: " p1 || return 1
      printf '\n'
      read -r -s -p "再次输入: " p2 || return 1
      printf '\n'
      [[ -n $p1 && $p1 == "$p2" ]] || die "两次密码不一致或为空"
      (( ${#p1} >= 8 )) || die "密码至少需要 8 位"
      [[ $p1 != *:* ]] || die "密码不能包含冒号"
      init_set_user_password "$username" "$p1" || die "设置用户密码失败"
      ;;
    *) die "未知认证方式：$mode" ;;
  esac

  getent passwd "$username" >/dev/null 2>&1 || die "用户创建校验失败"
  if [[ $mode == key ]] && [[ ! -s "$home/.ssh/authorized_keys" ]]; then
    die "管理用户密钥写入失败"
  fi
  if have sudo; then
    sudo -l -U "$username" >/dev/null 2>&1 || warn "sudo 权限验证失败，请手动检查"
  fi
  wizard_set ADMIN_USER "$username"
  wizard_set ADMIN_AUTH "$mode"
  ok "管理用户已配置：$username（$mode）"
}

init_accounts() {
  wizard_init
  require_root
  [[ -t 0 ]] || die "账户设置需要在交互终端运行"
  local choice user
  section "账户设置"

  section "[1/2] root 密码"
  ui_menu_list $'保持当前密码（确认已足够强）\n自定义新密码\n生成随机强密码（推荐）\n跳过' "保存退出"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) wizard_set ROOT_PASSWORD kept ;;
    2) init_set_root_password ;;
    3) init_generate_root_password ;;
    4) ;;
    0|q|back) return 0 ;;
    *) warn "无效选项" ;;
  esac

  section "[2/2] 管理用户"
  ui_menu_list $'不创建，仅使用 root（简单场景）\n创建管理用户并复制 root 密钥（推荐）\n创建管理用户并设置密码\n使用已有用户\n跳过' "保存退出"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1|5) ;;
    2)
      user=$(ask "管理用户名" "admin")
      init_create_admin_user "$user" key
      ;;
    3)
      user=$(ask "管理用户名" "admin")
      init_create_admin_user "$user" password
      ;;
    4)
      user=$(ask "已有用户名" "feng")
      getent passwd "$user" >/dev/null 2>&1 || die "用户不存在：$user"
      wizard_set ADMIN_USER "$user"
      wizard_set ADMIN_AUTH existing
      if have sudo; then
        sudo -l -U "$user" >/dev/null 2>&1 || warn "该用户 sudo 验证失败"
      fi
      ok "已记录管理用户：$user"
      ;;
    0|q|back) return 0 ;;
    *) warn "无效选项" ;;
  esac

  wizard_mark accounts done
  ok "账户设置步骤完成"
}

# ---------- P2：SSH ----------

init_ssh_snapshot() {
  local ts file
  local -a paths=(etc/ssh/sshd_config)
  [[ -d /etc/ssh/sshd_config.d ]] && paths+=(etc/ssh/sshd_config.d)
  ts=$(date +%Y%m%d-%H%M%S)
  file="$SST_WIZARD_DIR/ssh-backup-$ts.tar.gz"
  tar -czf "$file" -C / "${paths[@]}" || return 1
  chmod 600 "$file"
  wizard_set SSH_BACKUP "$file"
  printf '%s\n' "$file"
}

init_ssh_restore_config() {
  local backup service
  backup=$(wizard_get SSH_BACKUP)
  [[ -f $backup ]] || { err "SSH 备份不存在，无法回滚"; return 1; }
  rm -f /etc/ssh/sshd_config.d/00-stbox-port.conf /etc/ssh/sshd_config.d/00-stbox-auth.conf 2>/dev/null || true
  tar -xzf "$backup" -C / || { err "SSH 配置恢复失败"; return 1; }
  service=$(ssh_service_name)
  svc_restart "$service" || { err "SSH 服务重启失败"; return 1; }
  ok "SSH 配置已恢复"
}

init_ssh_dropin_set() {
  local file=$1 key=$2 value=$3 tmp
  mkdir -p /etc/ssh/sshd_config.d
  touch "$file"
  tmp=$(mktemp)
  awk -v k="$key" -v v="$value" '
    BEGIN { IGNORECASE = 1; done = 0 }
    {
      if (tolower($1) == tolower(k)) {
        if (!done) { print k " " v; done = 1 } else { print "#" $0 }
      } else {
        print $0
      }
    }
    END { if (!done) print k " " v }
  ' "$file" >"$tmp"
  cat "$tmp" >"$file"
  rm -f "$tmp"
  chmod 644 "$file"
}

init_ssh_apply_port() {
  local new=$1 old_ports p f
  old_ports=$(ssh_all_ports | tr ',' ' ')
  if grep -qE '^[[:space:]]*Include[[:space:]]+.*sshd_config\.d' /etc/ssh/sshd_config 2>/dev/null; then
    f=/etc/ssh/sshd_config.d/00-stbox-port.conf
    {
      printf '# managed by stbox\n'
      for p in $old_ports $new; do printf 'Port %s\n' "$p"; done
    } >"$f"
    chmod 644 "$f"
  else
    for p in $old_ports $new; do
      ssh_add_port "$p" >/dev/null || return 1
    done
  fi
}

init_ssh_apply_auth() {
  local pass=$1 root=$2
  [[ -n $pass || -n $root ]] || return 0
  if grep -qE '^[[:space:]]*Include[[:space:]]+.*sshd_config\.d' /etc/ssh/sshd_config 2>/dev/null; then
    local f=/etc/ssh/sshd_config.d/00-stbox-auth.conf
    [[ -n $pass ]] && init_ssh_dropin_set "$f" PasswordAuthentication "$pass"
    [[ -n $root ]] && init_ssh_dropin_set "$f" PermitRootLogin "$root"
  else
    [[ -n $pass ]] && ssh_set_option PasswordAuthentication "$pass"
    [[ -n $root ]] && ssh_set_option PermitRootLogin "$root"
  fi
}

init_ssh_verify() {
  local new=$1 pass=$2 root=$3 ports p actual
  sshd -t || return 1
  if [[ -n $new ]]; then
    ports=$(ssh_all_ports | tr ',' ' ')
    for p in $ports; do [[ $p == "$new" ]] && break; done
    [[ $p == "$new" ]] || return 1
  fi
  if [[ -n $pass ]]; then
    actual=$(ssh_cfg_get PasswordAuthentication)
    [[ $actual == "$pass" ]] || return 1
  fi
  if [[ -n $root ]]; then
    actual=$(ssh_cfg_get PermitRootLogin)
    [[ $actual == "$root" || ($root == prohibit-password && $actual == without-password) ]] || return 1
  fi
  return 0
}

init_allow_ssh_port_now() {
  local port=$1 fw
  fw=$(_fw_installed)
  case $fw in
    ufw)
      if ufw status 2>/dev/null | grep -qi active; then
        ufw allow "$port/tcp" >/dev/null 2>&1 || warn "UFW 放行新 SSH 端口失败"
      fi
      ;;
    firewalld)
      if svc_active firewalld; then
        firewall-cmd --permanent --add-port="$port/tcp" >/dev/null 2>&1 || true
        firewall-cmd --reload >/dev/null 2>&1 || true
      fi
      ;;
  esac
}

init_ssh_cancel_timer() {
  local unit
  unit=$(wizard_get SSH_TIMER_UNIT)
  [[ -n $unit ]] || unit=stbox-ssh-rollback
  if have systemctl; then
    systemctl stop "$unit.timer" "$unit.service" >/dev/null 2>&1 || true
    systemctl reset-failed "$unit.timer" "$unit.service" >/dev/null 2>&1 || true
  fi
  wizard_set SSH_TIMER_UNIT ''
}

init_ssh_rollback_script() {
  if [[ ${SST_BUNDLED:-0} -eq 1 ]]; then
    declare -F stbox_write_ssh_rollback >/dev/null 2>&1 || return 1
    stbox_write_ssh_rollback || return 1
    printf '%s\n' "$SST_STATE_DIR/ssh-rollback.sh"
  else
    printf '%s\n' "$SST_HOME/core/ssh-rollback.sh"
  fi
}

init_ssh_arm_timer() {
  local minutes=$1 unit=stbox-ssh-rollback
  (( minutes > 0 )) || return 0
  if [[ ${INIT:-sysv} != systemd ]] || ! have systemd-run; then
    warn "当前环境不支持 systemd 定时回滚，请手动验证并保留配置"
    return 0
  fi
  local rollback
  rollback=$(init_ssh_rollback_script) || { warn "准备 SSH 回滚脚本失败"; return 1; }
  init_ssh_cancel_timer
  wizard_set SSH_KEEP 0
  wizard_set SSH_SERVICE "$(ssh_service_name)"
  wizard_set ROLLBACK_LOG "$SST_WIZARD_DIR/ssh-rollback.log"
  if systemd-run --collect --unit="$unit" --on-active="${minutes}m" \
    --timer-property=AccuracySec=1s /bin/bash "$rollback" "$SST_WIZARD_STATE"; then
    wizard_set SSH_TIMER_UNIT "$unit"
    wizard_set SSH_TIMER_MIN "$minutes"
    ok "已启用 ${minutes} 分钟自动回滚；确认可登录后执行 st init ssh keep"
  else
    warn "自动回滚定时器创建失败，请手动验证 SSH"
  fi
}

init_ssh_apply_changes() {
  require_root
  local new=$1 pass=$2 root=$3 minutes=$4 service
  [[ -n $new || -n $pass || -n $root ]] || return 0
  init_ssh_snapshot >/dev/null || die "备份 SSH 配置失败"
  wizard_set SSH_NEW_PORT "$new"
  wizard_set SSH_PASS_AUTH "$pass"
  wizard_set SSH_ROOT_LOGIN "$root"
  wizard_set SSH_STATUS applying
  service=$(ssh_service_name)
  wizard_set SSH_SERVICE "$service"

  if ! (
    [[ -n $new ]] && init_ssh_apply_port "$new"
    init_ssh_apply_auth "$pass" "$root"
    init_ssh_verify "$new" "$pass" "$root"
  ); then
    init_ssh_restore_config || true
    die "SSH 配置校验失败，已回滚"
  fi

  [[ -n $new ]] && init_allow_ssh_port_now "$new"
  init_ssh_arm_timer "$minutes"

  if ! svc_restart "$service"; then
    init_ssh_cancel_timer
    init_ssh_restore_config || true
    die "SSH 服务重启失败，已回滚"
  fi
  sleep 1
  if [[ -n $new ]] && ! ss -tln 2>/dev/null | awk '{print $4}' | grep -q ":$new$"; then
    init_ssh_cancel_timer
    init_ssh_restore_config || true
    die "新端口 $new 未监听，已回滚"
  fi
  wizard_set SSH_STATUS applied
  ok "SSH 配置已应用"
}

init_ssh_keep() {
  require_root
  wizard_init
  if [[ $(wizard_get SSH_ROLLBACK) == done ]]; then
    die "SSH 配置已自动回滚，不能确认保留；请重新执行 st init ssh"
  fi
  init_ssh_cancel_timer
  wizard_set SSH_KEEP 1
  wizard_set SSH_STATUS kept
  wizard_mark ssh done
  ok "已确认保留 SSH 配置，自动回滚已取消"
  if [[ -f $SST_WIZARD_DIR/ssh-rollback.log ]]; then
    info "回滚日志：$SST_WIZARD_DIR/ssh-rollback.log"
  fi
}

init_ssh_rollback() {
  require_root
  wizard_init
  init_ssh_cancel_timer
  wizard_set SSH_KEEP 0
  local rollback
  rollback=$(init_ssh_rollback_script) || die "准备 SSH 回滚脚本失败"
  bash "$rollback" "$SST_WIZARD_STATE" || die "SSH 回滚失败"
  wizard_set SSH_STATUS rolledback
  wizard_mark ssh skipped
  ok "SSH 配置已回滚"
}

init_ssh() {
  local action=${1:-}
  case $action in
    keep) init_ssh_keep; return 0 ;;
    rollback) init_ssh_rollback; return 0 ;;
    status)
      section "SSH 向导状态"
      kv "状态" "$(wizard_get SSH_STATUS 未执行)"
      kv "新端口" "$(wizard_get SSH_NEW_PORT 未设置)"
      kv "自动回滚" "$([[ -n $(wizard_get SSH_TIMER_MIN) ]] && echo "$(wizard_get SSH_TIMER_MIN) 分钟" || echo 未启用)"
      kv "回滚结果" "$(wizard_get SSH_ROLLBACK 未执行)"
      return 0
      ;;
  esac

  wizard_init
  require_root
  [[ -t 0 ]] || die "SSH 设置需要在交互终端运行"
  local old_ports new_port='' pass='' root='' minutes=10 choice login_user current_root rollback_hint
  old_ports=$(ssh_all_ports)
  current_root=$(ssh_cfg_get PermitRootLogin)
  section "SSH 安全设置"
  kv "当前端口" "$old_ports"
  kv "密码登录" "$(ssh_cfg_get PasswordAuthentication)"
  kv "root 登录" "$current_root"
  kv "管理用户" "$(wizard_get ADMIN_USER 未创建)"

  section "[1/4] SSH 端口"
  ui_menu_list $'新增随机高位端口，保留旧端口（推荐）\n新增 2222，保留旧端口\n自定义新端口，保留旧端口\n保持当前端口' "保存退出"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1)
      local i
      for i in 1 2 3 4 5; do
        new_port=$(shuf -i 20000-65000 -n 1 2>/dev/null || echo $((20000 + RANDOM % 45000)))
        ssh_all_ports | tr ',' '\n' | grep -qx "$new_port" && continue
        ss -tln 2>/dev/null | awk '{print $4}' | grep -q ":$new_port$" || break
      done
      ;;
    2) new_port=2222 ;;
    3) new_port=$(ask "新 SSH 端口" "2222") ;;
    4) new_port='' ;;
    0|q|back) return 0 ;;
    *) warn "无效选项"; return 0 ;;
  esac
  if [[ -n $new_port ]]; then
    valid_port "$new_port" || die "端口无效：$new_port"
    ssh_all_ports | tr ',' '\n' | grep -qx "$new_port" && die "端口 $new_port 已存在"
    if ss -tln 2>/dev/null | awk '{print $4}' | grep -q ":$new_port$"; then
      die "端口 $new_port 已被其他服务占用"
    fi
  fi

  section "[2/4] 密码登录"
  ui_menu_list $'禁用密码登录，仅允许密钥（有密钥时推荐）\n保持当前设置\n开启密码登录' "保存退出"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1)
      init_key_ready || die "未发现可用 authorized_keys，不能禁用密码登录"
      pass=no
      ;;
    2) pass='' ;;
    3) pass=yes ;;
    0|q|back) return 0 ;;
    *) warn "无效选项"; return 0 ;;
  esac

  section "[3/4] root 登录"
  if init_admin_ready; then
    info "管理用户已通过密钥/sudo 验证，推荐选择 2) 完全禁止 root SSH"
  else
    info "未验证管理用户，推荐选择 1) prohibit-password"
  fi
  ui_menu_list $'prohibit-password，root 仅允许密钥（推荐）\nno，完全禁止 root SSH（需管理用户可用）\n保持当前设置\nyes，允许 root 密码登录（高风险）' "保存退出"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) root=prohibit-password ;;
    2)
      init_admin_ready || die "管理用户未通过密钥/sudo 验证，不能禁止 root SSH"
      root=no
      ;;
    3) root='' ;;
    4) root=yes; warn "允许 root 密码登录会降低安全性" ;;
    0|q|back) return 0 ;;
    *) warn "无效选项"; return 0 ;;
  esac

  if [[ ${INIT:-sysv} == systemd ]] && have systemd-run; then
    section "[4/4] 自动回滚"
    ui_menu_list $'10 分钟（推荐）\n5 分钟\n20 分钟\n不启用自动回滚' "保存退出"
    ui_read_choice || return 0
    choice=$UI_CHOICE
    case $choice in
      1) minutes=10 ;;
      2) minutes=5 ;;
      3) minutes=20 ;;
      4) minutes=0 ;;
      0|q|back) return 0 ;;
      *) minutes=10 ;;
    esac
  else
    minutes=0
    warn "当前环境不支持自动回滚定时器，请手动验证 SSH"
  fi

  section "即将应用"
  kv "SSH 端口" "${new_port:-保持 $old_ports}"
  kv "密码登录" "${pass:-保持}"
  kv "root 登录" "${root:-保持}"
  kv "自动回滚" "$([[ $minutes -gt 0 ]] && echo "${minutes} 分钟" || echo 未启用)"
  if (( minutes > 0 )); then
    rollback_hint="st init ssh rollback（${minutes} 分钟自动回滚）"
  else
    rollback_hint="st init ssh rollback（手动回滚）"
  fi
  ui_confirm_danger "即将应用 SSH 设置，操作不当可能导致无法登录。" \
    "SSH 端口、密码登录与 root 登录策略" \
    "$rollback_hint" || return 0

  if [[ -z $new_port && -z $pass && -z $root ]]; then
    wizard_mark ssh done
    info "SSH 设置未变化"
    return 0
  fi

  init_ssh_apply_changes "$new_port" "$pass" "$root" "$minutes"

  login_user=$(wizard_get ADMIN_USER)
  [[ -n $login_user ]] || login_user=root
  local port_show=${new_port:-$old_ports}
  info "请在新终端验证：ssh -p ${port_show} ${login_user}@$(get_public_ip)"
  printf '\n'
  ui_menu_list $'已验证，保留配置（推荐）\n未验证，立即回滚\n保留定时器，稍后执行 st init ssh keep' "保持当前选择并返回"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) init_ssh_keep ;;
    2) init_ssh_rollback ;;
    3)
      wizard_set SSH_KEEP 0
      if [[ $minutes -eq 0 ]]; then
        warn "未启用自动回滚，请尽快执行 st init ssh keep 或 rollback"
      fi
      ;;
    0|q|back) ;;
    *) warn "无效选项" ;;
  esac
}

init_firewall_apply_ufw() {
  local -a extra=("$@")
  local ports p
  require_root
  if ! have ufw; then
    pkg_update || die "软件源更新失败"
    pkg_install ufw || die "ufw 安装失败"
  fi
  if [[ -f /etc/default/ufw ]]; then
    backup_config_file /etc/default/ufw ufw-defaults >/dev/null 2>&1 || true
    if grep -q '^IPV6=' /etc/default/ufw; then
      sed -i 's/^IPV6=.*/IPV6=yes/' /etc/default/ufw
    else
      printf 'IPV6=yes\n' >>/etc/default/ufw
    fi
  fi
  ports=$(ssh_all_ports | tr ',' ' ')
  for p in $ports; do
    valid_port "$p" && ufw allow "$p/tcp" >/dev/null || warn "放行 SSH 端口 $p 失败"
  done
  for p in "${extra[@]}"; do
    [[ -n $p ]] || continue
    valid_port "$p" && ufw allow "$p/tcp" >/dev/null || warn "放行端口 $p 失败"
  done
  ufw --force enable || die "UFW 启用失败"
  ufw status verbose || true
  wizard_set FIREWALL "ufw"
  wizard_set FIREWALL_PORTS "$ports ${extra[*]}"
  ok "UFW 已启用，SSH 端口：$ports"
}

init_firewall_apply_firewalld() {
  local -a extra=("$@")
  local ports p
  require_root
  if ! have firewall-cmd; then
    pkg_update || die "软件源更新失败"
    pkg_install firewalld || die "firewalld 安装失败"
  fi
  svc_enable firewalld || die "firewalld 启动失败"
  firewall-cmd --permanent --add-service=ssh >/dev/null 2>&1 || true
  ports=$(ssh_all_ports | tr ',' ' ')
  for p in $ports "${extra[@]}"; do
    [[ -n $p ]] || continue
    valid_port "$p" && firewall-cmd --permanent --add-port="$p/tcp" >/dev/null 2>&1 || true
  done
  firewall-cmd --reload >/dev/null || die "firewalld 重载失败"
  firewall-cmd --list-all 2>/dev/null || true
  wizard_set FIREWALL "firewalld"
  wizard_set FIREWALL_PORTS "$ports ${extra[*]}"
  ok "firewalld 已启用，SSH 端口：$ports"
}

init_firewall() {
  wizard_init
  require_root
  [[ -t 0 ]] || die "防火墙设置需要在交互终端运行"
  local fw state choice ports_input p
  local -a extra=()
  fw=$(_fw_installed)
  state=$(_ufw_state)
  section "防火墙与防护"
  kv "当前防火墙" "$fw / $state"
  kv "SSH 端口" "$(ssh_all_ports)"
  kv "Docker" "$(have docker && echo 已安装 || echo 未安装)"
  [[ $(have docker && echo yes) == yes ]] && warn "UFW 不能完全保护 Docker 发布的端口"

  printf '\n'
  ui_menu_list $'跳过，不修改防火墙\nUFW：默认拒绝入站，只放行 SSH（推荐）\nUFW：默认拒绝入站，放行 SSH + 80/443\nUFW：默认拒绝入站，放行 SSH + 自定义端口\nfirewalld：放行 SSH + 自定义端口\n关闭现有防火墙（不推荐）' "保存退出"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) wizard_set FIREWALL skipped ;;
    2) init_firewall_apply_ufw ;;
    3) init_firewall_apply_ufw 80 443 ;;
    4)
      ports_input=$(ask "额外放行端口（空格/逗号分隔）" "80 443")
      ports_input=${ports_input//,/ }
      for p in $ports_input; do
        valid_port "$p" || die "端口无效：$p"
        extra+=("$p")
      done
      init_firewall_apply_ufw "${extra[@]}"
      ;;
    5)
      ports_input=$(ask "额外放行端口（空格/逗号分隔）" "80 443")
      ports_input=${ports_input//,/ }
      for p in $ports_input; do
        valid_port "$p" || die "端口无效：$p"
        extra+=("$p")
      done
      init_firewall_apply_firewalld "${extra[@]}"
      ;;
    6)
      ui_confirm_danger "将关闭现有防火墙，所有端口会直接暴露。" \
        "公网服务、Docker 端口与 SSH" \
        "st init firewall" || return 0
      if [[ $fw == ufw ]]; then
        ufw --force disable || die "UFW 关闭失败"
        wizard_set FIREWALL disabled
      elif [[ $fw == firewalld ]]; then
        systemctl disable --now firewalld >/dev/null 2>&1 || true
        wizard_set FIREWALL disabled
      else
        warn "没有可关闭的 ufw/firewalld"
      fi
      ;;
    0|q|back) return 0 ;;
    *) warn "无效选项"; return 0 ;;
  esac

  section "Fail2ban"
  ui_menu_list $'安装并启用 sshd 防护（推荐）\n跳过\n查看状态' "跳过"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1)
      if security_fail2ban_install --yes; then
        wizard_set FAIL2BAN installed
      else
        warn "Fail2ban 安装未完成"
      fi
      ;;
    2|0|q|back) ;;
    3) security_fail2ban_status ;;
    *) warn "无效选项" ;;
  esac

  wizard_mark firewall done
  ok "防火墙与防护步骤完成"
}

# ---------- P3：系统加固 ----------

init_openrc_sysctl_loader() {
  [[ ${INIT:-} == systemd ]] && return 0
  mkdir -p /etc/local.d
  cat >/etc/local.d/99-stbox-sysctl.start <<'EOF'
#!/bin/sh
for f in /etc/sysctl.d/99-stbox-security.conf /etc/sysctl.d/99-stbox-swap.conf /etc/sysctl.d/99-sst-bbr.conf; do
  [ -f "$f" ] && sysctl -p "$f" >/dev/null 2>&1
done
EOF
  chmod +x /etc/local.d/99-stbox-sysctl.start
  if have rc-update; then
    rc-update add local default >/dev/null 2>&1 || true
  fi
}

init_security_sysctl_apply() {
  local strict=${1:-}
  local file=/etc/sysctl.d/99-stbox-security.conf backup=''
  local check key expected actual
  require_root
  if [[ -f $file ]]; then
    backup=$(mktemp)
    cp "$file" "$backup"
    backup_config_file "$file" stbox-security >/dev/null 2>&1 || true
  fi

  {
    printf '# managed by stbox\n'
    printf 'net.ipv4.tcp_syncookies = 1\n'
    printf 'net.ipv4.conf.all.accept_redirects = 0\n'
    printf 'net.ipv4.conf.default.accept_redirects = 0\n'
    printf 'net.ipv4.conf.all.send_redirects = 0\n'
    printf 'net.ipv4.conf.default.send_redirects = 0\n'
    printf 'net.ipv4.conf.all.accept_source_route = 0\n'
    printf 'net.ipv4.conf.default.accept_source_route = 0\n'
    printf 'net.ipv4.icmp_echo_ignore_broadcasts = 1\n'
    printf 'net.ipv4.icmp_ignore_bogus_error_responses = 1\n'
    printf 'net.ipv4.conf.all.log_martians = 1\n'
    printf 'net.ipv6.conf.all.accept_redirects = 0\n'
    printf 'net.ipv6.conf.all.accept_source_route = 0\n'
    printf 'fs.protected_hardlinks = 1\n'
    printf 'fs.protected_symlinks = 1\n'
    [[ -n $strict ]] && printf 'net.ipv4.conf.all.rp_filter = 1\nnet.ipv4.conf.default.rp_filter = 1\n'
  } >"$file"

  if ! sysctl -p "$file" >/dev/null 2>&1 && ! sysctl -e -p "$file" >/dev/null 2>&1; then
    if [[ -n $backup ]]; then cp "$backup" "$file"; else rm -f "$file"; fi
    sysctl --system >/dev/null 2>&1 || true
    rm -f "$backup"
    die "安全 sysctl 应用失败，已还原配置"
  fi

  local -a checks=(
    "net.ipv4.tcp_syncookies=1"
    "net.ipv4.conf.all.accept_redirects=0"
    "net.ipv4.conf.all.send_redirects=0"
    "net.ipv4.conf.all.accept_source_route=0"
    "net.ipv4.icmp_echo_ignore_broadcasts=1"
    "net.ipv4.icmp_ignore_bogus_error_responses=1"
    "fs.protected_hardlinks=1"
    "fs.protected_symlinks=1"
  )
  [[ -n $strict ]] && checks+=("net.ipv4.conf.all.rp_filter=1" "net.ipv4.conf.default.rp_filter=1")

  for check in "${checks[@]}"; do
    key=${check%=*}
    expected=${check#*=}
    actual=$(sysctl -n "$key" 2>/dev/null || true)
    [[ -z $actual ]] && continue
    if [[ $actual != "$expected" ]]; then
      if [[ -n $backup ]]; then cp "$backup" "$file"; else rm -f "$file"; fi
      sysctl --system >/dev/null 2>&1 || true
      rm -f "$backup"
      die "安全参数校验失败：$key=$actual，已还原"
    fi
  done
  rm -f "$backup"
  init_openrc_sysctl_loader
  wizard_set SECURITY_SYSCTL "$([[ -n $strict ]] && echo strict || echo safe)"
  ok "安全 sysctl 已应用：$file"
  [[ -n $strict ]] && warn "rp_filter 可能影响 VPN、多网卡或非对称路由，如有异常请移除"
}

init_security_sysctl_remove() {
  require_root
  rm -f /etc/sysctl.d/99-stbox-security.conf
  if [[ ! -f /etc/sysctl.d/99-stbox-swap.conf && ! -f /etc/sysctl.d/99-sst-bbr.conf ]]; then
    rm -f /etc/local.d/99-stbox-sysctl.start
  fi
  sysctl --system >/dev/null 2>&1 || true
  wizard_set SECURITY_SYSCTL removed
  warn "配置已移除；已运行的参数可能保持到重启"
  ok "安全 sysctl 配置已移除"
}

init_hardening_sysctl() {
  local choice
  section "安全 sysctl"
  kv "配置文件" "$([[ -f /etc/sysctl.d/99-stbox-security.conf ]] && echo 已应用 || echo 未应用)"
  kv "syncookies" "$(sysctl -n net.ipv4.tcp_syncookies 2>/dev/null || echo 未知)"
  kv "rp_filter" "$(sysctl -n net.ipv4.conf.all.rp_filter 2>/dev/null || echo 未知)"
  printf '\n'
  ui_menu_list $'跳过，保持当前配置（推荐）\n应用安全配置（推荐）\n安全配置 + 严格 rp_filter（可能影响 VPN/多网卡）\n移除本工具的安全配置' "返回"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) wizard_set SECURITY_SYSCTL kept ;;
    2) init_security_sysctl_apply ;;
    3) init_security_sysctl_apply strict ;;
    4) init_security_sysctl_remove ;;
    0|q|back) return 0 ;;
    *) warn "无效选项" ;;
  esac
}

init_swap_create_mb() {
  local mb=$1 swappiness=10 avail
  require_root
  swap_rootfs_guard
  [[ $mb =~ ^[0-9]+$ ]] && (( mb >= 128 && mb <= 16384 )) || die "SWAP 大小需在 128M - 16G"
  if [[ -e $TUNE_SWAP_FILE ]] || grep -q "$TUNE_SWAP_FILE" /proc/swaps 2>/dev/null; then
    die "$TUNE_SWAP_FILE 已存在或已启用"
  fi
  if swapon --show --noheadings 2>/dev/null | grep -q .; then
    warn "系统已有 SWAP，本次将新增一个 $TUNE_SWAP_FILE"
  fi
  avail=$(df -Pm / | awk 'NR==2 {print $4}')
  if [[ $avail =~ ^[0-9]+$ ]] && (( avail < mb * 2 )); then
    confirm "根分区可用 ${avail} MB，创建 ${mb} MB SWAP 后空间紧张，继续？" || return 0
  else
    confirm "创建 ${mb} MB SWAP 并写入 /etc/fstab？" || return 0
  fi

  if ! fallocate -l "${mb}M" "$TUNE_SWAP_FILE" 2>/dev/null; then
    dd if=/dev/zero of="$TUNE_SWAP_FILE" bs=1M count="$mb" status=none || die "创建 SWAP 文件失败"
  fi
  chmod 600 "$TUNE_SWAP_FILE"
  mkswap "$TUNE_SWAP_FILE" >/dev/null || { rm -f "$TUNE_SWAP_FILE"; die "mkswap 失败"; }
  if ! swapon "$TUNE_SWAP_FILE"; then
    rm -f "$TUNE_SWAP_FILE"
    die "swapon 失败"
  fi

  backup_config_file /etc/fstab fstab >/dev/null 2>&1 || true
  if ! awk -v f="$TUNE_SWAP_FILE" '$1 == f {found=1} END {exit !found}' /etc/fstab; then
    printf '%s none swap sw 0 0\n' "$TUNE_SWAP_FILE" >>/etc/fstab
  fi
  {
    printf '# managed by stbox\n'
    printf 'vm.swappiness = %s\n' "$swappiness"
  } >/etc/sysctl.d/99-stbox-swap.conf
  sysctl -p /etc/sysctl.d/99-stbox-swap.conf >/dev/null 2>&1 || warn "swappiness 应用失败"
  init_openrc_sysctl_loader
  wizard_set SWAP "file:${mb}MB"
  ok "SWAP 已创建：${mb}MB（swappiness=$swappiness）"
}

init_swap_remove_hardening() {
  require_root
  if [[ ! -e $TUNE_SWAP_FILE ]] && ! grep -q "$TUNE_SWAP_FILE" /proc/swaps 2>/dev/null; then
    info "未发现本工具创建的 $TUNE_SWAP_FILE"
    return 0
  fi
  confirm "关闭并删除 $TUNE_SWAP_FILE，同时清理 fstab 与 swappiness 配置？" || return 0
  swapoff "$TUNE_SWAP_FILE" >/dev/null 2>&1 || die "swapoff 失败"
  backup_config_file /etc/fstab fstab >/dev/null 2>&1 || true
  local tmp
  tmp=$(mktemp)
  awk -v f="$TUNE_SWAP_FILE" '$1 != f' /etc/fstab >"$tmp" && cat "$tmp" >/etc/fstab
  rm -f "$tmp"
  rm -f "$TUNE_SWAP_FILE" /etc/sysctl.d/99-stbox-swap.conf
  if [[ ! -f /etc/sysctl.d/99-stbox-security.conf && ! -f /etc/sysctl.d/99-sst-bbr.conf ]]; then
    rm -f /etc/local.d/99-stbox-sysctl.start
  fi
  sysctl --system >/dev/null 2>&1 || true
  wizard_set SWAP removed
  ok "SWAP 文件已移除"
}

init_hardening_swap() {
  local choice mem_mb mb size
  section "SWAP"
  tune_swap_status
  mem_mb=$(get_mem_info | awk '{print $1}')
  if [[ $mem_mb =~ ^[0-9]+$ ]]; then
    if (( mem_mb <= 4096 )); then
      info "内存 ${mem_mb} MB，推荐 SWAP 2G"
    else
      info "内存 ${mem_mb} MB，推荐 SWAP 4G"
    fi
  fi
  printf '\n'
  ui_menu_list $'跳过，保持当前 SWAP（推荐）\n按内存推荐创建/新增\n1G\n2G\n4G\n自定义\n移除本工具创建的 SWAP' "返回"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) wizard_set SWAP kept ;;
    2)
      if [[ $mem_mb =~ ^[0-9]+$ ]] && (( mem_mb <= 4096 )); then mb=2048; else mb=4096; fi
      init_swap_create_mb "$mb"
      ;;
    3) init_swap_create_mb 1024 ;;
    4) init_swap_create_mb 2048 ;;
    5) init_swap_create_mb 4096 ;;
    6)
      size=$(ask "SWAP 大小（如 512M、1G）" "1G")
      [[ $size =~ ^([0-9]+)([GgMm])$ ]] || die "大小格式错误"
      mb=${BASH_REMATCH[1]}
      [[ ${BASH_REMATCH[2]} == G || ${BASH_REMATCH[2]} == g ]] && mb=$((mb * 1024))
      init_swap_create_mb "$mb"
      ;;
    7) init_swap_remove_hardening ;;
    0|q|back) return 0 ;;
    *) warn "无效选项" ;;
  esac
}

init_bbr_enable() {
  local file=/etc/sysctl.d/99-sst-bbr.conf backup=''
  require_root
  if [[ $(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null) == bbr ]]; then
    wizard_set BBR bbr
    info "BBR 已启用"
    return 0
  fi
  if ! bbr_supported; then
    warn "当前内核不支持 BBR，请先升级内核"
    wizard_set BBR unsupported
    return 0
  fi
  confirm "启用 BBR（fq 队列 + bbr 拥塞控制）？" || return 0
  if ! bbr_try_load; then
    warn "tcp_bbr 模块加载失败，请检查内核模块"
    wizard_set BBR unsupported
    return 0
  fi
  if [[ -f $file ]]; then
    backup=$(mktemp)
    cp "$file" "$backup"
    backup_config_file "$file" bbr >/dev/null 2>&1 || true
  fi
  {
    printf '# managed by stbox\n'
    printf 'net.core.default_qdisc = fq\n'
    printf 'net.ipv4.tcp_congestion_control = bbr\n'
  } >"$file"
  if ! sysctl -p "$file" >/dev/null 2>&1; then
    if [[ -n $backup ]]; then cp "$backup" "$file"; else rm -f "$file"; fi
    rm -f "$backup"
    die "BBR 配置应用失败，已还原"
  fi
  rm -f "$backup"
  init_openrc_sysctl_loader
  if [[ $(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null) == bbr ]]; then
    wizard_set BBR bbr
    ok "BBR 已启用"
  else
    warn "配置已写入，当前算法未切换，重启后可能生效"
  fi
}

init_bbr_disable() {
  require_root
  confirm "关闭 BBR 并恢复 cubic/fq_codel？" || return 0
  rm -f /etc/sysctl.d/99-sst-bbr.conf
  sysctl -w net.ipv4.tcp_congestion_control=cubic >/dev/null 2>&1 || true
  sysctl -w net.core.default_qdisc=fq_codel >/dev/null 2>&1 || true
  if [[ ! -f /etc/sysctl.d/99-stbox-security.conf && ! -f /etc/sysctl.d/99-stbox-swap.conf ]]; then
    rm -f /etc/local.d/99-stbox-sysctl.start
  fi
  wizard_set BBR cubic
  ok "BBR 已关闭"
}

init_hardening_bbr() {
  local choice
  section "BBR"
  kv "当前算法" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || echo 未知)"
  kv "内核支持" "$(bbr_supported && echo 是 || echo 否)"
  printf '\n'
  ui_menu_list $'跳过，保持当前设置（推荐）\n启用 BBR\n关闭 BBR，恢复 cubic' "返回"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) wizard_set BBR kept ;;
    2) init_bbr_enable ;;
    3) init_bbr_disable ;;
    0|q|back) return 0 ;;
    *) warn "无效选项" ;;
  esac
}

init_hardening() {
  wizard_init
  require_root
  [[ -t 0 ]] || die "系统加固需要在交互终端运行"
  section "系统加固与可选优化"
  kv "根分区" "$(findmnt -n -o FSTYPE / 2>/dev/null || stat -f -c %T / 2>/dev/null || echo 未知)"
  kv "SWAP" "$(swapon --show --noheadings 2>/dev/null | awk '{printf "%s(%s) ", $1, $3}' | sed 's/^/ /' || echo 未启用)"
  kv "TCP 算法" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || echo 未知)"
  init_hardening_sysctl
  init_hardening_swap
  init_hardening_bbr
  wizard_mark hardening done
  ok "系统加固步骤完成"
}

init_report() {
  require_root
  local file
  file=$(wizard_report_write)
  wizard_mark report done
  ok "开荒报告已生成：$file"
  ui_panel "验收报告" \
    "报告：$file" \
    "权限 600，包含主机名、IP 和配置摘要，请勿公开分享" \
    "下一步：按报告建议逐项检查配置"
}
init_reset() {
  require_root
  confirm "清除向导进度？不会还原任何系统配置" || return 0
  rm -f "$SST_WIZARD_STATE"
  ok "向导进度已清除，历史报告保留在 $SST_WIZARD_DIR"
}

init_resume() { init_wizard; }

init_wizard() {
  require_root
  [[ -t 0 ]] || die "开荒向导需要在交互终端运行；预检可用 st init preflight"
  wizard_init
  sst_print_banner
  wizard_status_table
  confirm "开始/继续开荒向导？" || return 0

  if [[ $(wizard_step_status preflight) != done ]]; then
    init_preflight_show
    confirm "预检完成，继续磁盘检测？" || { warn "已保存进度，可执行 st init resume 继续"; return 0; }
    wizard_mark preflight done
  fi

  if [[ $(wizard_step_status disk) != done ]]; then
    init_disk
    if [[ $(wizard_step_status disk) != done ]]; then
      warn "磁盘步骤未完成，已保存进度"
      return 0
    fi
  fi

  if [[ $(wizard_step_status basics) != done ]]; then
    init_basics
    if [[ $(wizard_step_status basics) != done ]]; then
      warn "基础信息步骤未完成，已保存进度"
      return 0
    fi
  fi

  if [[ $(wizard_step_status accounts) != done ]]; then
    init_accounts
    if [[ $(wizard_step_status accounts) != done ]]; then
      warn "账户步骤未完成，已保存进度"
      return 0
    fi
  fi

  if [[ $(wizard_step_status ssh) != done ]]; then
    if [[ $(wizard_get SSH_STATUS) == applied ]]; then
      warn "SSH 配置正在等待验证：新开终端测试后执行 st init ssh keep 或 rollback"
      return 0
    fi
    init_ssh
    if [[ $(wizard_step_status ssh) != done ]]; then
      warn "SSH 步骤未完成，已保存进度"
      return 0
    fi
  fi

  if [[ $(wizard_step_status firewall) != done ]]; then
    init_firewall
    if [[ $(wizard_step_status firewall) != done ]]; then
      warn "防火墙步骤未完成，已保存进度"
      return 0
    fi
  fi

  if [[ $(wizard_step_status hardening) != done ]]; then
    init_hardening
    if [[ $(wizard_step_status hardening) != done ]]; then
      warn "系统加固步骤未完成，已保存进度"
      return 0
    fi
  fi

  init_report
  wizard_status_table
  ok "开荒流程完成：预检、磁盘、基础信息、账户、SSH、防火墙、系统加固、报告"
}

# --- modules/network.sh ---
# 模块：网络测试

sst_register_module network "网络测试" "测速 路由 延迟 DNS 端口"
SST_MODULE_ITEMS[network]=$'info|网络概览\nip|IP 与归属地\nspeed|下载测速\nping|延迟与丢包\nroute|路由追踪\ndns|DNS 检测\nport|远程端口检测\nlisten|本机监听端口'

network_info() {
  section "网络概览"
  if have ip; then
    ip -br address 2>/dev/null
    printf '\n'
    info "默认路由："
    ip route show default 2>/dev/null || true
  else
    ifconfig -a 2>/dev/null || warn "未找到 ip/ifconfig 命令"
  fi

  local dns
  dns=$(awk '/^nameserver/ {printf "%s ", $2}' /etc/resolv.conf 2>/dev/null)
  kv "DNS 服务器" "${dns:-未知}"
  kv "公网 IP" "$(get_public_ip)"
}

network_ip() {
  section "本机 IP 与归属地"
  local v4 v6 json field city region country org
  v4=$(ip -4 -br addr show scope global 2>/dev/null | awk '{print $3}' | paste -sd, -)
  v6=$(ip -6 -br addr show scope global 2>/dev/null | awk '{print $3}' | paste -sd, -)
  kv "本机 IPv4" "${v4:-无}"
  kv "本机 IPv6" "${v6:-无}"
  kv "公网 IPv4" "$(get_public_ip)"

  v6=$(curl -6 -fsS --max-time 4 https://api6.ipify.org 2>/dev/null || true)
  kv "公网 IPv6" "${v6:-无或不可用}"

  json=$(curl -fsS --max-time 6 https://ipinfo.io/json 2>/dev/null || true)
  if [[ -n $json ]]; then
    field() { printf '%s\n' "$2" | sed -n "s/.*\"$1\": \"\\([^\"]*\\)\".*/\\1/p" | head -n 1; }
    city=$(field city "$json")
    region=$(field region "$json")
    country=$(field country "$json")
    org=$(field org "$json")
    kv "归属地" "${country:-未知} / ${region:-未知} / ${city:-未知}"
    kv "运营商" "${org:-未知}"
  else
    warn "归属地查询失败（ipinfo.io 不可达）"
  fi
}

network_speed() {
  local size=${1:-50} out speed sampled time
  [[ $size =~ ^[0-9]+$ ]] || die "测速大小必须是数字（单位 MB）"
  (( size >= 5 && size <= 500 )) || die "测速大小需在 5-500 MB 之间"
  ensure_tool curl curl || return 1

  info "从 Cloudflare 下载 ${size} MB 测试数据…"
  if ! out=$(curl -o /dev/null -fsS --max-time 60 \
    -w '%{speed_download} %{size_download} %{time_total}' \
    "https://speed.cloudflare.com/__down?bytes=$((size * 1024 * 1024))" 2>/dev/null); then
    die "测速失败：无法访问测速节点，请检查网络或代理设置"
  fi
  read -r speed sampled time <<<"$out"
  awk -v s="$speed" -v n="$sampled" -v t="$time" 'BEGIN{
    printf "下载速度：%.2f Mbps（%.2f MB/s）\n", s * 8 / 1000000, s / 1048576;
    printf "下载大小：%.1f MB，用时 %.2f 秒\n", n / 1048576, t;
  }'
}

network_ping() {
  local host=${1:-1.1.1.1} out
  ensure_tool ping iputils-ping || return 1
  info "对 $host 进行 10 次探测…"
  out=$(ping -c 10 -W 2 "$host" 2>&1) || warn "存在丢包或目标不可达"
  printf '%s\n' "$out" | tail -n 5
}

network_route() {
  local host=${1:-1.1.1.1}
  if have mtr; then
    info "使用 mtr 追踪到 $host 的路由…"
    mtr -r -c 10 "$host"
    return 0
  fi
  if ! have traceroute; then
    confirm "安装 traceroute 用于路由追踪？" || return 0
    pkg_install traceroute || die "traceroute 安装失败"
  fi
  info "使用 traceroute 追踪到 $host 的路由…"
  traceroute -m 20 -w 1 "$host"
}

network_dns() {
  section "DNS 配置"
  grep -E '^nameserver' /etc/resolv.conf 2>/dev/null || warn "未配置 nameserver"

  section "域名解析测试"
  local d out start end ms failed=0
  printf '  %-24s %-18s %s\n' "域名" "解析结果" "耗时"
  for d in github.com www.cloudflare.com www.baidu.com; do
    start=$(date +%s%3N)
    if have dig; then
      out=$(dig +short +time=2 "$d" 2>/dev/null | head -n 1)
    else
      out=$(getent ahosts "$d" 2>/dev/null | awk 'NR==1 {print $1}')
    fi
    end=$(date +%s%3N)
    ms=$(( end - start ))
    if [[ -n $out ]]; then
      printf '  %-24s %-18s %s ms\n' "$d" "$out" "$ms"
    else
      printf '  %-24s %-18s %s\n' "$d" "解析失败" "-"
      failed=$((failed + 1))
    fi
  done
  (( failed == 0 )) || warn "存在解析失败，通常是 DNS 污染或本地解析服务异常"
}

network_port() {
  local host=${1:-} port=${2:-}
  [[ -n $host ]] || host=$(ask "目标主机" "1.1.1.1")
  [[ -n $port ]] || port=$(ask "目标端口" "443")
  valid_port "$port" || die "端口无效：$port"

  info "检测 $host:$port（最多 3 秒）…"
  if tcp_check "$host" "$port" 3; then
    ok "$host:$port 可达"
  else
    err "$host:$port 不可达（可能被防火墙拦截或服务未监听）"
    return 1
  fi
}

network_listen() {
  section "本机监听端口"
  if have ss; then
    ss -tulpn 2>/dev/null || ss -tuln 2>/dev/null
  elif have netstat; then
    netstat -tulpn 2>/dev/null
  else
    warn "未找到 ss/netstat，请安装 iproute2 或 net-tools"
    return 1
  fi
}

# --- modules/security.sh ---
# 模块：安全与优化

sst_register_module security "安全与优化" "防火墙 SSH BBR Fail2ban"
SST_MODULE_ITEMS[security]=$'status|安全状况\nfirewall_status|防火墙状态\nfirewall_allow|开放端口\nfirewall_enable|启用防火墙\nfirewall_disable|关闭防火墙\nssh_status|SSH 配置\nssh_port|修改 SSH 端口\nssh_password|禁用密码登录\nssh_password_on|开启 root 密码登录\nssh_root|限制 root 登录\nbbr_status|BBR 状态\nbbr_on|开启 BBR\nbbr_off|关闭 BBR\nfail2ban_status|Fail2ban 状态\nfail2ban_install|安装 Fail2ban'

ssh_service_name() {
  if [[ ${INIT:-sysv} == systemd ]]; then
    if systemctl list-unit-files 2>/dev/null | grep -q '^ssh\.service'; then
      printf 'ssh'
    else
      printf 'sshd'
    fi
  else
    printf 'sshd'
  fi
}

sshd_config_file() { printf '/etc/ssh/sshd_config'; }

ssh_cfg_get() {
  local key=$1 v='' cfg
  cfg=$(sshd_config_file)
  if have sshd && [[ ${EUID:-1} -eq 0 ]]; then
    v=$(sshd -T 2>/dev/null | awk -v k="${key,,}" '$1 == k {print $2; exit}')
  fi
  [[ -n $v ]] || v=$(awk -v k="$key" 'tolower($1) == tolower(k) && $1 !~ /^#/ {v = $2} END {print v}' "$cfg" 2>/dev/null)
  printf '%s' "${v:-未知}"
}

ssh_current_port() {
  local port
  port=$(ssh_cfg_get Port)
  port=$(printf '%s' "$port" | awk '{print $1}')
  [[ $port =~ ^[0-9]+$ ]] || port=22
  printf '%s' "$port"
}

ssh_all_ports() {
  local ports=''
  if have sshd && [[ ${EUID:-1} -eq 0 ]]; then
    ports=$(sshd -T 2>/dev/null | awk '$1 == "port" {print $2}' | sort -u | paste -sd, -)
  fi
  if [[ -z $ports ]]; then
    ports=$(awk 'tolower($1) == "port" && $1 !~ /^#/ {print $2}' \
      "$(sshd_config_file)" 2>/dev/null | sort -u | paste -sd, -)
  fi
  printf '%s' "${ports:-22}"
}

svc_state_text() {
  if svc_active "$1"; then printf '运行中'; else printf '未运行'; fi
}

_fw_installed() {
  if have ufw; then printf 'ufw'
  elif have firewall-cmd; then printf 'firewalld'
  elif have nft; then printf 'nftables'
  elif have iptables; then printf 'iptables'
  else printf 'none'
  fi
}

_ufw_state() {
  local state
  state=$(ufw status 2>/dev/null | head -n 1 | awk '{print $2}')
  printf '%s' "${state:-需 root 查看}"
}

backup_config_file() {
  local src=$1 tag=${2:-$(basename "$1")} dir ts dest
  dir="$SST_DATA_DIR/backups/config"
  mkdir -p "$dir" || return 1
  ts=$(date +%Y%m%d-%H%M%S)
  dest="$dir/${tag}.${ts}"
  cp -a "$src" "$dest" || return 1
  chmod 600 "$dest" 2>/dev/null || true
  printf '%s\n' "$dest"
}

# 替换或追加单个 sshd 指令，写入前做语法校验
ssh_set_option() {
  local key=$1 value=$2 cfg tmp backup
  cfg=$(sshd_config_file)
  [[ -f $cfg ]] || die "找不到 $cfg"
  backup=$(backup_config_file "$cfg" sshd_config) || die "备份 sshd_config 失败"
  tmp=$(mktemp)

  awk -v k="$key" -v v="$value" '
    BEGIN { IGNORECASE = 1; done = 0 }
    {
      if (tolower($1) == tolower(k)) {
        if (!done) { print k " " v; done = 1 } else { print "#" $0 }
      } else {
        print $0
      }
    }
    END { if (!done) print k " " v }
  ' "$cfg" >"$tmp"

  if have sshd && ! sshd -t -f "$tmp" 2>/dev/null; then
    rm -f "$tmp"
    die "新配置校验失败，原配置未改动（备份：$backup）"
  fi
  cat "$tmp" >"$cfg"
  rm -f "$tmp"
  info "已设置 $key $value（备份：$backup）"
}

# 新增端口（保留旧端口，避免改端口后无法连接）
ssh_add_port() {
  local port=$1 cfg tmp backup
  cfg=$(sshd_config_file)
  backup=$(backup_config_file "$cfg" sshd_config) || die "备份 sshd_config 失败"
  tmp=$(mktemp)
  cat "$cfg" >"$tmp"
  printf '\n# added by stbox\nPort %s\n' "$port" >>"$tmp"
  if have sshd && ! sshd -t -f "$tmp" 2>/dev/null; then
    rm -f "$tmp"
    die "新配置校验失败，原配置未改动（备份：$backup）"
  fi
  cat "$tmp" >"$cfg"
  rm -f "$tmp"
  info "已新增 SSH 端口 $port（旧端口保留，备份：$backup）"
}

security_status() {
  local fw root_login pass_auth
  root_login=$(ssh_cfg_get PermitRootLogin)
  pass_auth=$(ssh_cfg_get PasswordAuthentication)
  if [[ ${EUID:-1} -ne 0 ]]; then
    [[ $root_login == 未知 ]] && root_login="需 root 查看"
    [[ $pass_auth == 未知 ]] && pass_auth="需 root 查看"
  fi
  section "SSH"
  kv "端口" "$(ssh_current_port)"
  kv "root 登录" "$root_login"
  kv "密码登录" "$pass_auth"
  kv "服务状态" "$(svc_state_text "$(ssh_service_name)")"

  section "防火墙"
  fw=$(_fw_installed)
  kv "类型" "$fw"
  case $fw in
    ufw) kv "状态" "$(_ufw_state)" ;;
    firewalld) kv "状态" "$(svc_state_text firewalld)" ;;
    nftables) kv "状态" "$(nft list ruleset 2>/dev/null | grep -c . ) 条规则" ;;
    iptables) kv "状态" "$(iptables -S 2>/dev/null | grep -c .) 条规则" ;;
    *) kv "状态" "未安装" ;;
  esac

  section "内核与防护"
  kv "TCP 算法" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || echo 未知)"
  kv "BBR" "$(bbr_supported && echo 可用 || echo 不可用)"
  kv "Fail2ban" "$(have fail2ban-client && svc_state_text fail2ban || echo 未安装)"
}

bbr_available() {
  sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null | grep -qw bbr
}

bbr_supported() {
  bbr_available && return 0
  if have modinfo && modinfo tcp_bbr >/dev/null 2>&1; then
    return 0
  fi
  compgen -G "/lib/modules/$(uname -r)/kernel/net/ipv4/tcp_bbr.ko*" >/dev/null 2>&1
}

bbr_try_load() {
  bbr_available && return 0
  have modprobe || return 1
  modprobe tcp_bbr >/dev/null 2>&1 || return 1
  bbr_available
}

security_bbr_status() {
  section "BBR 状态"
  kv "当前算法" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || echo 未知)"
  kv "队列规则" "$(sysctl -n net.core.default_qdisc 2>/dev/null || echo 未知)"
  kv "内核支持" "$(bbr_supported && echo 是 || echo 否)"
  if [[ -f /etc/sysctl.d/99-sst-bbr.conf ]]; then
    kv "配置文件" "/etc/sysctl.d/99-sst-bbr.conf"
  fi
}

security_bbr_on() {
  require_root
  if ! bbr_supported; then
    warn "当前内核不支持 BBR（通常需要 4.9+ 内核），请先升级内核"
    return 1
  fi
  confirm "启用 BBR（fq 队列 + bbr 拥塞控制）？" || return 0
  if ! bbr_try_load; then
    warn "tcp_bbr 模块加载失败，请检查内核模块"
    return 1
  fi
  cat >/etc/sysctl.d/99-sst-bbr.conf <<'EOF'
net.core.default_qdisc=fq
net.ipv4.tcp_congestion_control=bbr
EOF
  if ! sysctl --system >/dev/null 2>&1; then
    sysctl -p /etc/sysctl.d/99-sst-bbr.conf >/dev/null 2>&1 || {
      rm -f /etc/sysctl.d/99-sst-bbr.conf
      die "BBR 配置应用失败，已回滚"
    }
  fi
  security_bbr_status
  if [[ $(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null) == bbr ]]; then
    ok "BBR 已启用"
  else
    warn "配置已写入，但当前算法未切换为 bbr，重启后可能生效"
  fi
}

security_bbr_off() {
  require_root
  confirm "关闭 BBR 并恢复 cubic 拥塞控制？" || return 0
  rm -f /etc/sysctl.d/99-sst-bbr.conf
  sysctl -w net.ipv4.tcp_congestion_control=cubic >/dev/null 2>&1 || true
  sysctl -w net.core.default_qdisc=fq_codel >/dev/null 2>&1 || true
  ok "已移除 BBR 配置"
  security_bbr_status
}

security_firewall_status() {
  local fw
  fw=$(_fw_installed)
  section "防火墙状态"
  kv "类型" "$fw"
  case $fw in
    ufw) ufw status verbose 2>/dev/null || warn "需要 root 权限查看 UFW 状态" ;;
    firewalld) firewall-cmd --list-all 2>/dev/null || warn "firewalld 未运行" ;;
    nftables) nft list ruleset 2>/dev/null | head -n 40 ;;
    iptables) iptables -S 2>/dev/null | head -n 40 ;;
    *) warn "未检测到防火墙工具，可安装 ufw 统一管理" ;;
  esac
}

security_firewall_allow() {
  local port=${1:-} proto=${2:-tcp} fw
  [[ -n $port ]] || port=$(ask "开放端口（如 8080 或 22/tcp）" "22")
  if [[ $port == */* ]]; then
    proto=${port#*/}
    port=${port%%/*}
  fi
  valid_port "$port" || die "端口无效：$port"
  [[ $proto == tcp || $proto == udp ]] || die "协议仅支持 tcp/udp"

  require_root
  fw=$(_fw_installed)
  case $fw in
    ufw)
      ufw allow "$port/$proto" || die "UFW 规则添加失败"
      ok "已放行 $port/$proto"
      ufw status 2>/dev/null | head -n 1
      ;;
    firewalld)
      firewall-cmd --permanent --add-port="$port/$proto" >/dev/null || die "firewalld 规则添加失败"
      firewall-cmd --reload >/dev/null || die "firewalld 重载失败"
      ok "已放行 $port/$proto（firewalld）"
      ;;
    *)
      warn "当前防火墙类型为 $fw，脚本未自动持久化规则"
      warn "建议安装 ufw 后由脚本统一管理：apt install ufw"
      return 1
      ;;
  esac
}

security_firewall_enable() {
  require_root
  local fw ssh_port
  fw=$(_fw_installed)
  if [[ $fw != ufw && $fw != firewalld ]]; then
    warn "当前防火墙类型为 $fw，建议使用 ufw 统一管理"
    confirm "现在安装 ufw？" || return 0
    pkg_install ufw || die "ufw 安装失败"
    fw=ufw
  fi

  ssh_port=$(ssh_current_port)
  if [[ $fw == ufw ]]; then
    confirm "启用 UFW（默认拒绝入站，将先放行 SSH $ssh_port/tcp）？" || return 0
    ufw allow "$ssh_port/tcp" >/dev/null || die "放行 SSH 端口失败"
    ufw --force enable || die "UFW 启用失败"
    ufw status verbose
  else
    confirm "启用 firewalld（默认放行 SSH 服务）？" || return 0
    svc_enable firewalld || die "firewalld 启动失败"
    firewall-cmd --permanent --add-service=ssh >/dev/null 2>&1 || true
    firewall-cmd --reload >/dev/null 2>&1 || true
    firewall-cmd --list-all
  fi
  ok "防火墙已启用，SSH 端口 $ssh_port 已放行"
}

security_firewall_disable() {
  require_root
  local fw
  fw=$(_fw_installed)
  ui_confirm_danger "将关闭防火墙，所有端口会直接暴露。" \
    "公网服务、Docker 端口与 SSH" \
    "st security firewall_enable" || return 0
  case $fw in
    ufw) ufw --force disable; ok "UFW 已关闭" ;;
    firewalld) systemctl disable --now firewalld 2>/dev/null || true; ok "firewalld 已关闭" ;;
    *) warn "当前没有可关闭的 ufw/firewalld 防火墙" ;;
  esac
}

security_ssh_status() {
  local cfg root_login pass_auth pubkey
  cfg=$(sshd_config_file)
  root_login=$(ssh_cfg_get PermitRootLogin)
  pass_auth=$(ssh_cfg_get PasswordAuthentication)
  pubkey=$(ssh_cfg_get PubkeyAuthentication)
  if [[ ${EUID:-1} -ne 0 ]]; then
    [[ $root_login == 未知 ]] && root_login="需 root 查看"
    [[ $pass_auth == 未知 ]] && pass_auth="需 root 查看"
    [[ $pubkey == 未知 ]] && pubkey="需 root 查看"
  fi
  section "SSH 配置"
  kv "配置文件" "$cfg"
  kv "服务名称" "$(ssh_service_name)"
  kv "服务状态" "$(svc_state_text "$(ssh_service_name)")"
  kv "端口" "$(ssh_current_port)"
  kv "PermitRootLogin" "$root_login"
  kv "PasswordAuthentication" "$pass_auth"
  kv "PubkeyAuthentication" "$pubkey"
  printf '\n'
  warn "修改前请保持当前 SSH 会话不要关闭，并新开终端验证"
}

security_ssh_port() {
  require_root
  local old new svc
  old=$(ssh_current_port)
  new=${1:-}
  [[ -n $new ]] || new=$(ask "新的 SSH 端口" "22")
  valid_port "$new" || die "端口无效：$new"
  if [[ $new == "$old" ]]; then
    info "端口未变化（当前 $old）"
    return 0
  fi
  if have ss && ss -tln 2>/dev/null | awk '{print $4}' | grep -q ":$new$"; then
    confirm "端口 $new 已有服务监听，仍要继续？" || return 0
  fi

  ssh_add_port "$new"
  svc=$(ssh_service_name)
  if ! svc_restart "$svc"; then
    err "SSH 服务重启失败，请检查配置备份：$SST_DATA_DIR/backups/config"
    return 1
  fi

  if [[ $(_fw_installed) == ufw ]] && ufw status 2>/dev/null | grep -q "Status: active"; then
    if confirm "在 UFW 中同时放行新端口 $new/tcp？"; then
      ufw allow "$new/tcp" >/dev/null || warn "UFW 放行失败"
    fi
  fi
  ok "SSH 已监听新端口 $new，旧端口 $old 保留（确认新端口可用后再手动清理）"
  info "测试命令：ssh -p $new root@$(get_public_ip)"
}

security_ssh_password() {
  require_root
  local keys
  if [[ $(ssh_cfg_get PasswordAuthentication) == no ]]; then
    info "密码登录已处于禁用状态"
    return 0
  fi
  keys=$(find /root /home -maxdepth 4 -name authorized_keys -type f -size +0c 2>/dev/null | wc -l)
  if (( keys == 0 )); then
    die "未发现非空的 authorized_keys，禁用密码登录会导致无法登录，已中止"
  fi
  ui_confirm_danger "将禁用 SSH 密码登录。" \
    "未配置密钥的账户将无法登录" \
    "st security ssh_password_on" || return 0
  ssh_set_option PasswordAuthentication no
  svc_restart "$(ssh_service_name)" || { err "重启 SSH 失败，请检查配置备份"; return 1; }
  ok "已禁用密码登录，请新开终端验证密钥登录后再关闭当前会话"
}

security_ssh_password_on() {
  require_root
  warn "开启 root 密码登录会降低 SSH 安全性，请确保密码强度并配合 Fail2ban/防火墙"
  ui_confirm_danger "将开启密码登录和 root 密码登录。" \
    "SSH 暴力破解与弱密码风险" \
    "st security ssh_password" || return 0
  ssh_set_option PasswordAuthentication yes
  ssh_set_option PermitRootLogin yes
  svc_restart "$(ssh_service_name)" || { err "重启 SSH 失败，请检查配置备份"; return 1; }
  ok "已开启 root 密码登录，请新开终端验证"
}

security_ssh_root() {
  require_root
  if [[ $(ssh_cfg_get PermitRootLogin) == "prohibit-password" ]]; then
    info "root 登录已限制为仅密钥模式"
    return 0
  fi
  confirm "将 PermitRootLogin 设为 prohibit-password（root 仅允许密钥登录）？" || return 0
  ssh_set_option PermitRootLogin prohibit-password
  svc_restart "$(ssh_service_name)" || { err "重启 SSH 失败，请检查配置备份"; return 1; }
  ok "已限制 root 登录方式，请新开终端验证"
}

security_fail2ban_status() {
  section "Fail2ban 状态"
  if ! have fail2ban-client; then
    warn "未安装 Fail2ban，可执行：st security fail2ban_install"
    return 1
  fi
  kv "服务状态" "$(svc_state_text fail2ban)"
  fail2ban-client status 2>/dev/null || true
  printf '\n'
  fail2ban-client status sshd 2>/dev/null || warn "sshd jail 未启用"
}

security_fail2ban_install() {
  require_root
  local no_confirm=${1:-}
  [[ $no_confirm == --yes ]] || { confirm "安装 Fail2ban 并启用 sshd 防护（5 次失败封禁 1 小时）？" || return 0; }
  pkg_update || die "软件源更新失败"
  pkg_install fail2ban || die "Fail2ban 安装失败"

  local ports backend ignore client_ip
  ports=$(ssh_all_ports | tr ',' ' ')
  [[ -n $ports ]] || ports=22
  backend="auto"
  [[ ${INIT:-sysv} == systemd ]] && backend="systemd"
  ignore="127.0.0.1/8 ::1"
  if [[ -n ${SSH_CLIENT:-} ]]; then
    client_ip=${SSH_CLIENT%% *}
    [[ -n $client_ip ]] && ignore="$ignore $client_ip"
  fi

  mkdir -p /etc/fail2ban/jail.d
  cat >/etc/fail2ban/jail.d/sst-sshd.conf <<EOF
[DEFAULT]
backend = $backend
bantime = 1h
findtime = 10m
maxretry = 5
ignoreip = $ignore

[sshd]
enabled = true
port = $ports
EOF

  svc_enable fail2ban || die "Fail2ban 服务启动失败"
  svc_restart fail2ban || true
  sleep 1
  ok "Fail2ban 已安装并启用"
  fail2ban-client status sshd 2>/dev/null || warn "jail 状态暂不可读，请稍后重试"
}

# --- modules/settings.sh ---
# 模块：脚本设置与维护

sst_register_module settings "脚本设置" "版本 更新 配置 日志"
SST_MODULE_ITEMS[settings]=$'version|版本信息\nupdate|更新脚本\nconfig|查看配置\nlog|查看日志'

settings_version() { version_info; }

settings_update() { update_self; }

settings_config() { cfg_show; }

settings_log() {
  section "运行日志（最近 60 行）"
  if [[ -r $SST_LOG ]]; then
    tail -n 60 "$SST_LOG"
  else
    info "暂无日志：$SST_LOG"
  fi
}

# --- modules/site.sh ---
# 模块：建站环境（Docker 版：Apache + PHP 8.2 + MariaDB + Redis）
# 原生实现：Apache+PHP 8.2、MariaDB、Redis 均为独立容器。

sst_register_module site "建站环境" "静态站 WordPress 反代 SSL"
SST_MODULE_ITEMS[site]=$'install|安装建站环境\nstatus|环境状态\nadd|新建静态站点\nwordpress|安装 WordPress\nproxy|新建反向代理\nssl|申请 SSL 证书\nlist|站点列表\nremove|删除站点\nbackup|备份站点数据\nupdate|更新环境镜像\nuninstall|卸载建站环境'

SITE_ROOT=/home/web
SITE_COMPOSE="$SITE_ROOT/compose.yml"
SITE_CONF_DIR="$SITE_ROOT/conf"
SITE_HTML_DIR="$SITE_ROOT/html"

site_require() {
  [[ -f $SITE_COMPOSE ]] || die "建站环境未安装，请先执行：st site install"
  docker info >/dev/null 2>&1 || die "Docker 未运行，请先启动 Docker"
}

site_web_running() {
  [[ $(docker inspect -f '{{.State.Status}}' sst-web 2>/dev/null) == "running" ]]
}

site_db_pass() {
  awk -F= '$1 == "MARIADB_ROOT_PASSWORD" {print $2}' "$SITE_ROOT/.env" 2>/dev/null
}

# 在容器内使用 MYSQL_PWD，避免密码出现在宿主机 argv
site_db_exec() {
  docker exec -i sst-db sh -c 'MYSQL_PWD="$MARIADB_ROOT_PASSWORD" exec mariadb -uroot'
}

site_valid_domain() {
  local d=$1
  [[ $d =~ ^[A-Za-z0-9][A-Za-z0-9.-]*$ ]] || die "域名格式无效：$d"
  [[ $d != *".."* ]] || die "域名格式无效：$d"
  printf '%s' "$d"
}

site_reload() {
  if site_web_running; then
    docker exec sst-web apache2ctl graceful >/dev/null 2>&1 || docker restart sst-web >/dev/null
    ok "Web 服务已重载"
  else
    warn "sst-web 容器未运行，配置已写入，启动容器后生效"
  fi
}

site_db_wait() {
  local i
  for i in $(seq 1 30); do
    if docker exec sst-db sh -c \
      'MYSQL_PWD="$MARIADB_ROOT_PASSWORD" mariadb -uroot -N -e "SELECT 1"' >/dev/null 2>&1; then
      return 0
    fi
    sleep 2
  done
  return 1
}

site_write_http_vhost() {
  local domain=$1 docroot=$2 target=${3:-}
  local conf="$SITE_CONF_DIR/$domain.conf"
  {
    printf '<VirtualHost *:80>\n'
    printf '  ServerName %s\n' "$domain"
    printf '  DocumentRoot /var/www/html/%s\n' "$docroot"
    printf '  <Directory /var/www/html/%s>\n' "$docroot"
    printf '    Options -Indexes\n'
    printf '    AllowOverride All\n'
    printf '    Require all granted\n'
    printf '  </Directory>\n'
    if [[ -n $target ]]; then
      printf '  ProxyPreserveHost On\n'
      printf '  ProxyPass / http://%s/\n' "$target"
      printf '  ProxyPassReverse / http://%s/\n' "$target"
    fi
    printf '  ErrorLog /var/log/apache2/%s-error.log\n' "$domain"
    printf '  CustomLog /var/log/apache2/%s-access.log combined\n' "$domain"
    printf '</VirtualHost>\n'
  } >"$conf"
  chmod 644 "$conf"
}

site_append_ssl_vhost() {
  local domain=$1 docroot=$2 target=${3:-}
  local conf="$SITE_CONF_DIR/$domain.conf"
  local cert="/etc/apache2/certs/${domain}_cert.pem"
  local key="/etc/apache2/certs/${domain}_key.pem"
  [[ -f "$SITE_ROOT/certs/${domain}_cert.pem" && -f "$SITE_ROOT/certs/${domain}_key.pem" ]] || return 1
  grep -Fq "ServerName $domain" "$conf" 2>/dev/null || site_write_http_vhost "$domain" "$docroot" "$target"

  if grep -q 'VirtualHost \*:443' "$conf" 2>/dev/null; then
    return 0
  fi
  {
    printf '\n<VirtualHost *:443>\n'
    printf '  ServerName %s\n' "$domain"
    printf '  DocumentRoot /var/www/html/%s\n' "$docroot"
    printf '  SSLEngine on\n'
    printf '  SSLCertificateFile %s\n' "$cert"
    printf '  SSLCertificateKeyFile %s\n' "$key"
    printf '  <Directory /var/www/html/%s>\n' "$docroot"
    printf '    Options -Indexes\n'
    printf '    AllowOverride All\n'
    printf '    Require all granted\n'
    printf '  </Directory>\n'
    if [[ -n $target ]]; then
      printf '  ProxyPreserveHost On\n'
      printf '  ProxyPass / http://%s/\n' "$target"
      printf '  ProxyPassReverse / http://%s/\n' "$target"
    fi
    printf '  ErrorLog /var/log/apache2/%s-ssl-error.log\n' "$domain"
    printf '  CustomLog /var/log/apache2/%s-ssl-access.log combined\n' "$domain"
    printf '</VirtualHost>\n'
  } >>"$conf"
}

site_add() {
  require_root
  site_require
  local domain
  domain=$(ask "站点域名（先用测试域名即可）" "")
  [[ -n $domain ]] || return 0
  site_valid_domain "$domain" >/dev/null

  local dir="$SITE_HTML_DIR/$domain"
  mkdir -p "$dir"
  if [[ ! -f $dir/index.html ]]; then
    cat >"$dir/index.html" <<EOF
<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><title>$domain</title></head>
<body style="font-family:system-ui;padding:40px"><h1>$domain</h1><p>站点已创建。</p></body></html>
EOF
  fi

  site_write_http_vhost "$domain" "$domain"
  local docroot="$domain"
  site_append_ssl_vhost "$domain" "$docroot" || true
  chown -R 33:33 "$dir" 2>/dev/null || true
  site_reload
  ok "静态站点已创建：http://$domain"
  info "站点目录：$dir"
}

site_proxy() {
  require_root
  site_require
  local domain target
  domain=$(ask "反代域名" "")
  [[ -n $domain ]] || return 0
  site_valid_domain "$domain" >/dev/null
  target=$(ask "后端地址（host:port）" "127.0.0.1:8080")
  [[ $target =~ ^[A-Za-z0-9._:-]+$ ]] || die "后端地址格式无效"

  local dir="$SITE_HTML_DIR/$domain"
  mkdir -p "$dir"
  site_write_http_vhost "$domain" "$domain" "$target"
  site_append_ssl_vhost "$domain" "$domain" "$target" || true
  site_reload
  ok "反向代理已创建：http://$domain → http://$target"
}

site_ssl() {
  require_root
  site_require
  local domain email
  domain=$(ask "需要申请证书的域名" "")
  [[ -n $domain ]] || return 0
  site_valid_domain "$domain" >/dev/null
  email=$(ask "Let's Encrypt 邮箱" "admin@$domain")
  [[ $email == *@* ]] || die "邮箱格式无效"

  confirm "申请 $domain 的 Let's Encrypt 证书？申请期间会短暂停止 Web 容器" || return 0
  ensure_tool certbot certbot || return 1
  mkdir -p "$SITE_ROOT/certs"

  info "停止 Web 容器以释放 80 端口…"
  docker stop sst-web >/dev/null 2>&1 || true
  if ! certbot certonly --standalone -d "$domain" --email "$email" --agree-tos --no-eff-email --force-renewal; then
    docker start sst-web >/dev/null 2>&1 || true
    die "证书申请失败，请确认域名解析到本机且 80 端口可用"
  fi
  docker start sst-web >/dev/null 2>&1 || true

  cp "/etc/letsencrypt/live/$domain/cert.pem" "$SITE_ROOT/certs/${domain}_cert.pem" || die "复制证书失败"
  cp "/etc/letsencrypt/live/$domain/privkey.pem" "$SITE_ROOT/certs/${domain}_key.pem" || die "复制私钥失败"
  chmod 600 "$SITE_ROOT/certs/${domain}_key.pem" 2>/dev/null || true

  local docroot=$domain
  local target=''
  if [[ -f $SITE_CONF_DIR/$domain.conf ]]; then
    target=$(awk '/^  ProxyPass \/ http:\/\// {print $3}' "$SITE_CONF_DIR/$domain.conf" | head -n 1)
    target=${target#http://}
    target=${target%/}
  fi
  site_append_ssl_vhost "$domain" "$docroot" "$target"
  site_reload
  ok "证书已部署：https://$domain"
  info "证书续期：certbot renew 后复制到 $SITE_ROOT/certs，可加入 cron"
}

site_wordpress() {
  require_root
  site_require
  local domain
  domain=$(ask "WordPress 域名" "")
  [[ -n $domain ]] || return 0
  site_valid_domain "$domain" >/dev/null

  ensure_tool unzip unzip || return 1
  ensure_tool openssl openssl || return 1

  local dir="$SITE_HTML_DIR/$domain"
  mkdir -p "$dir"
  info "下载 WordPress 中文版…"
  local tmp
  tmp=$(mktemp -d)
  if ! curl -fsSL --connect-timeout 10 --max-time 300 -o "$tmp/wp.zip" \
    https://cn.wordpress.org/latest-zh_CN.zip; then
    rm -rf "$tmp"
    die "WordPress 下载失败"
  fi
  unzip -q -o "$tmp/wp.zip" -d "$tmp" || { rm -rf "$tmp"; die "解压失败"; }
  cp -a "$tmp/wordpress/." "$dir/"
  rm -rf "$tmp"

  local rootpass dbname dbuser dbpass
  rootpass=$(site_db_pass)
  [[ -n $rootpass ]] || die "读取数据库密码失败：$SITE_ROOT/.env"
  dbname="wp_$(printf '%s' "$domain" | sed 's/[^A-Za-z0-9]/_/g')"
  dbuser="$dbname"
  dbpass=$(openssl rand -hex 12)
  site_db_wait || die "数据库未就绪，请稍后重试"

  info "创建数据库与用户：$dbname"
  site_db_exec <<SQL || die "创建数据库失败"
CREATE DATABASE IF NOT EXISTS \`$dbname\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE USER IF NOT EXISTS '$dbuser'@'%' IDENTIFIED BY '$dbpass';
GRANT ALL PRIVILEGES ON \`$dbname\`.* TO '$dbuser'@'%';
FLUSH PRIVILEGES;
SQL

  info "生成 wp-config.php…"
  local -A salts=()
  local k
  for k in AUTH_KEY SECURE_AUTH_KEY LOGGED_IN_KEY NONCE_KEY AUTH_SALT SECURE_AUTH_SALT LOGGED_IN_SALT NONCE_SALT; do
    salts[$k]=$(openssl rand -base64 48 | tr -d '\n')
  done
  cat >"$dir/wp-config.php" <<EOF
<?php
define('DB_NAME', '$dbname');
define('DB_USER', '$dbuser');
define('DB_PASSWORD', '$dbpass');
define('DB_HOST', 'db');
define('DB_CHARSET', 'utf8mb4');
define('DB_COLLATE', '');
define('AUTH_KEY', '${salts[AUTH_KEY]}');
define('SECURE_AUTH_KEY', '${salts[SECURE_AUTH_KEY]}');
define('LOGGED_IN_KEY', '${salts[LOGGED_IN_KEY]}');
define('NONCE_KEY', '${salts[NONCE_KEY]}');
define('AUTH_SALT', '${salts[AUTH_SALT]}');
define('SECURE_AUTH_SALT', '${salts[SECURE_AUTH_SALT]}');
define('LOGGED_IN_SALT', '${salts[LOGGED_IN_SALT]}');
define('NONCE_SALT', '${salts[NONCE_SALT]}');
\$table_prefix = 'wp_';
define('WP_DEBUG', false);
if ( ! defined( 'ABSPATH' ) ) { define( 'ABSPATH', __DIR__ . '/' ); }
require_once ABSPATH . 'wp-settings.php';
EOF
  chown -R 33:33 "$dir" 2>/dev/null || true

  site_write_http_vhost "$domain" "$domain"
  site_append_ssl_vhost "$domain" "$domain" || true
  site_reload
  ok "WordPress 已安装：http://$domain"
  if confirm "现在申请 HTTPS 证书？"; then
    site_ssl
  fi
}

site_list() {
  site_require
  section "站点列表"
  local conf domain
  if ! compgen -G "$SITE_CONF_DIR/*.conf" >/dev/null 2>&1; then
    info "暂无站点"
    return 0
  fi
  printf '  %-24s %-10s %s\n' "域名" "HTTPS" "配置文件"
  hr
  for conf in "$SITE_CONF_DIR"/*.conf; do
    domain=$(awk '/^  ServerName/ {print $2; exit}' "$conf")
    [[ -n $domain ]] || continue
    printf '  %-24s %-10s %s\n' \
      "$domain" \
      "$(grep -q 'VirtualHost \*:443' "$conf" && echo 已启用 || echo 未启用)" \
      "$(basename "$conf")"
  done
}

site_remove() {
  require_root
  site_require
  local domain
  domain=${1:-}
  [[ -n $domain ]] || domain=$(ask "要删除的域名" "")
  [[ -n $domain ]] || return 0
  site_valid_domain "$domain" >/dev/null
  [[ -f $SITE_CONF_DIR/$domain.conf ]] || die "站点不存在：$domain"

  confirm "删除站点 $domain 的配置与文件（数据库默认保留）？" || return 0
  rm -f "$SITE_CONF_DIR/$domain.conf"
  rm -rf "${SITE_HTML_DIR:?}/$domain"
  rm -f "$SITE_ROOT/certs/${domain}_cert.pem" "$SITE_ROOT/certs/${domain}_key.pem"
  site_reload

  if confirm "同时删除该站点的数据库 wp_$(printf '%s' "$domain" | sed 's/[^A-Za-z0-9]/_/g')？"; then
    site_db_exec <<SQL || warn "数据库删除失败"
DROP DATABASE IF EXISTS \`wp_$(printf '%s' "$domain" | sed 's/[^A-Za-z0-9]/_/g')\`;
SQL
  fi
  ok "站点已删除：$domain"
}

site_status() {
  section "建站环境状态"
  if [[ ! -f $SITE_COMPOSE ]]; then
    warn "未安装，可执行：st site install"
    return 1
  fi
  kv "目录" "$SITE_ROOT"
  kv "Web 容器" "$(docker inspect -f '{{.State.Status}}' sst-web 2>/dev/null || echo 未创建)"
  kv "数据库容器" "$(docker inspect -f '{{.State.Status}}' sst-db 2>/dev/null || echo 未创建)"
  kv "Redis 容器" "$(docker inspect -f '{{.State.Status}}' sst-redis 2>/dev/null || echo 未创建)"
  printf '\n'
  compose_run -f "$SITE_COMPOSE" ps 2>/dev/null || true
}

site_backup() {
  require_root
  site_require
  local dir ts file tmpd
  dir=$(backup_dir_get)
  mkdir -p "$dir"
  ts=$(date +%Y%m%d-%H%M%S)
  file="$dir/site-$ts.tar.gz"
  tmpd=$(mktemp -d)

  info "导出数据库…"
  if ! docker exec sst-db sh -c 'MYSQL_PWD="$MARIADB_ROOT_PASSWORD" mariadb-dump -uroot --single-transaction --all-databases' >"$tmpd/database.sql" 2>/dev/null; then
    warn "数据库导出失败，继续备份文件（备份中将不含数据库）"
    rm -f "$tmpd/database.sql"
  fi

  info "打包站点文件…"
  local -a extra=()
  [[ -f $tmpd/database.sql ]] && extra=(-C "$tmpd" database.sql)
  if ! tar --ignore-failed-read -czf "$file" \
    -C "$SITE_ROOT" html conf certs .env "${extra[@]}"; then
    rm -rf "$tmpd"
    rm -f "$file"
    die "站点备份失败"
  fi
  rm -rf "$tmpd"
  {
    printf 'host=%s\n' "$(hostname)"
    printf 'time=%s\n' "$(date '+%F %T')"
    printf 'type=lnmp-site\n'
  } >"$file.manifest"
  ok "站点备份完成：$file（$(du -h "$file" | cut -f1)）"
}

site_update() {
  require_root
  site_require
  confirm "重新构建 PHP 镜像并更新容器？" || return 0
  compose_run -f "$SITE_COMPOSE" build --pull || die "镜像构建失败"
  compose_run -f "$SITE_COMPOSE" up -d || die "容器更新失败"
  ok "建站环境已更新"
}

site_install() {
  require_root
  docker_require || die "需要先安装并启动 Docker"

  if [[ -f $SITE_COMPOSE ]]; then
    info "建站环境已存在：$SITE_ROOT"
    confirm "重新生成配置并重建容器？（站点文件与数据库保留）" || return 0
  fi
  if ! site_web_running && ss -tln 2>/dev/null | awk '{print $4}' | grep -qE '(:80|:443)$'; then
    die "80/443 端口已被占用，请先停止占用服务（如系统 Nginx/Apache）"
  fi

  confirm "安装建站环境（PHP 8.2 + MariaDB + Redis，首次构建镜像需要数分钟）？" || return 0
  ensure_tool openssl openssl || return 1

  mkdir -p "$SITE_ROOT"/{html,conf,certs,mysql,redis,logs,php}
  local dbpass
  dbpass=$(openssl rand -hex 16)
  cat >"$SITE_ROOT/.env" <<EOF
MARIADB_ROOT_PASSWORD=$dbpass
EOF
  chmod 600 "$SITE_ROOT/.env"

  cat >"$SITE_ROOT/php/Dockerfile" <<'EOF'
FROM php:8.2-apache
RUN apt-get update && apt-get install -y --no-install-recommends \
      libpng-dev libjpeg62-turbo-dev libfreetype6-dev libzip-dev libonig-dev libicu-dev unzip \
    && docker-php-ext-configure gd --with-freetype --with-jpeg \
    && docker-php-ext-install -j"$(nproc)" mysqli pdo_mysql gd zip intl bcmath exif opcache \
    && a2enmod rewrite headers expires ssl proxy proxy_http \
    && rm -rf /var/lib/apt/lists/*
EOF

  cat >"$SITE_COMPOSE" <<'EOF'
services:
  web:
    build: ./php
    container_name: sst-web
    restart: unless-stopped
    ports:
      - "80:80"
      - "443:443"
    volumes:
      - ./html:/var/www/html
      - ./conf:/etc/apache2/sites-enabled
      - ./certs:/etc/apache2/certs
      - ./logs:/var/log/apache2
    depends_on:
      - db
      - redis
  db:
    image: mariadb:11
    container_name: sst-db
    restart: unless-stopped
    environment:
      MARIADB_ROOT_PASSWORD: ${MARIADB_ROOT_PASSWORD}
    volumes:
      - ./mysql:/var/lib/mysql
  redis:
    image: redis:7-alpine
    container_name: sst-redis
    restart: unless-stopped
    command: ["redis-server", "--appendonly", "yes"]
    volumes:
      - ./redis:/data
EOF

  cat >"$SITE_CONF_DIR/000-default.conf" <<'EOF'
<VirtualHost *:80>
  ServerName default
  DocumentRoot /var/www/html
  <Directory /var/www/html>
    Options -Indexes
    AllowOverride All
    Require all granted
  </Directory>
  ErrorLog /var/log/apache2/default-error.log
  CustomLog /var/log/apache2/default-access.log combined
</VirtualHost>
EOF
  chmod 644 "$SITE_CONF_DIR/000-default.conf"

  info "构建并启动容器…"
  compose_run -f "$SITE_COMPOSE" up -d --build || die "建站环境启动失败"
  ok "建站环境安装完成"
  info "站点目录：$SITE_ROOT/html；配置目录：$SITE_CONF_DIR"
  compose_run -f "$SITE_COMPOSE" ps 2>/dev/null || true
}

site_uninstall() {
  require_root
  site_require
  warn "卸载会删除容器、数据库卷与 Redis 数据；站点文件默认保留"
  local phrase
  read -r -p "输入 REMOVE 确认卸载 建站环境: " phrase || return 1
  [[ $phrase == REMOVE ]] || { warn "已取消"; return 0; }
  compose_run -f "$SITE_COMPOSE" down -v --remove-orphans || die "卸载失败"
  if confirm "同时删除 $SITE_ROOT（站点文件、证书、数据库目录）？"; then
    rm -rf "$SITE_ROOT"
    ok "建站目录已删除"
  fi
  ok "建站环境已卸载"
}

# --- modules/system.sh ---
# 模块：系统信息与基础维护

sst_register_module system "系统维护" "信息 内存 更新 清理 DNS"
SST_MODULE_ITEMS[system]=$'info|系统概览\nenv|系统环境\nload|资源负载\nmemory|内存与缓存\ndisk|磁盘占用\nclean|清理系统垃圾\nupdate|系统更新\nclean_deep|深度清理\ndns|DNS 设置\ntimezone|时区设置\nhostname|主机名\nrootpass|修改 root 密码\nportscan|端口扫描\ncron|定时任务\nshortcut|快捷命令'

system_info() {
  local cpu cores mem_total mem_used mem_avail mem_pct load disk rx tx ip
  cpu=$(get_cpu_model)
  [[ -n $cpu ]] || cpu="未知"
  cores=$(nproc 2>/dev/null || grep -c '^processor' /proc/cpuinfo 2>/dev/null || echo 未知)
  read -r mem_total mem_used mem_avail <<<"$(get_mem_info)"
  mem_pct="未知"
  if [[ $mem_total =~ ^[0-9]+$ ]] && (( mem_total > 0 )); then
    mem_pct=$(( mem_used * 100 / mem_total ))
  fi
  load=$(get_load)
  disk=$(df -h / 2>/dev/null | awk 'NR==2 {printf "%s 已用 %s (%s)", $2, $3, $5}')
  read -r rx tx <<<"$(get_rx_tx)"
  ip=$(get_public_ip)

  section "系统概览"
  kv "主机名" "$(hostname)"
  kv "系统" "$OS_NAME"
  kv "内核" "$(uname -r)"
  kv "架构" "$ARCH"
  kv "虚拟化" "$VIRT"
  kv "运行时长" "$(get_uptime_human)"
  hr
  kv "CPU" "$cpu（${cores} 核）"
  kv "CPU 使用率" "$(top -bn1 2>/dev/null | awk '/Cpu\(s\)/ {printf "%.2f%%", $2 + $4}' || echo "未知")"
  kv "负载" "$load"
  kv "内存" "${mem_used}/${mem_total} MB（${mem_pct}%，可用 ${mem_avail} MB）"
  kv "SWAP" "$(free -m 2>/dev/null | awk 'NR==3 {if ($2 == 0) print "未启用"; else printf "%d/%d MB (%d%%)", $3, $2, $3 * 100 / $2}')"
  kv "磁盘 /" "$disk"
  kv "公网 IP" "$ip"
  kv "累计流量" "接收 $(bytes_h "${rx:-0}") / 发送 $(bytes_h "${tx:-0}")"
}

system_env() {
  local tz bbr dns shell_ver docker_ver
  if have timedatectl; then
    tz=$(timedatectl show -p Timezone --value 2>/dev/null || true)
  fi
  [[ -n ${tz:-} ]] || tz=$(readlink -f /etc/localtime 2>/dev/null | sed 's#.*/zoneinfo/##')
  [[ -n ${tz:-} ]] || tz=$(date +%Z)

  bbr=$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || echo "未知")
  dns=$(awk '/^nameserver/ {printf "%s ", $2}' /etc/resolv.conf 2>/dev/null)
  docker_ver="未安装"
  if have docker; then
    docker_ver=$(docker --version 2>/dev/null | sed 's/^Docker version //;s/,.*//')
  fi

  section "系统环境"
  kv "发行版" "$OS_NAME"
  kv "版本号" "${OS_VER:-未知}"
  kv "内核" "$(uname -r)"
  kv "架构" "$ARCH"
  kv "虚拟化" "$VIRT"
  kv "包管理器" "$PKG"
  kv "服务管理" "$INIT"
  kv "时区" "$tz"
  kv "Shell" "$(basename "${SHELL:-bash}") ${BASH_VERSION%(*}"
  kv "DNS" "${dns:-未知}"
  kv "TCP 算法" "$bbr"
  kv "Docker" "$docker_ver"
  kv "公网 IP" "$(get_public_ip)"
}

system_load() {
  section "资源负载"
  kv "负载（1/5/15 分钟）" "$(get_load)"
  kv "CPU 核心" "$(nproc 2>/dev/null || echo 未知)"
  printf '\n'
  uptime 2>/dev/null || true

  section "CPU 占用前 5"
  ps -eo pid,pcpu,pmem,comm --sort=-pcpu 2>/dev/null | head -n 6 || warn "当前系统不支持 ps 排序"

  section "内存占用前 5"
  ps -eo pid,pcpu,pmem,comm --sort=-pmem 2>/dev/null | head -n 6 || true
}

system_memory_status() {
  local mem_total mem_used mem_avail pct cached buffers swap_total swap_free swap_used
  read -r mem_total mem_used mem_avail <<<"$(get_mem_info)"
  pct=0
  if [[ $mem_total =~ ^[0-9]+$ ]] && (( mem_total > 0 )); then
    pct=$((mem_used * 100 / mem_total))
  fi
  cached=$(awk '/^Cached:/ {print $2}' /proc/meminfo 2>/dev/null)
  buffers=$(awk '/^Buffers:/ {print $2}' /proc/meminfo 2>/dev/null)
  swap_total=$(awk '/^SwapTotal:/ {print $2}' /proc/meminfo 2>/dev/null)
  swap_free=$(awk '/^SwapFree:/ {print $2}' /proc/meminfo 2>/dev/null)
  cached=$(( ${cached:-0} / 1024 ))
  buffers=$(( ${buffers:-0} / 1024 ))
  swap_total=$(( ${swap_total:-0} / 1024 ))
  swap_free=$(( ${swap_free:-0} / 1024 ))
  swap_used=$((swap_total - swap_free))

  section "内存与缓存"
  kv "内存" "${mem_used}/${mem_total} MB（${pct}%，可用 ${mem_avail} MB）"
  kv "缓存" "${cached} MB"
  kv "缓冲区" "${buffers} MB"
  if (( swap_total > 0 )); then
    kv "SWAP" "${swap_used}/${swap_total} MB"
  else
    kv "SWAP" "未启用"
  fi
  hr
  printf '  内存占用前 10\n'
  if ps -eo pid,comm,rss --sort=-rss >/dev/null 2>&1; then
    ps -eo pid,comm,rss --sort=-rss 2>/dev/null | head -n 11 \
      | awk 'NR == 1 {printf "  %8s %-24s %10s\n", "PID", "进程", "RSS(MB)"; next}
             {printf "  %8s %-24s %10.1f\n", $1, $2, $3 / 1024}'
  else
    ps aux 2>/dev/null | sort -k6 -nr | head -n 10 || true
  fi
}

system_memory_drop_caches() {
  require_root
  ui_confirm_danger "将执行 sync，并清理页缓存、目录项和 inode。" \
    "可能造成短暂 IO 抖动，不会删除磁盘数据" \
    "无需回滚，缓存会随访问自动重建" || return 0
  sync
  if printf '3' >/proc/sys/vm/drop_caches 2>/dev/null; then
    ok "缓存清理请求已执行"
  else
    warn "无法写入 /proc/sys/vm/drop_caches（容器或权限限制）"
  fi
  system_memory_status
}

system_memory() {
  system_memory_status
  [[ -t 0 ]] || return 0
  local choice
  ui_menu_list $'刷新内存信息\n清理页缓存（sync + drop_caches）' "返回"
  ui_read_choice || return 0
  choice=$UI_CHOICE
  case $choice in
    1) system_memory_status ;;
    2) system_memory_drop_caches ;;
    0|q|back) return 0 ;;
    *) warn "无效选项：$choice" ;;
  esac
}

system_disk() {
  section "文件系统占用"
  df -hT 2>/dev/null || df -h

  section "根目录一级目录占用"
  info "磁盘较大时统计可能耗时，请耐心等待…"
  if du -xhd1 / 2>/dev/null | sort -rh | head -n 12; then
    :
  else
    du -x -k / 2>/dev/null | sort -rn | head -n 12
  fi
}

system_clean() {
  require_root
  section "清理项目"
  printf '  - 系统包管理器缓存\n'
  printf '  - systemd journal 日志（保留最近 200M）\n'
  printf '  - /tmp 下 7 天未访问的文件\n'
  printf '  - /var/log 下 30 天前的 .gz 日志\n\n'
  confirm "确认执行清理？" || return 0

  local before after freed
  before=$(df -m / | awk 'NR==2 {print $4}')
  info "清理包管理器缓存…"
  pkg_clean || warn "包缓存清理未完成"

  if [[ ${INIT:-sysv} == systemd ]] && have journalctl; then
    info "清理 journal 日志…"
    journalctl --vacuum-size=200M 2>/dev/null | tail -n 1 || true
  fi

  info "清理 /tmp 过期文件…"
  find /tmp -xdev -mindepth 1 -mtime +7 -exec rm -rf -- {} + 2>/dev/null || true

  info "清理过期日志…"
  find /var/log -type f -name '*.gz' -mtime +30 -delete 2>/dev/null || true

  after=$(df -m / | awk 'NR==2 {print $4}')
  if [[ $before =~ ^[0-9]+$ && $after =~ ^[0-9]+$ ]]; then
    freed=$(( after - before ))
    ok "清理完成，根分区可用空间变化约 ${freed} MB"
  else
    ok "清理完成"
  fi
}

system_update() {
  require_root
  confirm "更新系统软件包？升级内核或服务后可能需要重启，建议先备份重要数据" || return 0
  pkg_upgrade || die "系统更新失败"
  ok "系统更新完成"
  if [[ -f /var/run/reboot-required ]]; then
    warn "系统提示需要重启：/var/run/reboot-required"
    ui_panel "更新完成" "系统软件包已更新" "检测到需要重启" "建议安排维护窗口后执行 reboot"
  else
    ui_panel "更新完成" "系统软件包已更新" "当前未检测到重启标记"
  fi
  if have needrestart; then
    needrestart -b 2>/dev/null || true
  fi
}

system_clean_deep() {
  require_root
  section "深度清理项目"
  printf '  - 自动移除不再需要的依赖与残留配置\n'
  printf '  - 清理包管理器缓存\n'
  printf '  - journal 日志压缩到 50M\n'
  printf '  - /tmp 下 7 天未访问文件\n'
  printf '  - /var/log 下 30 天前的 .gz 日志\n'
  printf '  说明：不会自动删除旧内核，避免误删当前或回退内核\n\n'
  confirm "确认执行深度清理？" || return 0

  local before after freed
  before=$(df -m / | awk 'NR==2 {print $4}')

  case ${PKG:-unknown} in
    apt)
      DEBIAN_FRONTEND=noninteractive apt-get autoremove --purge -y || warn "autoremove 未完成"
      DEBIAN_FRONTEND=noninteractive apt-get autoclean -y || true
      dpkg -l 2>/dev/null | awk '/^rc/ {print $2}' | xargs -r apt-get purge -y >/dev/null 2>&1 || true
      ;;
    dnf|yum) "$PKG" autoremove -y || true ;;
    apk) apk cache clean || true ;;
    pacman) pacman -Rns --noconfirm $(pacman -Qtdq 2>/dev/null) 2>/dev/null || true ;;
    *) warn "未知包管理器，跳过依赖清理" ;;
  esac
  pkg_clean || warn "包缓存清理未完成"

  if have journalctl; then
    journalctl --vacuum-size=50M 2>/dev/null | tail -n 1 || true
  fi
  find /tmp -xdev -mindepth 1 -mtime +7 -exec rm -rf -- {} + 2>/dev/null || true
  find /var/log -type f -name '*.gz' -mtime +30 -delete 2>/dev/null || true

  after=$(df -m / | awk 'NR==2 {print $4}')
  if [[ $before =~ ^[0-9]+$ && $after =~ ^[0-9]+$ ]]; then
    freed=$(( after - before ))
    ok "深度清理完成，根分区可用空间变化约 ${freed} MB"
  else
    ok "深度清理完成"
  fi
}

system_dns() {
  local -a servers=("$@") valid=()
  if [[ ${#servers[@]} -eq 0 ]]; then
    local input
    input=$(ask "DNS 服务器（空格分隔）" "223.5.5.5 1.1.1.1")
    read -r -a servers <<<"$input"
  fi
  [[ ${#servers[@]} -gt 0 ]] || die "未提供 DNS 服务器"
  local ip
  for ip in "${servers[@]}"; do
    [[ $ip =~ ^[0-9A-Fa-f:.]+$ ]] || die "DNS 地址格式无效：$ip"
    valid+=("$ip")
  done
  require_root
  confirm "将 DNS 设置为：${valid[*]}？" || return 0

  if systemctl is-active --quiet systemd-resolved 2>/dev/null; then
    local dir=/etc/systemd/resolved.conf.d
    mkdir -p "$dir"
    {
      printf '[Resolve]\n'
      printf 'DNS=%s\n' "${valid[*]}"
      printf 'FallbackDNS=8.8.8.8 1.0.0.1\n'
    } >"$dir/99-sst-dns.conf"
    systemctl restart systemd-resolved || die "systemd-resolved 重启失败"
    have resolvectl && resolvectl flush-caches >/dev/null 2>&1 || true
    ok "已通过 systemd-resolved 应用 DNS：${valid[*]}"
  else
    backup_config_file /etc/resolv.conf resolv.conf >/dev/null 2>&1 || true
    {
      printf '# managed by stbox\n'
      for ip in "${valid[@]}"; do printf 'nameserver %s\n' "$ip"; done
    } >/etc/resolv.conf
    ok "已写入 /etc/resolv.conf：${valid[*]}"
  fi

  if getent hosts github.com >/dev/null 2>&1; then
    ok "DNS 解析测试通过"
  else
    warn "DNS 解析测试失败，请检查网络或更换 DNS"
  fi
}

system_timezone() {
  local tz=${1:-}
  [[ -n $tz ]] || tz=$(ask "时区（如 Asia/Shanghai）" "Asia/Shanghai")
  [[ -f /usr/share/zoneinfo/$tz ]] || die "无效时区：$tz"
  require_root
  confirm "将系统时区设置为 $tz？" || return 0
  if have timedatectl; then
    timedatectl set-timezone "$tz" || die "时区设置失败"
  else
    ln -sf "/usr/share/zoneinfo/$tz" /etc/localtime || die "时区设置失败"
    printf '%s\n' "$tz" >/etc/timezone
  fi
  ok "时区已设置为 $tz（当前时间：$(date '+%F %T %Z')）"
}

system_hostname() {
  local new=${1:-}
  [[ -n $new ]] || new=$(ask "新主机名" "$(hostname)")
  [[ $new =~ ^[A-Za-z0-9][A-Za-z0-9.-]*$ ]] || die "主机名只能包含字母、数字、点和短横线"
  require_root
  confirm "将主机名从 $(hostname) 修改为 $new？" || return 0
  if have hostnamectl; then
    hostnamectl set-hostname "$new" || die "主机名修改失败"
  else
    hostname "$new" || die "主机名修改失败"
    printf '%s\n' "$new" >/etc/hostname
  fi
  ok "主机名已修改为 $new（SSH 提示符会在重新登录后更新）"
}

system_rootpass() {
  require_root
  local pass
  read -r -s -p "请输入新的 root 密码: " pass || return 1
  printf '\n'
  [[ -n $pass ]] || die "密码不能为空"
  confirm "确认修改 root 密码？" || return 0
  if printf 'root:%s\n' "$pass" | chpasswd; then
    ok "root 密码已修改"
  else
    die "root 密码修改失败"
  fi
}

system_portscan() {
  local target=${1:-} ports=${2:-200}
  [[ -n $target ]] || target=$(ask "扫描目标 IP/域名" "$(get_public_ip)")
  [[ $ports =~ ^[0-9]+$ ]] && (( ports >= 10 && ports <= 1000 )) \
    || die "扫描端口数需在 10-1000 之间"

  if ! have nmap; then
    confirm "安装 nmap 用于端口扫描？" || return 0
    pkg_update || die "软件源更新失败"
    pkg_install nmap || die "nmap 安装失败"
  fi
  warn "请仅扫描你有权限测试的服务器"
  info "使用 nmap 扫描 $target 的 TCP Top ${ports} 端口…"
  nmap -Pn --top-ports "$ports" "$target"
}

cron_field_valid() {
  local field=${1:-} part
  [[ -n $field ]] || return 1
  local -a parts=()
  IFS=',' read -r -a parts <<<"$field"
  (( ${#parts[@]} > 0 )) || return 1
  for part in "${parts[@]}"; do
    [[ $part =~ ^(\*|[0-9]+|[0-9]+-[0-9]+)(/[0-9]+)?$ ]] || return 1
  done
  return 0
}

cron_schedule_valid() {
  local schedule=${1:-} field
  local -a fields=()
  read -r -a fields <<<"$schedule"
  (( ${#fields[@]} == 5 )) || return 1
  for field in "${fields[@]}"; do
    cron_field_valid "$field" || return 1
  done
  return 0
}

# cron 会把命令中的 % 视为换行，写入前需要转义
cron_escape_percent() {
  printf '%s\n' "${1//%/\\%}"
}

system_cron() {
  local action=${1:-}
  if [[ -z $action ]]; then
    system_cron list
    [[ -t 0 ]] || return 0
    local choice
    ui_menu_list $'添加任务\n删除本工具任务'
    ui_read_choice || return 0
    choice=$UI_CHOICE
    case $choice in
      1) action=add ;;
      2) action=remove ;;
      0|q|back) return 0 ;;
      *) warn "无效选项"; return 0 ;;
    esac
  fi

  case $action in
    list)
      section "定时任务"
      info "当前用户 crontab："
      crontab -l 2>/dev/null || echo "  （空）"
      hr
      info "/etc/cron.d 下的任务文件："
      ls -1 /etc/cron.d 2>/dev/null || echo "  （无）"
      if compgen -G "/etc/cron.d/sst-*" >/dev/null 2>&1; then
        hr
        for f in /etc/cron.d/sst-*; do
          printf '%s\n' "--- $(basename "$f")"
          grep -vE '^(#|SHELL=|PATH=)' "$f" 2>/dev/null || true
        done
      fi
      ;;
    add)
      require_root
      local name schedule cmd file
      name=$(ask "任务名称（字母数字）" "mytask")
      [[ $name =~ ^[A-Za-z0-9_-]+$ ]] || die "任务名称仅支持字母、数字、下划线和短横线"
      schedule=$(ask "执行时间（分 时 日 月 周）" "0 3 * * *")
      cron_schedule_valid "$schedule" || die "cron 时间格式无效，示例：0 3 * * * 或 */5 * * * *"
      cmd=$(ask "要执行的命令" "st backup create")
      [[ -n $cmd ]] || die "命令不能为空"
      local cmd_line
      cmd_line=$(cron_escape_percent "$cmd")
      file="/etc/cron.d/sst-$name"
      confirm "写入 $file：$schedule root $cmd ？" || return 0
      cat >"$file" <<EOF
SHELL=/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
$schedule root $cmd_line
EOF
      chmod 644 "$file"
      ok "定时任务已添加：$file"
      ;;
    remove)
      require_root
      local -a files=()
      mapfile -t files < <(ls -1 /etc/cron.d/sst-* 2>/dev/null)
      [[ ${#files[@]} -gt 0 ]] || { info "没有本工具创建的定时任务"; return 0; }
      section "选择要删除的任务"
      local i choice
      for i in "${!files[@]}"; do
        ui_menu_item "$((i + 1))" "$(basename "${files[$i]}")"
      done
      ui_menu_footer "取消"
      ui_read_choice "选择编号" || return 1
      choice=$UI_CHOICE
      [[ $choice =~ ^[0-9]+$ ]] && (( choice >= 1 && choice <= ${#files[@]} )) || {
        [[ $choice == 0 || $choice == q || $choice == back ]] && return 0
        die "无效编号"
      }
      rm -f "${files[$((choice - 1))]}"
      ok "已删除 ${files[$((choice - 1))]}"
      ;;
    *) die "用法：st system cron [list|add|remove]" ;;
  esac
}

system_shortcut() {
  local alias=${1:-}
  [[ -n $alias ]] || alias=$(ask "快捷命令（单个字母）" "k")
  [[ $alias =~ ^[A-Za-z]$ ]] || die "快捷命令必须是单个字母"
  [[ $alias == "st" ]] && die "st 是默认命令，请换一个字母"
  require_root
  local target="/usr/local/bin/$alias"
  if [[ -e $target && ! -L $target ]]; then
    confirm "$target 已存在且不是软链接，覆盖它？" || return 0
  fi
  ln -sfn "$SST_ENTRY" "$target" || die "创建快捷命令失败"
  hash -r 2>/dev/null || true
  ok "已设置快捷命令：$alias → $SST_ENTRY"
}

# --- modules/tools.sh ---
# 模块：实用工具（磁盘挂载、常用软件、探针/面板/节点/代理脚本入口）

sst_register_module tools "实用工具" "磁盘 工具 探针 面板 代理"
SST_MODULE_ITEMS[tools]=$'disk_mount|磁盘挂载与 fstab\ngit|安装/升级 Git\nrclone|安装 Rclone\nfclone|Fclone 安装\nscripts|第三方工具脚本\naria2|Aria2 安装管理\nipt|IPTables 工具\nchangesource|第三方换源脚本\nprobes|监控探针（Nezha/Komari/Diting）\npanels|面板安装脚本\nnodes|节点搭建脚本合集\nproxy|代理与转发脚本\nkernel|内核与 BBR 脚本\nbbr3|BBR3/tcpx 管理\nbbrmanage|BBR 一键管理\nbbrkernel|BBR 内核（CentOS）\nwarp|WARP 管理（ChatGPT/Netflix）\nmtp|MTP&TLS 代理\nnezha|哪吒探针\nkomari|Komari 探针\nditing|Diting 探针\nbaota|宝塔面板\noracle|甲骨文云脚本\nreinstall|DD/重装脚本\nnat|NAT 小鸡管理'

tools_disk_mount() {
  require_root
  section "块设备"
  lsblk -o NAME,SIZE,TYPE,FSTYPE,MOUNTPOINT,UUID 2>/dev/null || die "lsblk 不可用，请安装 util-linux"
  hr

  local device
  device=$(ask "要挂载的设备（如 /dev/vdb1，留空取消）" "")
  [[ -n $device ]] || return 0
  [[ -b $device ]] || die "不是块设备：$device"

  local mounted
  mounted=$(lsblk -no MOUNTPOINT "$device" 2>/dev/null | head -n 1)
  [[ -z $mounted ]] || die "$device 已挂载或正在使用（$mounted）"

  local dev_type
  dev_type=$(lsblk -ndo TYPE "$device" 2>/dev/null | head -n 1)
  if [[ $dev_type == disk ]]; then
    local children
    children=$(lsblk -no NAME "$device" 2>/dev/null | wc -l)
    if (( children > 1 )); then
      die "该磁盘已有分区，请直接选择分区设备（如 ${device}1）"
    fi
  fi

  # 避免误操作系统盘
  local root_src root_parent dev_parent
  root_src=$(findmnt -n -o SOURCE / 2>/dev/null || true)
  root_parent=''
  [[ -n $root_src ]] && root_parent=$(lsblk -no PKNAME "$root_src" 2>/dev/null | head -n 1)
  dev_parent=$(lsblk -no PKNAME "$device" 2>/dev/null | head -n 1)
  if [[ -n $dev_parent && $dev_parent == "$root_parent" ]]; then
    die "$device 属于系统盘（$root_parent），已拒绝操作"
  fi

  local fstype
  fstype=$(lsblk -no FSTYPE "$device" 2>/dev/null | head -n 1)
  [[ $fstype != swap ]] || die "$device 是 SWAP 分区，已拒绝挂载"
  if [[ -z $fstype ]]; then
    warn "设备没有文件系统，继续将格式化 $device 并清空其数据"
    local phrase
    read -r -p "输入 FORMAT 确认格式化: " phrase || return 1
    [[ $phrase == FORMAT ]] || { warn "已取消"; return 0; }
    mkfs.ext4 "$device" || die "格式化失败"
    fstype=ext4
  else
    info "设备已有文件系统：$fstype，跳过格式化"
  fi

  local mountpoint
  mountpoint=$(ask "挂载点" "/mnt/data")
  [[ $mountpoint == /* ]] || die "挂载点必须是绝对路径"
  if findmnt -n "$mountpoint" >/dev/null 2>&1; then
    die "$mountpoint 已被占用"
  fi
  mkdir -p "$mountpoint" || die "无法创建挂载点"
  mount "$device" "$mountpoint" || die "挂载失败"
  ok "已挂载 $device → $mountpoint"

  local uuid entry
  uuid=$(blkid -s UUID -o value "$device" 2>/dev/null || true)
  if [[ -n $uuid ]]; then
    entry="UUID=$uuid $mountpoint $fstype defaults,nofail 0 2"
  else
    entry="$device $mountpoint $fstype defaults,nofail 0 2"
  fi

  backup_config_file /etc/fstab fstab >/dev/null 2>&1 || true
  if awk -v m="$mountpoint" '$2 == m {found=1} END {exit !found}' /etc/fstab; then
    info "/etc/fstab 已存在该挂载点，未重复写入"
  else
    printf '%s\n' "$entry" >>/etc/fstab
    ok "已写入 /etc/fstab：$entry"
  fi

  df -hT "$mountpoint" 2>/dev/null || true
  info "如需卸载：umount $mountpoint，并从 /etc/fstab 删除对应行"
}

tools_git() {
  require_root
  if have git; then
    info "当前版本：$(git --version)"
  fi
  confirm "通过系统包管理器安装/升级 Git？" || return 0
  pkg_update || die "软件源更新失败"
  pkg_install git || die "Git 安装失败"
  git --version
}

tools_rclone() {
  require_root
  if have rclone; then
    info "当前版本：$(rclone version 2>/dev/null | head -n 1)"
    confirm "重新安装/升级 Rclone？" || return 0
  else
    confirm "安装 Rclone？" || return 0
  fi

  if confirm "优先使用系统包管理器安装？"; then
    pkg_update >/dev/null 2>&1 || true
    if pkg_install rclone; then
      rclone version 2>/dev/null | head -n 1
      ok "Rclone 安装完成"
      return 0
    fi
    warn "包管理器安装失败，尝试官方脚本"
  fi

  confirm "下载并执行 Rclone 官方安装脚本（rclone.org）？" || return 0
  local tmp
  tmp=$(mktemp)
  curl -fsSL --connect-timeout 10 --max-time 120 -o "$tmp" https://rclone.org/install.sh \
    || { rm -f "$tmp"; die "下载官方安装脚本失败"; }
  bash "$tmp"
  local rc=$?
  rm -f "$tmp"
  (( rc == 0 )) || die "Rclone 官方脚本执行失败"
  have rclone && rclone version | head -n 1
  ok "Rclone 安装完成"
}

tools_fclone() {
  require_root
  [[ $ARCH == x86_64 ]] || die "Fclone 二进制仅提供 x86_64 版本，当前为 $ARCH"
  if have fclone; then
    info "已安装：$(fclone version 2>/dev/null | head -n 1)"
    confirm "重新下载/覆盖安装 Fclone？" || return 0
  else
    confirm "下载 Fclone 到 /usr/local/bin/fclone？" || return 0
  fi
  local tmp
  tmp=$(mktemp)
  if ! download_with_fallback https://raw.githubusercontent.com/BlueSkyXN/RcloneX/master/fclone "$tmp" 90; then
    rm -f "$tmp"
    die "Fclone 下载失败"
  fi
  install -m 0755 "$tmp" /usr/local/bin/fclone || { rm -f "$tmp"; die "安装失败"; }
  rm -f "$tmp"
  ok "Fclone 已安装：/usr/local/bin/fclone"
  fclone version 2>/dev/null | head -n 1 || true
}

