# Nginx：静态站点容器

app_nginx_install() {
  docker_require || return 1
  local dir
  dir=$(app_data_dir nginx)
  mkdir -p "$dir/html"
  if [[ ! -f $dir/html/index.html ]]; then
    cat >"$dir/html/index.html" <<'HTML'
<!doctype html>
<html lang="zh-CN">
<head><meta charset="utf-8"><title>STBOX</title></head>
<body style="font-family:system-ui;padding:40px">
<h1>Nginx 已就绪</h1>
<p>站点目录：data/apps/nginx/html</p>
</body>
</html>
HTML
  fi
  cat <<YAML | app_compose_up nginx || return 1
services:
  nginx:
    image: nginx:alpine
    container_name: sst-nginx
    restart: unless-stopped
    ports:
      - "80:80"
    volumes:
      - ./html:/usr/share/nginx/html:ro
YAML
  ok "Nginx 已启动：http://$(get_public_ip):80"
  info "修改页面：$dir/html/index.html"
}

app_nginx_remove() {
  app_compose_down nginx || return 1
  info "容器已移除，站点文件仍保留在 data/apps/nginx/html"
}

# --- app: npm ---
APP_TITLE="Nginx Proxy Manager"
APP_DESC="可视化反向代理与 SSL 证书管理"
APP_CATEGORY="面板"
APP_PORT="81"
APP_URL="http://IP:81"

SST_APP_TITLE['npm']=$APP_TITLE
SST_APP_DESC['npm']=$APP_DESC
SST_APP_CATEGORY['npm']=$APP_CATEGORY
SST_APP_PORT['npm']=$APP_PORT
SST_APP_URL['npm']=$APP_URL
SST_APP_DIR['npm']=''
SST_APP_ORDER+=('npm')

# --- apps/npm/app.sh ---
# Nginx Proxy Manager：图形化反代与证书管理

app_npm_install() {
  docker_require || return 1
  app_compose_up npm <<'YAML' || return 1
services:
  npm:
    image: jc21/nginx-proxy-manager:latest
    container_name: sst-npm
    restart: unless-stopped
    ports:
      - "80:80"
      - "81:81"
      - "443:443"
    volumes:
      - ./data:/data
      - ./letsencrypt:/etc/letsencrypt
      - /etc/localtime:/etc/localtime:ro
YAML
  ok "Nginx Proxy Manager 已启动：http://$(get_public_ip):81"
  info "默认账号 admin@example.com / changeme，首次登录会要求修改"
  warn "占用宿主机 80/443 端口，请勿与其他建站环境同时部署"
}

app_npm_remove() {
  app_compose_down npm || return 1
  info "容器已移除，data/letsencrypt 数据仍保留"
}

